window.__D("text/likkutei-sichot/c104",{"p":[[1300161134,"(ניט סתם רגיל) באלילים\" (ניט אין אן ענין בלתי רצוי סתם):\nמ'האט שוין געלערנט אין פ' וארא39, אז צאן איז געווען די עבודה זרה פון מצרים. קומט אויס, אז דאס עצם נעמען פון א שה — „יראת מצרים\"40 — צוליב „ושחטו אותו\", דאס גופא האט זיי אפגעריסן פון ע\"ז41, ויתרה מזה — באופן פון לשחטו, היפך לגמרי פון „שטופים באלילים\". וכדלקמן.\nדערמיט וועט מען אויך פארשטיין פארוואס די לקיחת השה האט געמוזט זיין ארבעה ימים פאר דער שחיטה:\nוויבאלד אז אידן (האבן ניט בלויז איין מאל געדינט ע\"ז, נאר זיי) זיינען גע־ווען „שטופים\" באלילים — האט גע־דארפט זיין א פעולה וואס זאל עוקר זיין דעם „שטופים\". ווען מ'וואלט גענומען דעם שה און גלייך גע'שחט'ן — און איין מאליקע פעולה — וואלט עס נאך ניט געווען גענוג זיי אפצורייסן פון זייער שטוף זיין אין ע\"ז; דוקא דורך דעם וואס זיי האבן געהאט ביי זיך דעם שה (יראת מצרים) א משך זמן, על מנת צו שחט'ן אים42, דאס האט געקענט מבטל זיין זייער פריערדיקע „שטופים באלילים\".\nאון דערפאר האט עס געמוזט גע־דויערן פיר טעג — ווי רש\"י האט שוין\nפריער מפרש געווען, ביי דער עקידה43, אז דאס וואס דער אויבערשטער האט באוויזן אברהם'ן דעם מקום העקידה ערשט „ביום השלישי\", איז עס געווען „כדי שלא יאמרו הממו וערבבו פתאום וטרד דעתו ואילו הי' לו שהות להמלך אל לבו לא הי' עושה\".\nדאס הייסט, אז א סימן אויף א גע־וויסע זאך אז זי איז געטאן געווארן מיט ישוב הדעת וכו', איז ערשט ווען מ'ווארט איבער פיר טעג44 — כשם ווי ביי אברהם'ען, וואס דער „יום השלישי\" איז געווען דער פערטער טאג45 נאכן ציווי „קח נא את בנך גו'\"46 (ווארום דער „ויקם וילך אל המקום גו'\" איז געווען „בבקר\"47 נאכן ציווי).\nח. בכדי אז ביי א בן חמש למקרא זאל זיך בעסער אפלייגן מאמרו של רמב\"ח, אז ניט קוקנדיק אויף דעם וואס עס איז דא א „שבועה שנשבעתי לאברהם שאגאל את בניו\", דארפן אידן אנקומען צו „מצות להתעסק בהם כדי שיגאלו\"48,\nברענגט רש\"י אז דער בעל המאמר איז ר' מתיא בן חרש, און אט דעם מאמר — „הי' רמב\"ח אומר\", ער פלעגט עס כסדר איבערזאגן צו זיינע תלמידים — ווייל דאס איז געווען א ביאור אויף זיין הנהגה נמשכת:",[["39","39","ח, כב וברש\"י."],["40","40","לשון רש\"י שם."],["41","41","ראה גם אלשיך ואוה\"ת כאן. — ועפ\"ז מתורצת קושיית הבאר מים חיים (לאחי המהר\"ל) כאן ד„א\"כ יהי' להם ג' מצות\" (גם פרישת ע\"ז) — כי פסח ופרישת ע\"ז תוכנם ותועלתם בנדו\"ד היינו הך."],["42","42","ובפרט שהי' קשור עם מסנ\"פ, וכמש\"נ (וארא שם) „הן נזבח גו' ולא יסקלונו\". וראה מדרש שהובא בבעה\"ת (דלעיל הערה 13). טור או\"ח סי' תל ובב\"ח שם. וראה גם תיב\"ע כאן."],["43","43","וירא כב, ד."],["44","44","להעיר מרש\"י יתרו יט, טז: הוא יום ד'."],["45","45","כי בפשטות, „ביום השלישי\" היינו משיצא מביתו (כמ\"ש הראב\"ע שם. רמב\"ן שם, ג (בכמה דפוסי הרמב\"ן נשמטה תיבת „והולכים\"))."],["46","46","שם, ב."],["47","47","שם, ג."],["48","48","ובפרט שכבר פרש\"י לעיל (שמות ג, יב): ששאלת מה זכות יש לישראל שיצאו ממצרים . . עתידים לקבל התורה."]]],[1300161135,"די גמרא49 דערציילט אין סנהדרין אז די ישיבה פון רמב\"ח איז געווען אין רומי. בימיו זיינען געווען נאך ישיבות, אויך אין א\"י, אבער זיין ישיבה (וב\"ד) — די גרעסטע בימיו50 — איז געווען אין רומי דוקא.\nולכאורה: פארוואס האט ער גע־מאכט זיין ישיבה אין רומי51, א זאך וואס האט גורם געווען אז מ'זאל דארפן גיין פון אנדערע ערטער קיין רומי צו זיין ישיבה — ווי די גמרא זאגט דארט „צדק צדק תרדוף, הלך אחר חכמים לישי־בה... אחר ר' מתיא לרומי\", און ניט גע־מאכט זיין ישיבה אין א\"י52 (ע\"ד ווי ר' עקיבא וואס „אחר רבי עקיבא לבני ברק\"49 וכיו\"ב)?\nדערויף זאגט מען „הי' רמב\"ח אומר כו'\" — ער פלעגט כסדר מנחם זיין זיינע תלמידים אויף זייער געפינען זיך אין רומי, אז די גאולה איז אפהענגיק אין דעם אז מ'זאל אין (א מצב פון) רומי מאכן א ישיבה — געפינען א איד וואס איז אין א מצב פון רומי („ערום וערי'\") און אים מאכן אויס „רומי\" נאר א יושב בישיבה, און אין אן אופן פון „להת־עסק\"53 בהם\", דאס ווערט זיין עסק. און פאר דעם צוועק געפינט זיך זיין ישיבה אין רומי, אין מקום הגלות54, צו העלפן\nיענעם אידן און דורך דעם ברענגען די גאולה.\nט. פון דעם האט מען אויך — די הוראה לימינו אלה:\nזייענדיק אין דער טיפעניש פון גלות זה האחרון, גלות רומי, און וויסנדיק דעם פסק חז\"ל אז שוין בזמנם „כלו כל הקיצין\"55 — טענה'ן אידן: מ'איז שוין אין גלות באלד צוויי טויזנט יאר — וויפל איז דער שיעור צו מאטערן אידן אין גלות?!\nאויף דעם זאגט רש\"י, אויב מ'וואלט געדארפט ניט מער ווי ארויסגיין פון גלות, וואלט מען שוין לאנג פטור גע־וואָרן פון גלות; אבער דער אויבער־שטער וויל אז דער ארויסגיין פון יעדער אידן זאל ניט זיין אין אן אופן פון „ערום וערי'\", ער וויל אז מ'זאל האבן מצות וכו'.\nוע\"ד ווי ביי יצי\"מ, וואו ס'איז געווען די הבטחה „ואחרי כן יצאו ברכוש גדול\"56 — האבן אידן גע'טענה'ט, אז זיי זיינען גרייט צו מוותר זיין אויפן רכוש גדול אבי וואס גיכער ארויסגיין פון גלות57; אבער דער אויבערשטער האט געוואלט אז מ'זאל ארויסגיין ברכוש גדול מיט אלע פירושים שבזה58.\nועד\"ז ביי דער גאולה העתידה בק־רוב, וואס — כימי צאתך מארץ מצרים אראנו נפלאות59 — וויל דער אויבער־שטער אז מ'זאל ארויסגיין „ברכוש גדול\", מיט אלע פירושים שבזה.",[["49","49","לב, ב."],["50","50","הגהות מיימוניות הל' סנהדרין ספ\"ו."],["51","51","ובפרט ע\"פ פרש\"י ס\"פ וישלח."],["52","52","ובפרט שכשיצא רמב\"ח לחו\"ל קרע בגדיו (ספרי ראה יב, כט)."],["53","53","ראה ב\"ח לטאו\"ח סמ\"ז ד\"ה ונוסחא. סד\"ה אריב\"ל כו' נכסיו, תרפ\"ח."],["54","54","להעיר שר' מתיא ניצוץ יוסף הצדיק (הובא בסה\"ד בערכו) — והרי ענינו של יוסף לכלכל את בנ\"י במצרים, וממנו בא הכח לעבודת הבירורים ו(במילא) גאולת מצרים (ראה בארוכה לקו\"ש ח\"ג ע' 831 ואילך)."],["55","55","סנהדרין צז, ב."],["56","56","לך טו, יד."],["57","57","ברכות ט, ריש ע\"ב."],["58","58","מתחיל בונצלתם את מצרים כפשוטו ועד — לכל ניצוצי קדושה שהיו שם. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370271\" data-slug=\"torah-or\" data-id=\"3901370271\">תו\"א (פרשתנו ס, ג</a>) שהעלו משם ר\"ב ניצוצים מהרפ\"ח שנפלו כו'."],["59","59","מיכה ז, טו."]]],[1300161136,"יו\"ד. און דאס איז אויך איינער פון די רמזים אין דער פרשה אויפ'ן יום ההילולא פון כ\"ק מו\"ח אדמו\"ר — יו\"ד שבט — וואס זיין הסתלקות איז געווען בשבת פ' בא60:\nדער רבי האט זיך אליין משתדל גע־ווען בהפצת התורה ומצותי' ביז צו מסירת נפש, און ביז צו פארשפרייטן קיום מצות מעשיות צווישן יעדער סוג אידן, ביז צו מתעסק זיין זיך בזה מיט אן איינצעלנעם אידן, כמפורסם כו\"כ סיפורים אין דעם,\nאון אין אן אופן — ווי ער האט גע־טייטשט אין א שיחה61 — „כי תראה ערום וכסיתו ומבשרך לא תתעלם, אז מיא זעהט א אידן א נאקעטען אהן ציצית און אהן תפילין, וכסיתו\" [ע\"ד ווי ר' מתיא בן חרש זאגט — „ואת ערום וערי' ונתן להם שתי מצות\"62];\nאון צוליב דער עבודה האט ער גע־האט זיין ישיבה דוקא אין חוץ לארץ,",[["60","60","לפני שלשים שנה* — שנת ה'שי\"ת — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021315\" data-slug=\"likkutei-sichot\" data-id=\"1300021315\">לקו\"ש (ח\"ב ע' 591</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041322\" data-slug=\"likkutei-sichot\" data-id=\"1300041322\">ח\"ד ע' 1323</a> ואילך) ביאור ענין ד'שלשים שנה. וראה לקוטי לוי\"צ אגרות ע' רעז."],["61","61","פורים תרצ\"א (לקו\"ד ח\"ד תשכט, א). והוא ע\"פ תדבא\"ר פכ\"ז."],["62","62","כההמשך בתדבא\"ר שם — „וכן אתה מוצא . . שבמצרים . . ואת ערום וערי' . . שנתרוקנים מן המצות ואין בך אלא שתי מצות אחת דם פסח ואחת דם מילה\". *) שיחה זו י\"ל בשנת תש\"מ. המו\"ל. בתוך הגולה63, און דארט גופא — בתוך העיר, אין „קול המונה של רומי\"64, אז דארט זאל מען אויפזוכן אידן וואס זיינען אין א מצב פון „ערום וערי'\" און געבן זיי איין מצוה, צוויי מצות וכו' „להתעסק בהם\" והולך ומוסיף ואור. — ווארום וויבאלד אז אין דער גאולה פון גלות זה האחרון וועט קיין איין און איינציקער איד ניט בלייבן אין גלות65 דארף מען אויפזוכן יעדן אידן, וואו ער זאל זיך נאר געפינען, און באווארענען אז ער זאל האבן לכל הפחות איין66 מצוה, ער זאל ניט זיין קיין „ערום\"67 — ווייל אין דעם הענגט אפ די גאולה פון גאנץ כלל ישראל. און דורך דעם וואס „נלכה באורחותיו נס\"ו68 אין אט דעם אופן, וועט דאס פועל זיין ומיד69 דעם — „(כדי ש)יגאלו\", והקיצו ורננו שוכני עפר והוא בתוכם, במהרה בימינו ממש. (משיחת ש\"פ בא תשל\"ז) ---"],["63","63","להעיר ממשנ\"ת (לקו\"ש ח\"ג ע' 835) ע\"ד כ\"ק מו\"ח אדמו\"ר ויוסף הצדיק (ראה לעיל הערה 54)."],["64","64","לשון הש\"ס — מכות בסופה."],["65","65","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011002\" data-slug=\"likkutei-sichot\" data-id=\"1300011002\">לקו\"ש ח\"א ע' 2</a> ואילך, וש\"נ."],["66","66","להעיר שבפרטיות יש בקיום דכל מצוה: סור מרע (— עבירה על רצון ה'), עשה טוב (— רצון ה')."],["67","67","ובפרט שמצוה גוררת מצוה (אבות פ\"ד מ\"ב). וגם המצוה ש„נגררה\" גוררת מצוה וכו'."],["68","68","לשון אגה\"ק סי' זך."],["69","69","ראה רמב\"ם הל' תשובה (פ\"ז ה\"ה) ומיד הן נגאלין."]]],[1300161137,"<h3>בא ד</h3>\nא. בנוגע צום ציווי „ואכלו גו' בלי־לה הזה גו' ומצות גו'\" — אַז אין דער נאָכט פון ט\"ו ניסן, זייענדיק נאָך אין מצרים, האָבן אידן געדאַרפט עסן מצה — געפינט מען אַ דבר פלא, לכאורה:\nביי דעם ציווי אויף אכילת מצות לדורות (אין פ' ראה<sup data-n=\"2\">2</sup> זאָגט די תורה: „שבעת ימים תאכל עליו מצות לחם עוני כי בחפזון יצאת מארץ מצרים\", און פון דעם לערנט מען אַפ 3, אַז די מצה מוז זיין „לחם עוני\" דוקא — ניט קיין מצה עשירה; איז ווי־באַלד אַז ביי פסח מצרים, בפרשתנו, ווערט „לחם עוני\" ניט דער־מאָנט, איז משמע 4, אַז דעמאָלט האָבן אידן געקענט יוצא זיין דעם חיוב פון אכילת מצה אויך מיט מצה עשירה 5.\nעפ\"ז איז פאַרשטאַנדיק, אַז כאָטש ביי פסח דורות מוז די מצה זיין „לחם עוני\" דוקא, איז אָבער ביי גאולת מצרים גופא געווען אַן אַרט אויך פאַר מצה עשירה: אָבער דאָס גופא — ניט בעת דער יציאה פון מצרים (וואָרום דאָן האָבן אידן געגעסן „לחם עוני\"<sup data-n=\"6\">6</sup>, נאָר פאַר דער יציאה (און אלס הכנה דערצו).",[["1","1","פרשתנו יב, ח. וראה שם, יח."],["2","2","טז, ג."],["3","3","פסחים לה, א. שם לו, א. רמב\"ם הל' חו\"מ פ\"ה ה\"ב. פ\"ו ה\"ה. טושו\"ע או\"ח סתס\"ב ס\"א. שו\"ע אדה\"ז שם ס\"א, ס\"ו. סתנ\"ד ס\"ד."],["4","4","כי אף את\"ל שהציווי דלחם עוני נאמר בסיני (ראה חגיגה ו, ריש ע\"ב (וש\"נ). ועוד) — הרי מובן שציווי זה (וכל הציווים) דפ' ראה כו' לא נאמרו לפני הדיבור — במצרים."],["5","5","ולדעת המהר\"ל (גבורות ה' פמ\"ח) גם בפסח דורות — ב' הציווים [„בערב תאכלו מצות\" ו„לחם עוני\"] הם ב' מצות. ומי שיש לו רק מצה עשירה [שיש בה גם מים ויכולה לבא לידי חימוץ] יאכלנה בליל פסח לקיים עכ\"פ מצות בערב תאכלו מצות, אף שלא יקיים מצות לחם עוני (וכ\"כ בב\"ח לטאו\"ח סתע\"א. וראה אלי' רבה שם סק\"ח. פמ\"ג שם א\"א סק\"ה). אבל במג\"א (שם סק\"ה. וכ\"ה בח\"י שם סק\"ה. סתס\"ב סק\"ב) לא ס\"ל כן. וכ\"ה להלכה בשו\"ע אדה\"ז סתנ\"ה סל\"ג. סתע\"א ס\"ד־ה' •. •) לכאורה הי' אפשר לדחוק, שכוונתו במש\"ש (סעיף ד) „מצה עשירה דהיינו שעירב בה מי פירות\""],["6","6","ראה גבורות ה' (פנ\"א) דמש\"נ בהגדה „לחמא עניא די אכלו אבהתנא בארעא דמצרים\", הכוונה בזה • להמצות שאכלו בעת יציאתם ממצרים, עיי\"ש. וב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940037\" data-slug=\"or-hatorah-hb\" data-id=\"8159940037\">אוה\"ת</a> רד\"ה הא לחמא (ויקרא כרך ב' ע' תנג) דהמצה שנק' לחם עוני היינו מה שאכלו כשיצאו ממצרים (אבל עיי\"ש בסוף המאמר), ומכיון שלחם עוני שולל מצה עשירה, הרי מובן, שלא אכלו אז מצה עשירה. היא לעיסה שנילושה רק במי פירות (בלי מים), שאז גם להמהר\"ל מותר לאכלה בערב פסח מפני שאינה יכולה לבוא לידי חימוץ. אבל אינו. כי (נוסף לזה שא\"כ: (א) הול\"ל „היינו שנילושה במי פירות\" ולא „שעירב בה מי פירות\" (שמשמע שיש בה גם מים), ובפרט שמשנה מלשון הטור (וכדיוק הב\"ח) שם „שנילושה כו'\" (אבל ראה לשון אדה\"ז בסי' תמד ס\"ב: שנילושה כו' — ואולי לא רצה לשנות שם מלשון הטור, וסמיך על מה שיפרש במקומו בסי' תעא (שמציין שם) „דהיינו שעירב כו'\"). (ב) ועיקר: לא הו\"ל להזכיר כלל התיבות „מצה עשירה\" (שהרי הטעם שמותר לאכלה הוא (לא מפני שהיא „מצה עשירה\", כ\"א) מפני שאינה יכולה לבוא לידי חימוץ). אלא שבזה י\"ל דקאי על ריש סימנא, שהוא לשון הרא\"ש, טור וכו' (ובלאה\"כ צ\"ל כן — לתרץ כפל הלשון: עשירה, דהיינו כו')) — ממ\"ש בסעיף ה' „ואסור לאכלה בערב פסח\" מוכח שקאי במצה שיש בה גם מים, ומסעיף זה נלמד על הקודם (אף שבדוחק י\"ל — דלצדדין קתני). ובכל אופן — הרי מפורש בסימן תנה סל\"ג: קמח ומים (עיי\"ש). •) וידועה השקו\"ט והפירושים בזה — כו\"כ מהם הובאו בתו\"ש מילואים לכרך כב סימן ה' פרק א'. וראה לקמן הערה 39."]]],[1300161138,"<h3>בא ד</h3>\nב. פסח מצרים איז דער מקור ושורש אויף פסח (ומצה של) דורות — איז מובן, אַז דער ענין הנ\"ל ביי פסח מצרים (אַז אלס הכנה צו יצי\"מ איז דאָ אַ נתינת מקום אויף מצה עשירה) דאַרף זיין (דוגמתו) אויך אין פסח דורות:\nעס שטייט אין מרדכי 7, אַז „בזמן שביהמ\"ק קיים היו עושין כל הסדר אחר הסעודה ולא היו אוכלין מצת מצוה אלא לאחר שמלאו כריסן כו'\", און „בימיהם היו אוכלין מצה עשירה על סעודתן\" 8 (כדי אַז די ברכת המוציא פון דער סעודה זאָל ניט זיין אויף אַ מצה מיט וועלכער מ'וועט שפעטער — ביים סדר — מקיים זיין מצות אכילת מצה<sup data-n=\"9\">9</sup>.\nאון כעין זה געפינט מען אויך בזמן הזה (כאטש מ'פראוועט דעם סדר פאַר דער סעודה): דער דין איז, אַז ערב פסח (קודם שעה עשירית), הגם מ'טאר ניט עסן קיין מצה 10, איז אָבער „מותר לאכול מצה עשירה\" 11. וי\"ל, אַז דאָס גופא וואָס שו\"ע (תורה) איז מתיר לכתחילה בפשטות 12 צו עסן דאָן מצה עשירה, באווייזט, אַז ערב פסח (ווען מ'מאַכט די הכנות צו פסח ויצי\"מ) האָט תורה געגעבן אַן אַרט אויף מצה עשירה.\nג. אין דעם ציווי פון אכילת לחם עוני (הנ\"ל), איז דער פסוק מסביר דעם טעם הציווי — „כי בחפזון יצאת מארץ\nמצרים\" (ובמילא — „לא הספיק בצק להחמיץ\"<sup data-n=\"13\">13</sup>:\nאון ווי־באַלד אַז „לחם עוני\" איז שולל ניט נאָר חמץ 14, נאָר אויך מצה עשירה (כנ\"ל), איז מסתבר, אַז „כי בחפזון יצאת גו'\" איז אויך דער טעם פאַרוואָס מ'קען ניט יוצא זיין מיט מצה עשירה.\nדאַרף מען פאַרשטיין: מיט וואָס איז „בחפזון יצאת גו'\" אַ טעם אויף דעם וואָס מ'איז ניט יוצא מיט מצה עשירה?\nד. פון דעם זעלבן פסוק הנ\"ל (מהתחלתו) — „לא תאכל עליו חמץ שבעת ימים תאכל עליו מצות גו'\" — לערנט מען אַפ 15, אַז מ'קען יוצא זיין חובת מצה נאָר מיט „דברים הבאים לידי חימוץ\".\n[און די שייכות וטעם פון „כי בחפזון יצאת גו'\" אויף דעם דין — קען מען זאָגן בפשטות: ווי־באַלד אַז ביי פסח מצרים איז געווען אַ בצק וואָס האָט געקענט ווערן חמץ און נאָר מצד דעם „חפזון\" איז „לא הספיק .. להחמיץ\" — דאַרף אויך די מצה וואָס מ'עסט אלס זכר ליצי\"מ זיין „דברים הבאים לידי חימוץ\", און ס'מוז זיין 16 אַ סיבה צו מונע זיין דאָס, מ'דאַרף עס היטן פון חימוץ, זכר ליצי\"מ — אויפן פרט פון „בחפזון יצאת גו'\"].\nאון היות אַז אויף די ביידע דינים — (א) מצה עשירה, (ב) דברים שאין באים",[["7","7","סוף פסחים בדיני הסדר בשם רבינו מאיר. ופליג בזה על הרמב\"ם הל' חו\"מ פ\"ח."],["8","8","שם בסוף המס' (קיט, ב)."],["9","9","ראה פסחים קטו, רע\"א (לענין מרור)."],["10","10","ירושלמי פסחים ר\"פ ערבי פסחים (הובא בתוד\"ה לא יאכל — פסחים צט, ב). רמב\"ם הל' חו\"מ ספ\"ו. טושו\"ע או\"ח סתע\"א ס\"ב. שו\"ע אדה\"ז שם ס\"ד."],["11","11","טושו\"ע שם. שו\"ע אדה\"ז שם."],["12","12","ראה תוד\"ה לא יאכל שם (בסופו): אבל מצה עשירה שריא וכן הוי' נוהג ר\"ת. הג\"מ הל' חו\"מ ספ\"ו. ועוד."],["13","13","רש\"י עה\"פ."],["14","14","ראה ריטב\"א להגש\"פ פי' הא לחמא. גבורות ה' רפנ\"א. ועוד."],["15","15","פסחים לה, א. רמב\"ם שם פ\"ו ה\"ד. שו\"ע אדה\"ז או\"ח ר\"ס תנג."],["16","16","וכמש\"נ ושמרתם את המצות. וראה שו\"ע אדה\"ז חאו\"ח סתנ\"ג, ס\"ד. וראה לקמן בפנים ובהערה 20."]]],[1300161139,"<h3>בא ד</h3>\nלידי חימוץ — זאָגט דער פסוק דעם זעלבן טעם („כי בחפזון יצאת גו'\"), איז דערפון פאַרשטאַנדיק, אַז די צוויי סוגי מצה הנ\"ל, האָבן, בכללות, דעם זעלבן חסרון לגבי יוצא זיין מיט זיי דעם חיוב פון אכילת מצה.\nלאידך גיסא געפינט מען, אַז כאָטש דער דין פון מצה עשירה איז געזאָגט געוואָרן ערשט ביי פסח דורות (כנ\"ל סעיף א'), איז אָבער אויך ביי פסח מצרים שוין געווען דער (כללות ה)דין, אַז די מצה פון ליל פסח מוז זיין (פון אזאַ בצק וואָס) „יכולה לבוא לידי חימוץ\" 17 — ווי מען לערנט עס אַפ (אין ירושלמי<sup data-n=\"18\">18</sup> פון פסוק 19 „ושמרתם את המצות\", אַז מ'איז יוצא נאָר מיט „מצה שצריכה שימור\" 20. ד.ה. אַז כאָטש ביי פסח מצרים האָט מען געקענט יוצא זיין אכילת מצה מיט מצה עשירה — האָט עס אָבער געדאַרפט זיין אזא, וואָס „צריכה שימור\" [לדוגמא: דורך אריינ־\nמישן וואַסער מיט די מי פירות, וואָס דאָן איז די עיסה באה לידי חימוץ, ואדרבה — ממהרת להחמיץ 21].\nה. דער ביאור בכל זה (ע\"פ פנימיות הענינים) וועט זיין פאַרשטאַנדיק דורך הסברת החילוק צווישן „לחם עוני\" און מצה עשירה בעבודה:\n„לחם עוני\" איז פון אַ טייג וואָס האָט בלויז קמח ומים — וואָס מים האָבן ניט (און גיבן ניט) קיין טעם: מצה עשירה איז פון אַן עיסה וואָס ווערט געקנאָטן מיט יין, שמן, דבש 22 (אדער אנדערע מי פירות<sup data-n=\"23\">23</sup>, וואָס גיבן אַ טעם אין דער עיסה.\nדער ענין אין עבודה 24: „לחם עוני\" איז די עבודה פון קבלת עול (ניט מצד „געשמאַק\"): כאָטש ער האָט ניט קיין הסברה בשכלו און (במילא) ניט קיין געשמאַק אין עניני אלקות, פונדעסט־וועגן דינט ער דעם אויבערשטן מצד קבלת עול; „מצה עשירה\" איז די עבודה מצד טעם ודעת, וואָס אין דער עבודה איז פאַראַן אַ „טעם\", אַ געשמאַק.",[["17","17","לשון אדה\"ז שו\"ע סתנ\"ב סוס\"א. — והיינו, לא רק שהדגן צ\"ל „מדברים הבאים לידי חימוץ\" (שזה נלמד מ„לא תאכל עליו גו'\" כנ\"ל בפנים), אלא שגם העיסה צ\"ל — זו שיכולה לבוא לידי חימוץ וצריכה שימור •, כמשנ\"ת בארוכה בהגש\"פ עם לקוטי טעמים מנהגים וביאורים (קה\"ת תשמ\"ו־ז) ע' שצז ואילך (וש\"נ)."],["18","18","פסחים פ\"ב ה\"ד."],["19","19","פרשתנו יב, יז (היינו שנצטוו ע\"ז עוד בהיותם במצרים)."],["20","20","עיין רמב\"ן במלחמת ה' פסחים פ\"ב (לו, א). וראה מ\"מ הל' חו\"מ פ\"ו ה\"ה (הובא בב\"י לטאו\"ח סתס\"ב ד\"ה ומ\"ש ואם לש). שו\"ע אדה\"ז הנ\"ל. וראה בארוכה שו\"ת צ\"צ חאו\"ח סנ\"ז אות ב' — שגם הבבלי (פסחים מ, א. הובא בשו\"ע אדה\"ז סתנ\"ג סי\"ד) ס\"ל דרשה זו דירושלמי. וראה בארוכה הגש\"פ הנ\"ל שם. •) ומ\"מ צריך גם הלימוד ד„לא תאכל גו'\" — שאין יוצאין במצה של טבל אף שצריכה שימור — ראה הגש\"פ הנ\"ל שם. ועוד י\"ל. ואכ\"מ."],["21","21","ראה בכ\"ז טושו\"ע או\"ח סי' תסב ס\"ב. שו\"ע אדה\"ז שם ס\"ג."],["22","22","לשון הגמרא — פסחים לה, א. לו, א. וברמב\"ם שם (פ\"ה ה\"ה) מוסיף „חלב\". והוא ע\"פ עובדא דריב\"ל (פסחים לה, א) — ב\"י סתס\"ב שם."],["23","23","ברמב\"ם שם (פ\"ה ה\"ה) דבשאר מי פירות יוצאין י\"ח (וראה כס\"מ שם פ\"ה ה\"ב). אבל ראה ב\"י לטאו\"ח סתס\"ב שם: לא ראיתי לשום אחד מהפוסקים שחילק בין יין ושמן ודבש והלב לשאר מי משקין. וראה פר\"ח או\"ח ר\"ס תסב."],["24","24","בהבא לקמן — עיין תוא\"א ס\"פ ויקהל ד\"ה קחו (פט, ג. צ, ב), וביאוריו בתוא\"ה שם בהוספות (קיד, ג ואילך. קטו, ד. קטז, ב). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830165\" data-slug=\"or-hatorah-hb\" data-id=\"8158830165\">אוה\"ת שם (ע' ב'קסג</a> ואילך. ב'קעא ואילך. ב'קפא). אוה\"ת ד\"ה הא לחמא (דלעיל הערה 6) ע' תנח ואילך. וראה ג\"כ <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380100\" data-slug=\"likkutei-torah\" data-id=\"4001380100\">לקו\"ת ויקרא ו, סע\"ג</a> ואילך."]]],[1300161140,"<h3>בא ד</h3>\nבשעת די עבודה פון אַ אידן איז נאָר מצד קבלת עול אָן דעם „טעם\" פון שכל ומדות, איז ער דאָך אין אַ מצב אַז מצד שכל ומדות איז ביי אים דאָ אַן אַרט אויף ניט טאָן אזוי, אויף רע, נאָר מיטן כח פון קבלת עול איז ער כופה דעם רע (אתכפיא) און איז עובד הוי'; ווען די עבודה איז אָבער מצד טעם ודעת (ובשלימותה), זיינען שכל ומדות שולל די אפשריות צו טאָן היפך רצון העליון — ס'איז ניטאָ קיין רע (אתהפכא).\nאון דאָס איז דער קשר צווישן די צוויי סוגי מצה [(א) מצה עשירה (ב) פון דברים שאין באים לידי חימוץ] — ווייל, בפנימיות הענינים, איז איין פרט אַ תוצאה פון צוויטן: עבודה אין אַן אופן פון „מצה עשירה\" (בשלימותה) — מצד שכל ומדות — איז שולל בדרך ממילא די אפשריות אויף חימוץ ורע 25 [ווי מצה עשירה כפשוטה, וואָס (ע\"ד הרגיל<sup data-n=\"26\">26</sup> קען זי ניט קומען לידי חימוץ]:\nדוקא (די עבודה פון) „לחם עוני\" — קבלת עול — גיט אַן אַרט אויף חמץ ורע (יכול לבוא לידי חימוץ), נאָר מ'איז כופה דעם רע און מ'דערלאָזט ניט צו התפשטות הגבהה וחימוץ — דורך „ושמרתם\", עבודה והתעסקות.\nו. די צוויי אופני עבודה זאָגן זיך אַרויס, בכללות, אויך אין די צוויי אופנים כלליים פון גאולה — גאולת מצרים און גאולה העתידה:\nביי יציאת מצרים שטייט 27 „כי ברח\nהעם\" (חפזון), ווייל „הרע שבנפשות ישראל עדיין הי' בתקפו 28, און דעריבער האָט מען געמוזט אנטליפן פון רע („טומאת מצרים\"<sup data-n=\"28\">28</sup> — וואָס דאָס איז דער ענין פון „לחם עוני\", די עבודה פון אתכפיא; משא\"כ לעתיד לבא וועט זיין „לא בחפזון תלכו 29, ואת רוח הטומאה אעביר מן הארץ\" 30, אַ מצב פון אתהפכא — מצה עשירה.\nאון דאָס איז דער ביאור וואָס „בחפזון יצאת גו'\" איז אַ טעם פאַרוואָס די מצה פון ליל פסח קען ניט זיין קיין מצה עשירה (און ניט פון דברים שאין באים לידי חימוץ): ווי־באַלד אַז „בחפזון יצאת גו'\", ווייל דער רע איז נאָך געווען בתקפו (כנ\"ל) 31, דעריבער פאַדערט זיך די עבודה פון קבלת עול ואתכפיא — „לחם עוני\" דוקא 32.\nז. דאָס וואָס מ'איז פסח ניט יוצא מיט מצה עשירה, איז ניט נאָר ווייל איר ענין איז ניט בדומה צו גאולת מצרים, וואָס איז געווען אין אַן אופן פון „ברח העם\" [קבלת עול ואתכפיא כנ\"ל] — נאָר אויך דערפאַר וואָס אין לחם עוני (און אזוי אויך — בגאולת מצרים) איז פאַראַן אַ יתרון לגבי מצה עשירה (והגאולה דלעת\"ל):\nכאָטש 33 אַז ביי אתהפכא (מצה עשירה) ווערט דער רע אינגאַנצן בטל, איז אָבער דאָ אַ מעלה אין אתכפיא, וואָס",[["28","28","<a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א</a>."],["29","29","ישעי' נב, יב. וראה המשך וככה דלקמן הערה 31."],["30","30","זכרי' יג, ב."],["31","31","ראה בענין דה„חפזון\" — <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380227\" data-slug=\"likkutei-torah\" data-id=\"4001380227\">לקו\"ת אמור לה, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380314\" data-slug=\"likkutei-torah\" data-id=\"4001380314\">במדבר א, ג</a>. ובארוכה — אוה\"ת בא ע' רצא ואילך. וככה תרל\"ז בתחילתו, שם פקכ\"ט. ד\"ה כי בחפזון תש\"ח (והמשכו). ועוד."],["32","32","ראה עד\"ז אוה\"ת סד\"ה הא לחמא הנ\"ל."],["33","33","ראה בכ\"ז במקומות שנסמנו בהערה 24."],["25","25","ראה תו\"א ס\"פ ויקהל (ועד\"ז — בשאר המקומות דלעיל הערה הקודמת): מצה עשירה .. שאינה באה לידי חימוץ כלל."],["26","26","דכשאין מערבין בה מים — מי פירות (לבד) אין מחמיצין (פסחים לה, ריש ע\"ב. וש\"נ. רמב\"ם הל' חו\"מ פ\"ה ה\"ב. טושו\"ע (ושו\"ע אדה\"ז) סי' תסב)."],["27","27","בשלח יד, ה."]]],[1300161141,"<h3>בא ד</h3>\nדוקא די עבודה איז פאַרבונדן מיט יגיעת האדם, צו לוחם זיין מיטן מנגד און נייטען דעם רע.\nאין אַן אַנדער סגנון: דער ענין פון אתהפכא דריקט אויס ווי דער מענטש ווערט מיוחד מיט אלקות דורך דעם וואָס ער איז זיך מזכך ביז אַז זיין מציאות לאָזט ניט קיין אַרט אויף רע; אין אתכפיא דריקט זיך אויס דער ביטול און אוועקלייג צו אלקות — אַז כאָטש מצד זיין שכל ומדות איז דאָ אַן אַרט אויף רע, נייט ער זיך, ער טוט היפך ווי עס מאָנט זיך מצד זיין מציאות, און איז מקיים דעם רצון העליון.\nאון דאָס איז איינער פון די ביאורים וואָס אויך ביי דער גאולה העתידה וועט זיין דער זכר פון יציאת מצרים 34 — ווייל דער תכלית הכוונה איז, אַז עס זאָלן זיין ביידע מעלות: אויך ווען מ'האַלט ביי אתהפכא — דער זיכוך פון דער מציאות האדם בתכלית ביז ס'איז אינגאַנצן ניטאָ קיין אַרט אויף רע — זאָל אויך זיין די מעלה פון אתכפיא 35 (גאולת מצרים), דער ביטול פון דעם אדם, וואָס דריקט זיך אויס אין עבודה ויגיעה.\nח. דער אלטער רבי איז מסביר אין תו\"א 36, אַז דאָס וואָס עס שטייט ביי גאולת מצרים „ואנכי אעלך גם עלה\" 37 — צוויי עליות — מיינט דאָס אויך די\nצווייטע עלי' וואָס וועט זיין בגאולה העתידה:\nבמילא מובן, אַז (פונקט ווי דער ענין פון גאולת מצרים וועט מען „דער־מאָנען\" — ער וועט ווירקען — ביי דער גאולה העתידה, אזוי איז אויך לאידך גיסא, אַז אויך) ביי גאולת מצרים דאַרף זיך אנהערן די (הבטחת ודיבור 38 הקב\"ה בנוגע דער) גאולה העתידה.\nדי הסברה אין דעם: ווי אזוי קען מען פועל'ן ביי זיך, אַז אויך ווען דער רע איז בתקפו [און אפילו נאָכן ברעכן זיך בלייבט ווייטער דער רע בתקפו (ווי ביי יצי\"מ, וואָס עס האָט געדאַרפט זיין „ברח העם\")] — זאָל מען האָבן די שטאַרקייט צו לוחם זיין מיטן רע (ולנצחו) — איז מסייע בזה די הכרה והרגשה, אַז סו\"ס וועט די עבודה פון אתכפיא ברענגען צו אתהפכא.\nאון דעריבער, נאָך איידער עס הייבט זיך אַן גאולת מצרים, איז געווען דער דיבור והודעה וועגן ביידע עליות — „אעלך גם עלה\" — אויך די גאולה העתידה.\nט. דאָס וואָס מ'דערמאָנט די גאולה העתידה ביי גאולת מצרים מיינט ניט נאָר אַז מ'איז מודיע אַן ענין וואָס וועט זיין בעתיד, נאָר ס'איז אויך אַ נתינת כח אראפצוטראגן דאָס אין עבודת האדם בהווה — און גלייך בתחילת העבודה (גלות מצרים) זאָל זיין אַ „מעין\" פון גאולה העתידה.\nלכאורה קען מען פרעגן: ווי־באַלד מ'האַלט נאָך בתחילת העבודה און דער רע איז נאָך בתקפו — ווי קען זיין (אפילו) אַ „מעין\" פון גאולה העתידה,",[["34","34","משנה ברכות ספ\"א. ונאמר „כימי צאתך מארץ מצרים אראנו נפלאות\" (מיכה ז, טו), „כאשר היתה לישראל ביום עלותו מארץ מצרים\" (ישעי' יא, טז)."],["35","35","ראה סד\"ה כימי צאתך תש\"ח: בחפזון יצאת למען תזכור כו', ועד\"מ ענג המלך בנצחון דוקא .. כד אתכפיא סט\"א כו'."],["36","36","ר\"פ שמות."],["37","37","ויגש מו, ד. ובתו\"א הנ\"ל: וכן בשמות ג' פסוק י\"ד א\"ל ענין הגאולה האחרונה כו'."],["38","38","דחשיב מעשה (ב\"ר פמ\"ד, כב. ועוד)."]]],[1300161142,"<h3>בא ד</h3>\nוואָס ענינה איז אתהפכא (אַז ס'איז ניטאָ קיין רע) ?\nאיז דער ביאור אין דעם: כאָטש אַז בתחילת העבודה איז ניטאָ דער ענין פון ביטול (מציאות) הרע, וואָס דערפאַר איז די עבודה בדרך מלחמה וקבלת עול (כנ\"ל סעיף ה') — דאַרף אָבער דער ביטול וקב\"ע זיין ניט (נאָר) בדרך הכרח, נאָר מ'דאַרף דעם ביטול גופא „פאַר־בינדן\" מיט „מציאות\" האדם — אַז אויך זיין שכל ומדות זאָלן „מסכים\" זיין אויף דעם ביטול וקב\"ע, וואָס דאָן איז זיין עבודה פון קבלת עול מיט אַ געשמאַק.\nד.ה. אַז די גאולה העתידה שבגאולת מצרים איז ניט די עבודה פון שכל ומדות בפו\"ע [וואָס ברענגט סו\"ס צו אתהפכא, כנ\"ל ס\"ה] — נאָר אַ פרט אין עבודת האתכפיא (דגאולת מצרים), אַז די עבודה פון קב\"ע איז מתוך תענוג.\n[און עד\"ז איז אויך דער ענין פון גאולת מצרים וואָס וועט דערמאָנט ווערן לעתיד לבא — איז עס אַ „פרט\" אין דער גאולה העתידה: דער עיקר העילוי לעתיד איז — זיכוך מציאות האדם (אתהפכא); נאָר דער זיכוך וועט זיין מדוד ומוגבל בלויז אויף אזויפיל ווי ויפל ער (מצד זיין „מציאות\") איז מזכך, נאָר מער פון די מדידות פון זיין מציאות (מעלת הביטול)].\nיוד. דאָס איז אויך די הסברה פאַר־וואָס די מצה וואָס אידן האָבן געגעסן אין מצרים (אלס הכנה צו יציאת מצרים) האָט געקענט זיין מצה עשירה 39, אָבער,\nלאידך גיסא, האָט עס געמוזט זיין אַ „מצה שצריכה שימור\":\nמצד דער התכללות פון גאולה העתידה אין גאולת מצרים, איז דאָ אַן אַרט פאַר מצה עשירה אויך אין מצרים; אָבער דאָס וואָס אין מצרים קען זיין אַ „מעין\" דלעתיד, איז נאָר אין דעם פרט פון „עשירה\" — אַז די קבלת עול גופא זאָל זיין מיט אַ „טעם\" און געשמאַק; אָבער ניט דער ענין פון אינה „יכולה לבוא לידי חימוץ\" (אתהפכא), וואָס דאָס קען ניט זיין ווען דער רע איז נאָך בתקפו.\nיא. דאָס איז אָבער שייך נאָר ווען מ'איז נאָך געווען אין מצרים, פאַר דער גאולה; אָבער אַרויסגייענדיק פון מצרים נאָך דער גאולה [און אזוי אויך די מצה וואָס מיר עסן בליל פסח, זכר ליציאת מצרים] מוז זיין „לחם עוני\" דוקא 40.\nדי הסברה בזה: דורך יציאת מצרים האָט זיך אויפגעטאָן אַז אידן זיינען געוואָרן אויס „עבדי פרעה\" און זיינען",[["39","39","באוה\"ת סד\"ה הא לחמא הנ\"ל איתא, דה„לחם עוני\" הוא המצה שאכלו לפני חצות, עיי\"ש [ועפ\"ז מבאר מש\"נ בהגדה „לחמא עניא די אכלו אבהתנא בארעא דמצרים\"], וכן מוכח ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370402\" data-slug=\"torah-or\" data-id=\"3901370402\">תו\"א שבהערה 24 (פט, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370511\" data-slug=\"torah-or\" data-id=\"3901370511\">קיד, ג</a>. עיי\"ש), וי\"ל ד„לחם עוני\" יש בו כו\"כ ענינים (כולל ג\"כ שעונים עליו דברים הרבה — פסחים לו, א. קטו, סע\"ב) ומצה עשירה כזו שצריכה שימור נק' ג\"כ (בכללות) „לחם עוני\" (מכיון שענינה אתכפיא — ענין עיקרי בלחם עוני). וראה הערה הבאה."],["40","40","ויל\"ע איך לתווך זה עם הידוע (לקו\"ת צו ד\"ה להבין מ\"ש בהגדה. ד\"ה ששת ימים (הא'). סדור ד\"ה והגדת. ובכ\"מ) דמצה [שלפני חצות היתה צריכה שימור ו]שלאחרי חצות (ואילך) לא היתה יכולה לבוא לידי חימוץ (מצד זה שנגלה עליהם ממה\"מ כו'), ובהמשך תער\"ב (ח\"ב ע' תתקלג) ש„היא בחי' מצה עשירה כו'\". ואולי י\"ל ע\"פ המבואר באוה\"ת ויקהל (ס\"ע ב'קסא־ב) דגם זה שלא הספיק כו' הוא „כמו בחי' אתכפיא רק שזהו בפנימיות\" (ראה לקמן בפנים, דיצי\"מ ענינה קבלת מלכות שמים, ביטול בתכלית), ולכן נק' ג\"כ — מצד ענין עיקרי זה — „לחם עוני\", מכיון שהוא רק אתכפיא ולא אתהפכא [שזה נעשה רק בספה\"ע כו'], כבהערה הקודמת."]]],[1300161143,"<h3>בא ד</h3>\nגעוואָרן „עבדי ה'\" 41. ד.ה. זיי האָבן דעמאָלט געהאַלטן ביי קבלת מלכותו ית' 42, וואָס קומט פריער פאַר דעם קבלת עול אויף צו מקיים זיין די ציווי ה' [וכלשון חז\"ל 43: יקבל עליו עול מלכות שמים תחילה ואח\"כ יקבל עליו עול מצות].\nאון אין דעם טאָר זיך ניט אריינמישן אַן ענין פון „מציאות\" האדם — ע\"ד ווי\nחז\"ל 44 זאָגן אַז מאן דמחוי במחוג קמי' מלכא איז זיין עונש דער היפך החיים: און דערפאַר טאָר אין דעם ניט זיין דער „טעם\" און געשמאַק פון מצה עשירה, ווייל קבלת מלכותו של הקב\"ה (ווערן עבדי ה') איז נאָר דורך „לחם עוני\" 45, ביטול בתכלית.\n(משיחות אחש\"פ וש\"פ שמיני תשכ\"ו)",[["41","41","ראה בהר כה, מב. שם, נה. מגילה יד, א."],["42","42","ראה ד\"ה הא לחמא הנ\"ל ע' תנג ואילך."],["43","43","משנה ברכות פ\"ב מ\"ב. וראה מכילתא יתרו כ, ג. ועוד."],["44","44","חגיגה ה, ב. וראה לקו\"ש ח\"ד ע' 1050 ובהערה 13 שם."],["45","45","ראה גם לקו\"ת שבהערה 24."]]],[1300161144,"<h3>בא — יו\"ד שבט —</h3>\nא. כ\"ק מו\"ח אדמו\"ר בעל ההילולא (פון היינטיקן שבת)¹ האט דערציילט² אז ווען זיין פאטער כ\"ק אדמו\"ר (מוהרש\"ב) נ\"ע „האט אנגעהויבן גיין אין חדר האט נאך דער רבי „צמח צדק\" געלעבט און ער האט אים דאן (ביים אריינ־פירן אין חדר) צוגעווארפן צוקערקעס און דערביי געזאגט, אז מלאך מיכאל האט אים דאס געווארפן. איז דאס ביי אים אין זייער נתקבל געווארן און ער האט ניט געוואלט אויפעסן די צוקערקעס, ווייל זיי זיינען ביי אים געווען זייער טייער. ערב פסח איז געווען דער מנהג³ בודק צו זיין די קעשענעס פון די קליינע קינדער, האט דער „צמח צדק\" גערופן דעם טאטן און האט אים געפרעגט וואו ער האט די צוקערקעס, האט ער זיי דעמאלט געמוזט אויפעסן\".\nפון אט דעם סיפור — ווי פון אלע סיפורים פון רבותינו נשיאינו, ובפרט א סיפור וועגן דעם וואס ס'האט פאסירט ביי זיי אליין — קען מען ארויסנעמען כמה הוראות; און ניט נאר אין ענין החינוך (ווי ער איז דארט מסיים „אט אזא חינוך דארפן מיר האבן\"), וואס איז מודגש בפרשתינו (בנוגע לפסח) „והגדת לבנך גו'\"⁴, „והי' כי ישאלך בנך גו'\"⁵, נאר אויך כמה עניני הלכות אין איסור חמץ (וכיו\"ב) וואס אויך וועגן דעם לערנט מען בפרשתינו⁶.\nב. לכאורה דארף מען פארשטיין וויבאלד די „צוקערקעס\" זיינען ביי אים (כ\"ק אדמו\"ר מוהרש\"ב נ\"ע) געווען אזוי טייער אז ער האט זיי ניט געוואלט אויפעסן — און זיי זיינען דאך טאקע געווען א דבר יקר, וויבאלד זיי זיינען געגעבן געווארן פון צמח צדק — פאר־וואס האט דער צמח צדק געוואלט בדווקא אז ער זאל זיי אויפעסן פאר פסח, און ער האט אים ניט געלאזט זיי אפהיטן אויף ווייטער דורך פארקויפן זיי צוזאמען מיט כל החמץ?\nובפרט, אז מען געפינט אזא הנהגה ביי גדולי ישראל בשייכות צו שיריים וואס זיי פלעגן באקומען פון א צדיק, אז אויב עס איז געווען א זאך וואס האט געהאט חמץ, האבן זיי דאס פארקויפט במכירת חמץ⁷.\nוויבאלד אז דער „צמח צדק\" האט אים דאס ניט געהייסן טאן, וואלט מען לכאורה געקענט מדייק זיין אז ער האט געהאלטן אז אין דעם פאל: א) איז דאס אסור היות ער וויל דאך די זאך צוריק־באקומען לאחר הפסח און ער איז רוצה בקיומו פון דעם חמץ⁸, ב) עס העלפט",[["1","1","שבת פ' בא, יו\"ד שבט, ה'שי\"ת. ולהעיר שהקביעות בשנה זו (תשל\"ז) היא כבשנת ההסתלקות."],["2","2","סה\"ש תש\"א ע' 30."],["3","3","ראה שו\"ע אדמוה\"ז סי' תלג סמ\"ב."],["4","4","יג, ח. וראה מכילתא ופרש\"י שם."],["5","5","שם, יד. מכילתא ופרש\"י שם. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071280\" data-slug=\"likkutei-sichot\" data-id=\"1300071280\">לקו\"ש ח\"ז ע' 268</a> ואילך."],["6","6","יב, טו. יט. כ. יג, ג ואילך."],["7","7","„רבינו הקדוש מראהטין זי\"ע הי' מוכר פ\"א גלוסקא יפהפי' מלחם הפנים של הה\"ק מהר\"ר יצחק אייזיק מזידיטשוב זי\"ע. וכן שמעתי כמה מהחסידים כשיש להם שירי מנחות מי\"ב חלות של צדיק כו' מוכרין אותו עד אחר פסח כו'\" (הובא בטעמי המנהגים עניני פסח ע' ריז בקו\"א)."],["8","8","ראה טור או\"ח סו\"ס תנ. וראה מנח\"י כלל פה סקט\"ו. אסר מטעם זה בשו\"ת ערוגת הבושם או\"ח"]]],[1300161145,"ניט קיין מכירה לעכו\"ם ווארום מכירת חמץ איז מותר כאטש דאס איז כהערמה [און מען האט בדיעה צוריקבאקומען דעם פארקויפטן חמץ לאחר הפסח — און מען מעג לכתחילה פארקויפן „לנכרי המכירו ומיודעו .. אע\"פ שהוא יודע בהנכרי שלא יגע בחמצו כלל אלא ישמרנו לו עד לאחר הפסח ואז יחזירנו לו\"⁹] ווייל דאס איז מדרבנן¹⁰, בנדו\"ד אבער איז די מכירה אן ענין פון הערמה ניכרת¹¹, ובמילא אין אזא פאל האבן די חכמים ניט מתיר געווען ע\"י מכירה¹².\nבאמת אבער קען מען אזוי ניט זאגן, ווארום א) דער אלטער רבי דערמאנט ניט אין שו\"ע¹³ דעם איסור „רוצה בקיומו\" ביי חמץ בפסח, ב) לדעת רוב הפוסקים ובפרט לדעת אדמו\"ר הזקן איז מכירת חמץ א מכירה גמורה באופן אז זי פארהיט אויך פון צו עובר זיין אויף ב\"י וב\"י (אויך) דאורייתא (ווארום דעם חמץ וואס מען פארקויפט איז ניט בכלל ביטול והפקר)¹⁴.\nג. לכאורה וואלט מען אינעם דער־ציילטן פאל געקענט געפינען אן אנדער עצה ווי צו האלטן גאנץ דעם חמץ, ניט אנקומענדיק צו מכירת חמץ לאינו יהודי: מפקיר זיין דעם חמץ (קודם זמן איסורו).\nאון כאטש אז (ביטול ו)הפקר ביי חמץ העלפט נאר מה\"ת אויף ניט צו עובר זיין בב\"י וב\"י, ווי מען לערנט עס ארויס פון ולא יראה לך „שלך אי אתה רואה אבל",[["","","סי' קיב בשאלה הנ\"ל („אחת מי\"ב חלות שהי' מונח על שלחן הטהור של כ\"ק אדמו\"ר הרה\"ק ר\"י מבעלזא זי\"ע וניתן לו והוא חביב בעיניו וכו' אם רשאי למכרו עם החמץ בשטר מכירה כו'\")."],["9","9","שו\"ע אדה\"ז סי' תמח ס\"ו משו\"ע שם ס\"ג. וראה שם ס\"ד (ואדה\"ז סי\"ז). ט\"ז שם סק\"ו (ואדה\"ז סכ\"ג „ונראה שכל אדם יאמר כן לעכו\"ם בפירוש ויועיל בזה ששום אדם לא יכול לקנות מהעכו\"ם\")."],["10","10","ראה בכור שור לפסחים כא, א. הובא במק\"ח סי' תמ סק\"ג. וראה שו\"ת צ\"צ או\"ח סמ\"ח (נדפס בהוספות לשו\"ע אדה\"ז ע' 42 [1348]), דלדעת אדה\"ז .. וכו' אי\"ז הערמה האסורה וכו', אבל הכא שזהו דרך מקח וממכר אין הערמה ניכרת. וראה פס\"ד להצ\"צ או\"ח לסי' תמה (לב, ב. נדפס בהוספות שם ע' 44 [1350]) דאף שכ' המג\"א דבדיעבד מהני אפי' לא מסר לו המפתח מ\"מ „כשהוא בעירו ואינו מוסר לו המפתח גרע טפי דהוה הערמה ניכרת\". ובפס\"ד (לב, ד. נדפס בהוספות שם כג, א [תרעו]) דהמכירה היא רק לצורך הפקעת איסור ב\"י וב\"י. ולהעיר משו\"ע אדה\"ז סי' תמח סוס\"ח."],["11","11","עדה\"ז פירש דברי הערוה\"ב בשו\"ת אבני זכרון ח\"ג סכ\"ה (אות ד')."],["12","12","ראה בכור שור ושאר המקומות שנסמנו בהערה 10."],["13","13","בס' תנ ס\"ב בהדין ד„אסור להשכיר לגוי כלי שמבשלין בו ע\"ג האור\" (שע\"ז כתב הטור הא דרוצה בקיומו (כנ\"ל הערה 8)), כ\"א כ' שם „יגיע לישראל הנאה מהחמץ\" (אף שכן פי' במג\"א שם (סקי\"א) דברי הטור „רוצה בקיומו\", אבל עכ\"פ מוכח מדברי אדה\"ז שהאיסור הוא מצד ההנאה)•. וכן דעת כמה פוסקים דלא אסרינן חמץ בפסח משום רוצה בקיומו — ראה פרמ\"ג סי' תנ סק\"ז. משא\"כ דעת המנח\"י (הנ\"ל בהערה 8) וישוע\"י הובא בשו\"ת ערוה\"ב שם. וראה שו\"ת חת\"ס או\"ח סקט\"ז בסופו. סי' קיט בתחלתו. מקו\"ח סי' תנ סק\"ז. וראה שו\"ת אבני זכרון שם אות ב' ואילך. שד\"ח מערכת חו\"מ ס\"ח אות כה (איקיד, א ואילך)."],["14","14","ראה הלכות מכירת חמץ (בסוף הל' פסח) לאדה\"ז. וראה לשון אדה\"ז בשו\"ע סתמ\"ח סכ\"ג. ובסכ\"ה „שהרי כבר נמכר לו לחלוטין\". ובסכ\"ג כ' „אין שום אדם יכול לקנותו מן הנכרי\", ולא הביא מ\"ש המג\"א שם סוסק\"ד „שאם קנה ישראל אחר החמץ מן העכו\"ם .. צריך להחזיר לבעלים\" ועד\"ז בט\"ז שם. ובח\"י סקי\"ד: ואם לקח צריך לחזור ולמכור לבעלים ראשונים (וראה מחה\"ש שם). ואכ\"מ (וראה מק\"ח סתמ\"ח סקי\"א). ובשו\"ע צ\"צ שם בסופו: ועוד\"ל ועיקר דאחר שאאזמר\"ר .. הצריך יהודי ערב קבלן .. אין זה הערמה. וראה שד\"ח מערכת חו\"מ ס' ט' אות טו (כרך ה' א'קנב) דמשמע מהפוסקים דהוי מכירה גמורה ולא הערמה ואשר כן ס\"ל גם להתבו\"ש. •) וראה בקו\"א סתמ\"ו סק\"ב מה שמבאר לדעת המנח\"י."]]],[1300161146,"אתה רואה של אחרים ושל הפקר\"¹⁵, אבער די חכמים האבן גוזר געווען אז (ביטול ו)הפקר איז ניט מספיק און מ'דארף דעם חמץ מבער זיין¹⁶ בפועל ממש — איז אבער אויך אויף דעם פאראן אן עצה:\nמען קען דאך מפקיר זיין דעם חמץ ניט נאר בלב (און עס זאל פארבלייבן אין זיין רשות) נאר ביים מפקיר זיין דעם חמץ זאל ער עס ארויסנעמען פון זיין רשות און אוועקלייגן ברה\"ר במקום הפקר ממש, אין אן ארט וואו עס גייען ניט קיין מענטשן (און דערנאך זוכה זיין דערין נאך פסח) —\nוואס לכאורה דערמיט איז מען באוואַרנט לויט ביידע טעמים צוליב וועלכע די חכמים האבן מתקן געווען אז ביטול והפקר אליין זאל ניט זיין גענוג: א) ביטול והפקר איז „תלוי במחשבתו של האדם\", איז מען חושש אז ער וועט דאס מפקיר זיין ניט „בלב שלם\"¹⁷, דעריבער דארף ער דאס ארויסנעמען פון זיין רשות¹⁸; אדער ב) מצד דעם\nטעם ווייל „האדם רגיל בכל השנה בחמץ ומחמת רגילותו קרוב הוא לשכחה שישכח את איסורו ו(אויב דאס וועט זיין „בגבולו\"¹⁹) יאכל ממנו\".\nאון מ'געפינט מפורש אז מען קען אזוי טאן לכתחלה: ארויסנעמען דעם חמץ מרשותו און אים מפקיר זיין, און אוועק־לייגן במקום הפקר לכל און לאחר הפסח זוכה זיין אין דעם²⁰ (וכמדומה",[["15","15","כן הוא בשו\"ע אדה\"ז סתל\"א סוס\"ב. ובמ\"מ על הגליון „ספרי תוס' שם ועיין ברא\"ש פ\"ק ס\"ד\", בספרי לפנינו (ראה טז, ד) אין מפורש „הפקר\". ובר\"מב\"ן ריש פסחים „שוב מצאתי בספרי .. לא יראה לך שאור אתה רואה בפלטיא\" (ולפנ\"ז ברמב\"ן שם הביא מירושלמי (פסחים פ\"ב ה\"ב) אבל אתה רואה בפלטיא), וכ\"ה במהר\"ם חלאוה פסחים ו, ב. — „בפלטיא\" הרי תוכנו שהפקירו. ובתוס' (ד, ב סד\"ה מדאורייתא) „מאחר שביטלו הוי הפקר ויצא מרשותו ומותר מדקאמרינן אבל אתה רואה של אחרים ושל גבוה כו'\"."],["16","16","משנה ריש פסחים ובגמרא ד, ב."],["17","17","ר\"ן ריש פסחים ד\"ה אלא כך. שו\"ע אדה\"ז שם ס\"ד."],["18","18","לשון אדה\"ז שם „עד שיוציא את החמץ מכל גבולו\", ולא כתב „לבערו\" (ע\"ד ל' הר\"ן „והצריכוהו בדיקה וביעור\"), ובפשטות כיון שאין כאן מקומו וציין במוסגר „עיין ס' תמה\" דשם מבואר בס\"א דקודם שעה ששית די לו במה שמבערו מרשותו דהיינו שימכרנו לנכרי כו' או להפקירו ולהניחו במקום הפקר."],["19","19","ל' אדה\"ז שם. והוא טעם התוס' ריש פסחים. ר\"ן שם. הובא גם בטור שם. ומסיים אדה\"ז „לפיכך הצריכו לחפש אחריו ולבדוק ולהוציא מכל גבולו\", ועד\"ז בטור „להוציא מן הבית\", אבל בתוס' לבדוק ולבערו. וראה הערה שלפנ\"ז."],["20","20","או\"ז בתשובה (סוף ח\"א) סי' תשמח. ח\"ב — הלכות פסחים סרמ\"ו (הובא בהג\"א פסחים פ\"ב ס\"ד). מהר\"ם ריקאנטי סי' קנז הובא בעו\"ש סרס תמז (ובאו\"ז ובריקאנטי דמותר אף באכילה). ובעו\"ש שם „ונראה דהאי הפקר אין צריך לא ב\"ד ולא לפני שלשה כו'\". ובשו\"ת פני' ח\"א ס\"ד קרוב לסופו, דהרקאנטי איירי „שמפקירו לגמרי לכל אדם ומוציאו לשוק .. וזה ממש כמו מכירה שלנו לגוי המכירו ויודע שישמור לו חמצו עד אחר החג ויחזור לו\"). שיירי כנה\"ג הובא בפרח\"ח סתמ\"ח סק\"ה (ולדעתו בהפקיר חמצו לפני עדים דוקא ואז מותר גם באכילה). ברכי יוסף סתמ\"ח סק\"ה בשם מגלת ספר (יכול להפקירו בפני ג'). ומדבריהם (שכנה\"ג וברכ\"י) מבואר שדי להפקירו אבל אי\"צ להוציאו מרשותו••. וראה פמ\"ג (א\"א) סתמ\"ח סק\"ח דכשהוציא החמץ מרשותו ואומר בכיון בפה שמפקיר הפקר גמור הוא אע\"פ שבלב חושב להיפוך בתר פיו אזלינן. ועוד. ולפי כל הנ\"ל הפי' בירושלמי (פסחים פ\"ב ה\"ב) הבקיר חמצו בי\"ג לאחר הפסח מהו ר\"י אמר אסור •) בד\"מ סי' תמה סק\"א כ': „שאף הא\"ז בעצמו כ' לבסוף וז\"ל ומותבינן כו'\". אבל בהג\"א (שבפנים ההערה) „והא\"ז כתב שמותר כו'\". וכ\"ה בפס\"ד להצ\"צ (לב, ד) „והא\"ז מתיר\". ••) וראה ד\"מ שם „ומשמע שם (מדברי האו\"ז) .. יכול להפקירו בפני אוהביו שבטוח בהן שלא יטלו כו' או שיפקירו ויניחו בשוק בזמן שאין ב\"א שם\"."]]],[1300161147,"שנמצא בספורי חיי כמה חסידים הנוהגים בקבלת שיריים (וכיו\"ב) שנהגו כן).\nדער טעם בפשטות וואס דער צ\"צ האט אזוי ניט געהייסן טאן: הגם מען געפינט אז לויט כמה דיעות²⁰ מעג מען מפקיר זיין פאר זמן איסורו (ובפרט במקום הפקר) מיט דער דיעה צו זוכה זיין אין דעם לאחר הפסח, אבער מ„שאר הפוסקים\"²¹ איז משמע אז דאס העלפט ניט²²; און אזוי פסק'נט דער אלטער רבי²³ „אפילו הניחו במקום המופקר לכל צריך שיפקירנו לגמרי בפיו ובלבו ולא יהי' בדעתו בשעת ההפקר לחזור ולזכות בו לאחר הפסח אם לא יקדמנו אחר שאם יש בדעתו כן אינו הפקר גמור והרי הוא כשלו ממש\".\nנאכמער: „אפילו חמץ שנמצא מושלך במקום הפקר שהשליכו שם ישראל קודם שעה ששית בע\"פ כדי שלא יעבור עליו בב\"י וב\"י בפסח .. שמותר לעשות כן לכתחלה מכל מקום לאחר הפסח\nאסור לכל אדם מישראל ליהנות ממנו\"²⁴.\nד. ס'איז אבער שווער צו זאגן אז דאס איז דער טעם בנדו\"ד: ראשית רעדט זיך דא וועגן „צוקערקעס\" וואס איז בכלל ניט ברור אויב ס'איז פאראן אין דעם חמץ; און אפילו אויב ס'איז דא,",[["","","כו' חשש להערמה, שיערימו לומר שהפקירו אע\"פ שלא הפקירו, וכמ\"ש ברא\"ש פ\"ב דפסחים ס\"ד. טור סי' תמח. ובמק\"ח שם בחידושים סקי\"ד. ואם הפקיר חמצו והניח במקום הפסד מותר אח\"פ, אבל אם העמידו במקום מוצנע ברה\"ר אסור (וראה ביאורים שם ססק\"ט)."],["21","21","ראה ד\"מ שם „מדלא כתבו שאר הפוסקים\"."],["22","22","אף שס\"ל שמותר לכתחלה להפקירו ולהניחו במקום הפקר קודם זמן איסורו (שלא ע\"מ לזכות בו) — ראה מ\"א סתמ\"ה ס\"ז. שו\"ע אדה\"ז שם ס\"א (וראה שם סתל\"ו סוס\"כ). ובשו\"ע אדה\"ז סתמ\"ח סכ\"ב „שמותר לעשות כן לכתחלה\"."],["23","23","סי' תמה ס\"ב. וראה המקורות וכו' בקו\"א שם. ושם, דלדעת הראם „עובר עליו בב\"י מן התורה\". וראה בארוכה בהנ\"ל ובפי' דברי הירושלמי בשד\"ח מערכת חו\"מ ס\"ח אות יז (ע' 2098 ואילך)."],["24","24","שו\"ע אדה\"ז סתמ\"ח סכ\"ט. ובקו\"א סתל\"ו סק\"י „שהניח חמצו ברה\"ר והפקירו קודם הפסח שהוא אסור בהנאה לאחר הפסח כדאיתא בירושלמי פ\"ב ה\"ב לפי פירוש האמיתי של המ\"א והפר\"ח וכמו שנת' בסי' תמח\". וגם מדבריו משמע (וכן ממ\"ש בסי' תמח שם „שאם יהא מותר בהנאה יש לחוש שמא יניח כל אדם חמצו עד לאחר הפסח ויאמר שהפקירו קודם הפסח כדי שנתיר לו ליהנות ממנו\") שבירושלמי מדובר בחמץ שנמצא אחר הפסח• והערמה שבירושלמי אינו שיפקיר ע\"מ לזכות בו, המבואר בסי' תמה ס\"ב, כ\"א „הפר\"ח הוציא זה מתשובות הרשב\"א (סי' ע') כו' וכ\"כ בעל חי\"י בספר תורת השלמים כו'\" — קו\"א סתמ\"ח שם. ולהלן בקו\"א שם מפרש כן ע\"פ הבבלי נדרים ומפרשים שם. ומשמע שזהו מדיני וגדרי הפקר. וצ\"ע ממ\"ש בהל' מכירת חמץ בתחילתו „חמץ הנמכר אינו בכלל ביטול והפקר מאחר שדעתו עליו לחזור ולזכות בו אחר הפסח כמבואר בתשובת הרשב\"א בשם הירושלמי (פ\"ב ה\"ב)\". וכ\"כ מפורש בשו\"ת פני' שם דהרשב\"א מפרש הערמה בירושלמי (דלא כהטור כו') שיכוין לחזור ולזכות בו אחר הפסח••. ובמק\"ח שם סקי\"ט ד\"ה לכן. שו\"ת תרי\"ח או\"ח סכ\"ב בתחלתו. וראה נוב\"י מהד\"ק או\"ח סי\"ח. שו\"ת חת\"ס או\"ח סקי\"ד (ומסיים „והמעיין בתשו' רשב\"א .. יראה להדיא שנתכוון לכל מה שכתבתי\"). וראה שו\"ת תרי\"ח שם (וס\"ט ואילך). שד\"ח שם. ואכ\"מ. •) גם ברה\"ר והפקירו בפני עדים כמ\"ש בס' תמה שם. משא\"כ בטור ושו\"ע ס\"ה הלשון „חמץ שנמצא בבית ישראל כו'\", ולפי\"ז כשנמצא ברה\"ר לכאורה מותר. וכ\"מ בשו\"ת פני' שם (ומק\"ח שם) דגם לפי' הרשב\"א בירושלמי במניחו במקום הפקר כו' מותר כנ\"ל הערה 20. וכ\"כ בביאורי הגר\"א סי' תלג ס\"ו (וכ' דאף באכילה מותר). ••) וכ\"מ במאירי פסחים ט, א. מגן אבות (להמאירי) ענין הי\"ח ד\"ה „וכן מה שהקשה בשמינית כו'\"."]]],[1300161148,"איז דאס נאר תערובות חמץ פון קודם הפסח וואס ווערט דאן בטל ברוב (אדער בס')²⁵ און ס'איז ניטא אין דעם קיין ב\"י וב\"י (מדאורייתא עכ\"פ)²⁶.\nועוד: דאס וואס אזא הפקר העלפט ניט איז דאך צוליב'ן טעם וואס יעדער מענטש וועט אזוי טאן כדי צו קענען הנאה האבן פון דעם חמץ לאחר הפסח²⁷; בנדו\"ד אבער, וויבאלד ער האט סיי ווי ניט בדיעה צו הנאה האבן פון די „צוקערקעס\" באיזה אופן שהוא,\nאפילו ניט דורך מכירה, ער האט זיי נאר געוואלט האלטן גאנץ²⁸ — און בצירוף לזה וואס דאס איז נאר א ספק דרבנן כנ\"ל, צי דער (תערובות) חמץ דארף בכלל האבן הפקר וביעור²⁹, ובפרט אז ס'איז אן ענין דלא שכיח — קען זיין אז אין דעם פאל האבן די רבנן מלכתחלה ניט גוזר געווען³⁰ אז אט דער הפקר זאל ניט מספיק זיין³¹.\n[און מ'קען ניט פרעגן אויף דער כללות השקו\"ט הנ\"ל, אז דער גאנצער ענין פון מכירה והפקר איז ניט שייך בנדו\"ד, וויבאלד אז עס רעדט זיך דא וועגן א חפץ פון א קטן וואס קען נאר קונה זיין (בדעת אחרת), אבער ניט",[["25","25","וראה שו\"ע אדה\"ז סתמ\"ז סי\"ח."],["26","26","להעיר מדין חמץ נוקשה כיון שלא עבר עליו בב\"י וב\"י מה\"ת אפילו באכילה שרי (שו\"ע סי' תמז ובמג\"א שם). ועי' מה שהביא במג\"א שם מהר\"ן. וראה שד\"ח שם סימן ח' אות יוד. ומ\"ש בפר\"ח סתס\"ז סק\"ט ובקו\"א סי' תלו (שהובא לעיל הערה 24) אף שלא עבר אפילו מד\"ס אסור בהנאה — ראה לקמן בפנים."],["27","27","בנוגע לחמץ לאחר הפסח וכמפורש בשו\"ע אדה\"ז סתמ\"ח סכ\"ט „שאם יהא מותר בהנאה יש לחוש שמא יניח כו' כדי שנתיר לו ליהנות ממנו\"• (וראה שו\"ת חת\"ס או\"ח סקי\"ד, אלא ששם מבאר זה לענין ביטול כשנשאר ברשותו). אבל כצ\"ל לענין לכתחלה בהפקר לפני הפסח המבואר בס' תמה••. וכן משמע מל' אדה\"ז סתל\"ו סי\"ח בדין דשו\"ת הרשב\"א „אבל חטים הללו כו' הי' בדעתו לחזור ולזכות בהם לאחר הפסח כשיפנה את האוצר (אם היינו מתירין לו ליהנות מהן לאחר הפסח) והרי זה דומה למבער את החמץ ומכוין לחזור ולזכות .. שאין זה ביעור גמור כמו שית' בס' תמה לפיכך אסרו חכמים להנות מהן לאחר הפסח\". וראה קו\"א שם סק\"ט. ובפרט עפ\"י מ\"ש בהל' מכירת חמץ בתחילתו (נעתק לעיל הערה 24). •) ועד\"ז הוא ברמב\"ם הל' חו\"מ פ\"א ה\"ד. ובשו\"ת פני' ס\"ג (ועוד) כ' שמקורו מהירושלמי הנ\"ל. וראה נו\"כ שם. ואכ\"מ. ••) וכמ\"ש בקו\"א שם ד„גזרי חכמים לענין מעשר שבת וחמץ\" במקום שיכול להיות הערמה. אף „שגזרו עליו חכמים אף במטלטלין דליכא הפקעת מעשר כו'\", הרי בנדו\"ד הוא מילתא דלא שכיחא כדלקמן בפנים."],["28","28","משא\"כ בנדון הפר\"ח סי' תסז שם „שנהנים מראות ידי אומד\"."],["29","29","ולפ\"ז י\"ל שזהו בדוגמת הנידון ברשב\"א שם, שכ' דגם לכתחלה ב„ביטול בעלמא סגי .. מפני שאין נודע ממש שיש שם חטים שנתבקעו .. ושמא אין שם כלל ואם נתבקעו שמא נפסדו לגמרי כו' והו\"ל ספק ספיקא (ואילו הי' ברור שיש שם חטים מבוקעות ונתיר אותו בביטול לכשיפנה אפשר שהי' צריך לבער כו' דהרי זה כמבטל ומתכוין לחזור ולמכרו לאחר הפסח כו')\". וע\"ש להלן „אלא שאפשר להתיר מן הצד שאמרתי כו'\". וראה פר\"ח שם שצידד להקל בנידון החיטה כיון שהוא ספק דרבנן. ובשו\"ע אדה\"ז סתל\"ו סי\"ט, ומסיים „וכל ספק חמץ שעבר עליו הפסח מותר בהנאה\" (אלא שבהנ\"ל מדובר לאחר הפסח)."],["30","30","ראה פסקי דינים להצ\"צ ח\"א לב, ד: עיקר דינא שכל שדעתו לחזור ולזכות בו אינו ביטול נראה שהוא רק מדרבנן. וראה מחנה אפרים הלכות זכי' מהפקר סי' ח', דלדעת הרא\"ש בסוגיא דנדרים דכל הפקר דעלמא תקנו שיוכל לחזור בו תוך ג' (ימים) כו' הא דשרי במודר הנאה דהוי מילתא דלא שכיח לא תקנו בי' רבנן כו'."],["31","31","וגם הרי אפשר להפקירו בפני ג'. וראה פסקי דינים להצ\"צ (כ, ג) שלפי המסקנא בנדרים בפני ג' הוי הפקר מיד (ושם „מ\"ש רבנו דלפי' הראם למסקנא אפי' מדאורייתא לא הוי הפקר צ\"ע דד\"א אלא לר\"י כו'\")."]]],[1300161149,"מקנה זיין³² אדער מפקיר זיין³³ — ווארום ביי א קטן „הסומך על שלחן אביו\" איז דער דין אז די (מציאה וואס ער געפינט און) מתנה וואס ער קריגט איז עס „של אביו\"³⁴, ובמילא ליגט אויפן פאטער דער חיוב צו פארקויפן עס צו א גוי אדער מפקיר זיין.\nמהאי טעמא איז מובן אז פון דעם סיפור הנ\"ל קען מען ניט מדייק זיין אז לויט דעת הצ\"צ איז א קטן מוזהר אין ב\"י וב\"י און חייב להפרישו מזה, און חמץ של קטן שעבר עליו הפסח איז אסור בהנאה³⁵, ווארום (נוסף אויף דעם וואס דא איז ניט געווען וודאי חמץ) ע\"פ דין איז דאס שייך צום טאטן — א גדול].\nובכלל צ\"ע צי מען קען פון תוכן סיפור הנ\"ל ארויסלערנען הלכות אינעם דין ואיסור חמץ ובנוגע לכל אדם — היות אז דא רעדט זיך וועגן חמץ דרבנן, אפשר — נאר ספק חמץ, און ענין מיוחד דלא שכיח, וועגן א שטוב וואס מ'האט מהדר געווען בתכלית וכו'.\nה. וועט מען דאס פארשטיין בהקדים אז — ע\"פ השמועה מחסידים³⁶\n— איז די הנהגה פון חסידי רבותינו נשיאינו געווען ע\"ד הנ\"ל: בשעת זיי האבן געהאט א דבר מאכל ומשקה וואס מ'האט באקומען פון רבי\"ן און מ'האט דאס ניט געקענט האלטן בפסח — האט מען דאס ניט פארקויפט אין חמץ, נאר מ'האט דאס אויפגעגעסן, אדער אויסגע־טרונקען פאר פסח.\nאון דער טעם דערפון י\"ל בפשטות: ס'איז היפך כבוד רבו צו נעמען זיינע שיריים וכיו\"ב (ובפרט וואס ער האט אים געגעבן) און זיי אוועקגעבן אדער פארקויפן צו א אינו יהודי.\nנאכמער, אין פאל ווען דער מאכל וכד' ווערט פארקויפט און גייט איבער אין רשות פון אינו יהודי, איז צ\"ע: נאכ־דעם ווען דער איד קויפט דאס אפ צוריק, צי עס בלייבט דאן אין דעם מאכל די פריערדיקע קדושה פון צדיק?\nו. לכאורה יש לומר אז דער ענטפער אויף דער שאלה הנ\"ל איז תלוי אין בירור מהות האיסור פון חמץ בפסח. און בלשון פון ראגאטשאווער³⁷: צי דער איסור חמץ איז א „תואר\" (ד.ה. דאס וואס דער מאכל (וכיו\"ב) איז חמץ'דיק), אדער דער איסור איז „חל על העצם\": און ווי ער איז מבאר אז דאס איז תלוי אין דער מחלוקת פון ר' יהודה ור\"ש³⁸ אויב חמץ לאחר הפסח אסור בהנאה „דמאן דס\"ל אסור ס\"ל דהאיסור חל על העצם ומאן דס\"ל מותר ס\"ל דלא הוה רק תואר וכשהלך הזמן בטל התואר\".\nאון דאס איז אויך פארבונדן מיט דער מחלוקת פון ר' יהודה מיט די חכמים³⁹: „ר\"י אומר אין ביעור חמץ אלא שריפה וחכ\"א אף מפרר וזורה לרוח או מטיל",[["32","32","ראה שו\"ע חו\"מ סרמ\"ג סט\"ו. ובנו\"כ."],["33","33","ראה ב\"מ כב, ב. ובפרש\"י שם ד\"ה יתמי."],["34","34","רמ\"א חו\"מ סע\"ר ס\"ב. שו\"ע אדה\"ז הל' הפקר ס\"ט. הל' שבת סי' שסו ס\"ג."],["35","35","ראה פרמ\"ג פתיחה כוללת ח\"ב אות ב. שד\"ח שם ס\"ח אות מג (ע' איכבה ואילך). אות עז (איקלו). שו\"ת חלקת יואב או\"ח סי' יט. ובשו\"ע אדה\"ז (סי' שמג ס\"ב) דאביו מחויב מד\"ס לגעור בהם ולהפרישם מלעבור על ל\"ת ואפילו על איסור של ד\"ס. ובס\"ג שם „החינוך בל\"ת כו' הוא בכל תינוק שהוא בר הבנה כו'\". ולהעיר ממ\"ש בהל' שבת סרס\"ט ס\"ג „שלא אסרו להאכילו איסור בידים אלא כשהמאכל אסור מצד עצמו כגון טריפה וכיוצא בה אבל כשהמאכל מותר מחמת עצמו אלא שהוא זמן האסור באכילה כו' שהרי מאכילים הקטנים ביוה\"כ כו'\" (ושם סי' קו ס\"ג. סי' תעא ס\"י)."],["36","36","מכ\"ק מו\"ח אדמו\"ר — לא שמעתי בכ\"ז."],["37","37","קונטרס השלמה ע' 65."],["38","38","פסחים כח, סע\"א ואילך."],["39","39","פסחים רפ\"ב."]]],[1300161150,"לים\": די חכמים האלטן אז דער איסור חמץ איז ב„תואר\" פון דער זאך, איז דעריבער גענוג „מפרר וזורה לרוח או מטיל לים\", וואס דעמאלט ווערט בטל דער „תואר\" פון חמץ (און במילא דער ענין פון אכילה והנאה), הגם אז עס פארבלייבט דער עצם החמץ; דאקעגן ר\"י האלט אז דער איסור חמץ איז „חל על העצם\" און דעריבער דארף מען דעם חמץ פארברענען — עס זאל בטל ווערן זיין עצם מציאות⁴⁰, ניט נאר דער „תואר\" און אפשריות פון אכילה און הנאה⁴¹.\nלפ\"ז י\"ל אז מיט דעם איז אויך פאר־בונדן די שאלה הנ\"ל: אויב מען האלט אז דער איסור איז „חל על העצם\" און דערפאר מוז די מכירה צום גוי כולל זיין אויך דעם עצם פון דעם חמץ,\nבמילא בלייבט ניט אין דעם חפץ קיין מציאות וואו די קדושה הקודמת זאל האבן אן אחיזה.\nאויב מ'לערנט אבער אז דער איסור חמץ „הוה רק תואר\" וואס איז א דבר נוסף אויף עצם הדבר⁴², וואס דעריבער איז דא א מקום צו זאגן אז ביי מכירת חמץ (כדי ניט עובר זיין אויף ב\"י וב\"י⁴³) ווערט פארקויפט נאר דער דבר נוסף על העצם, וואס איז געבונדן מיט'ן „תואר\"⁴⁴ ובמילא בלייבט אין דעם די קדושה הקודמת (די בעלות על העצם⁴⁵ — פון דעם נותן) וואס רירט אן דעם עצם פון דער זאך.\nולפ\"ז וויבאלד אז די הלכה איז ווי ר\"ש⁴⁵• אז חמץ לאחר הפסח איז מותר בהנאה, און דער איסור איז נאר אלס קנס, און אזוי אויך בנוגע ביעור חמץ איז דאך נאר „המנהג לשורפו\"⁴⁶, אבער די הלכה איז דאך ווי די חכמים⁴⁷ אז ס'איז גענוג „מפרר וזורה לרוח או מטיל לים\" — קומט במילא אויס אז עס מאכט ניט אויס צו פארקויפן די שיריים פון א צדיק (וכד') צום אינו יהודי, ווייל אויך",[["40","40","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071201\" data-slug=\"likkutei-sichot\" data-id=\"1300071201\">בשו\"ת צפע\"נ</a> וורשא סי' נ (הובא בצפע\"נ עה\"ת ר\"פ בחוקתי. לקו\"ש ח\"ז ע' 189) מבאר המחלוקת בפי' חיבת תשביתו. אבל מובן מדבריו שזה שייך להשאלה במהות האיסור. וראה מכתבי תורה מכתב קט. כולם הובאו במפענ\"צ פ\"א ס\"ט. וראה לעיל ע' 88 ואילך."],["41","41","לכאורה י\"ל שזהו גם המחלוקת אם ביטול ענינו השבתה בלב שיחשוב אותו כעפר כו' (ראה פרש\"י פסחים ד, ב. רמב\"ם פ\"ב מהל' חו\"מ ה\"ב. וראה רמב\"ן פסחים שם) או שהוא מחמת הפקר (תוס' פסחים שם. ר\"ן ריש פסחים): ביטול הדבר בלבו ומחשבתו כו' מתאים בהתואר (ראה רמב\"ן שם: „שהביטול מועיל להוציא מתורת חמץ ולהחשיבו כעפר שאינו ראוי לאכילה\". וראה צפע\"נ (השלמה שם. ושם ע' 46 בתחילתו. ועוד. הובא במפענ\"צ שם ס\"ח) לענין ביטול ע\"ז), משא\"כ כשמפקירו הרי עצם הדבר יצא מרשותו. ודעת אדה\"ז דענינו הפקר — ראה סתל\"א ס\"ב. וכן בס\"ג־ד מדייק „ביטול והפקר\" „ולא יפקירנו כו'\" (וראה סתל\"ד סי\"ח). וראה צפע\"נ הל' חו\"מ פ\"ב ה\"ב. ובהשמטות שם פ\"ג ה\"י. — ולהעיר מחיוב שריפה קדשים (האם תלוי בהנ\"ל או שזהו דין נוסף). ובכל אופן אינו שייך לעונש מיתת שריפה שהרי אופנו — דהגוף קיים (סנה' נב, א), משא\"כ בשריפה דעיר הנדחת שהיא כליל. ואכ\"מ."],["42","42","ולהעיר מב' הדיעות בשו\"ע אדה\"ז סתמ\"ז סמ\"ה, סתנ\"א סי\"ג ובהגהה שם. ובס' תמז שם „הי' שמו חמץ ועכשיו שמו חמץ אלא שעד עכשיו לא אסרו הכתוב ועכשיו הוא כחתיכת נבילה\"."],["43","43","ראה פסקי דינים להצ\"צ ושו\"ע אדה\"ז שבסוף הערה 10. וראה שד\"ח שבהערה 14."],["44","44","ומצינו עד\"ז בכמה עניני קנינים ובעלות. ולהעיר מצפע\"נ מהד\"ת לא, ב (הובא במפענ\"צ פ\"א סכ\"ט)."],["45","45","מעין דוגמא לדבר: קודם ברכה להי' הארץ ומלואה לאחר ברכה והארץ נתן לבנ\"א (ברכות לה, סע\"א) — אף שגם אז הוא לה', אבל כחילוק קדשים וחולין. — וראה לקו\"ש חל\"ד ע' 107 ואילך. •45) רמב\"ם פ\"א מהל' חו\"מ ה\"ד. שו\"ע אדה\"ז רסתמ\"ח."],["46","46","רמ\"א סתמ\"ה ס\"א. שו\"ע אדה\"ז שם ס\"ז."],["47","47","רמב\"ם שם פ\"ג ה\"א. שו\"ע אדה\"ז שם."]]],[1300161151,"נאכדעם קען פארבלייבן אין דעם די קדושת הצדיק⁴⁸.\nז. באמת קען מען אזוי ניט זאגן, ווארום הגם אז די מכירה איז בכדי ניט עובר זיין אויף ב\"י וב\"י, איז דאך אבער דעת רוב הפוסקים אז דאס איז א מכירה גמורה, כנ\"ל, ד.ה. אז דער עצם החמץ איז קנוי צום גוי בקנין גמור ומדאו־רייתא⁴⁹ (ובפרט לויט תקנת אדמו\"ר הזקן אז מ'מאכט אן ערב קבלן), ביז אז דער נכרי קען דאס פארקויפן צו א צווייטן לאחר הפסח⁵⁰. ד.ה. אז ער האט ניט בלויז א זכות השתמשות אדער א קנין בלויז אינעם „תואר\" פון דער זאך, נאר די עצם זאך באלאנגט צו אים⁵¹.\nועפ\"ז איז מובן וואס חסידים האבן ניט געוואלט פארקויפן א דבר מאכל וואס מ'האט מקבל געווען פון רבי\"ן צו א אינו יהודי, ווארום דאס איז ניט נאר אן ענין פון היפך כבוד רבו — אז מ'זאל די שיריים (וכיו\"ב) וואס מ'האט בא־קומען פון צדיק איבערגעבן אין רשות פון אן אינו יהודי (וואס איז מקבל חיות\nפון ג' קליפות הטמאות)⁵² — דורך דעם איז מען בידים מפקיע ח\"ו די בעלות הקדושה וואס איז פריער געווען אויף דעם⁵³.\nח. לפי\"ז קען מען מבאר זיין פאר־וואס עס איז ניט געווען די הנהגה צו מפקיר זיין די שיריים וכו' פון א צדיק:\nדער גדר פון הפקר, זאגט דער ראגאטשאווער⁵⁴, קען מען אויסטייטשן אויף צוויי אופנים: צי דער אויפטו פון הפקר איז אז דער בעה\"ב איז זיך מסלק פון דער זאך וואס ער איז מפקיר און עס געהערט ניט צו קיינעם, אדער אז דורך דעם מפקיר זיין „באקומען\" אלע מענטשן א (זכות ו)קנין אין דבר הנפקר.\nאון דערמיט איז דער ראגאטשאווער מבאר פלוגתת אמוראים⁵⁵:\nווען איינער האט אנגעשעפט וואסער פון א בור של הפקר⁵⁶ אום יו\"ט צוליב זיין חבר, זאגט ר' נחמן אז דער תחום ווערט גערעכנט „כרגלי מי שנתמלאו לו\", ד.ה. אז די אלפים אמה (פון מקום שביתה) ווערט גערעכנט פון דעם ארט וואו עס געפינט זיך דער פאר וועמען ער האט געשעפט די וואסער. רב ששת זאגט אז מ'רעכנט עס „כרגלי הממלא\", אז מ'רעכנט די אלפים אמה פון דעם",[["48","48","להעיר מגדרי חלות הדין דבאו בה פריצים וחללוה (ע\"ז נב, ב (ומלחמות שם). נדרים סב, א. וראה צפע\"נ עה\"ת הפטורת פ' בהר (ע' רמז)), דין כלי המקדש (בהיותם אצל אחשורוש — ראה מגילה יא, ב), אבל ביאת פריצים וכו' אסורה, משא\"כ בנדו\"ד. ואכ\"מ."],["49","49","ראה לעיל הערה 14."],["50","50","ראה לעיל (בהערה הנ\"ל) שאדה\"ז כ' ששום אדם .. לא יוכל לקנות .. אחר הפסח, ולא כל' המג\"א והח\"י. וראה ט\"ז שם „ואי\"ל דלא מכר לעכו\"ם רק כדי להפקיע איסור חמץ ולא להפקיענו מרשותו דז\"א דא\"כ הו\"ל חמץ של ישראל\"."],["51","51","ולהעיר מהדיעות שלא ימכרו הכלים לנכרי שלא יצטרכו טבילה כשיצאו מרשות העכו\"ם (שו\"ת שיבת ציון סי\"א. שו\"ת חת\"ס או\"ח סק\"ט. הובא בשד\"ח שם ס\"ט אות כז). ומה שלא כתבו אדה\"ז — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181377\" data-slug=\"likkutei-sichot\" data-id=\"1300181377\">לקו\"ש חי\"ח ע' 368</a> ואילך ודלא כבשד\"ח שם)."],["52","52","להעיר מלקו\"ד תשנג, א דכללות הענין שכתב יד קדשו של רבינו הזקן ימצא אצל אינו יהודי היא אחת מפליאות תמים דעים יתברך ויתעלה."],["53","53","וצ\"ע אם י\"ל שבנדון הנ\"ל הערה 7 שאני."],["54","54","הלכות נדרים פ\"ב הי\"ד (י, ד). הלכות מתנות עניים פ\"ב (לא, ג) ופ\"ד (נט, ג)."],["55","55","ביצה לט, א."],["56","56","בגמרא קאי פלוגתי' בבורות של עולי בבל, אבל בצפע\"נ נדרים שם ובמת\"ע (לא, ג) גבי „מעיינות הנובעין\", ואולי כ' כן כי של עולי בבל לא שייך עתה, משא\"כ מעיינות הנובעין גם כשהם של יחיד הי\"ה כמו בור של הפקר כבגמרא שם לפנ\"ז. וראה השגת הראב\"ד הל' יו\"ט פ\"ה הי\"ז (בסופה)."]]],[1300161152,"ממלא: און די גמרא זאגט „במאי קא מיפלגי — מר סבר בירא דהפקרא הוא ומר סבר בירא דשותפי הוא\". איז דער ראגאטשאווער מבאר (אז ביידע האלטן אז דער בור איז הפקר, נאר): רב נחמן האלט, אז דער גדר פון הפקר איז אז אלע האבן אין אים א זכות וחלק — אויך דער פאר וועמען ער האט געשעפט די וואסער, דערפאר האט ער דעם דין פון „בירא דשותפי הוא\". רב ששת האלט: הפקר מיינט אז דאס געהערט ניט צו קיינעם, ובמילא קען דער ממלא (זוכה זיין פאר זיך — עיי\"ש — אבער) ניט זוכה זיין די וואסער פארן צווייטן און דערפאר קען מען ניט רעכענען די אלפים אמה פונעם צווייטן, נאר „כרגלי הממלא\"⁵⁷.\nאון לויט ביידע סברות אין הפקר איז מובן בנדו\"ד, כדלקמן.\nט. לויט דער סברא אז הפקר פועל'ט אז דאס געהערט צו אלעמען⁵⁸ איז מובן בפשטות פארוואס מ'האט ניט געוואלט מפקיר זיין די שיריים הנ\"ל — און מצד דעם זעלבן טעם ווי ביי מכירה צו א אינו יהודי — ווארום דעמאלט וואלט דאס באלאנגט צו אלע גוים פון דער וועלט [ובפרט אז בפשטות זיינען זיך אידן, וואס אין רצונם בחמץ בפסח, מסלק פון באקומען דעם זכות אין דעם\nהפקר⁵⁹] און דאס איז היפך כבוד רבו, כנ\"ל.\nאון אין איין פרט איז דאס מפקיר זיין נאך ערגער ווי פארקויפן עס צו אן אינו יהודי: בשעת ער פארקויפט צו אן אינו יהודי קען ער אויפזוכן אזא גוי וועלכער איז מחסידי אומות העולם וואס דער רמב\"ם פסק'נט⁶⁰ וועגן אים, אז יש להם חלק לעוה\"ב⁶¹ ובפרט נאך אז דער גוי איז מציל דעם אידן פון עובר זיין אויף איסור חמץ בפסח; משא\"כ בשעת דאס ווערט „הפקר לכל\" — געהערט דאס צו אלע גוים, אויך ניט חסידי אומות העולם, און דערמיט אויך נאך מער בסתירה צו כבוד רבו.\nיו\"ד. אויך לויט דער סברא אז הפקר איז ניט א זאך וואס האט א שייכות צו אלעמען, איז מובן: נעמען א דבר יקר, א דבר שבקדושה וואס מ'האט עס באקומען מרבו, און דאס בלב שלם מבטל זיין און איבערלאזן דאס במקום הפקר, איז אויך אן ענין פון היפך הכבוד, ווייל דאס ווייזט אויף היפך החשיבות⁶².\nומהאי טעמא האט אויך דער „צמח צדק\" זיך משתדל געווען אז אנשטאט",[["57","57","אבל להעיר שבגמרא שם (לט, ב) מסיים דפליגתי' הוא לא אם בירא דשותפא אלא דכולא עלמא בירא דהפקרא היא אלא הכא במגב' מציאה לחבירו כו' וכהפי' בזה בפרש\"י תוס' וכו'. וכן הוא להלכה במג\"א או\"ח סשצ\"ז סקי\"ד ושו\"ע אדה\"ז שם סי\"ח."],["58","58","ולהעיר מל' אדה\"ז סתרל\"ו ס\"א „שהרי יש לכל העולם הילוך בו כו' והגוים אינם מוחלין\". ובהל' גזילה וגניבה סוס\"ז. ---"],["59","59","ובלא\"ה אינו ברשותו של אדם ורק שעשאו הכתוב כאילו ברשותו (פסחים ה, סע\"ב); וראה ר\"ן (פסחים בתחלתו) דמה\"ט מהני גילוי דעתי' בעלמא דלא ניחא לי' ליהוי זכותא בגוי\" כלל סגי. וראה שו\"ע אדה\"ז סתל\"ד ס\"ז."],["60","60","הלכות מלכים ספ\"ח. וראה ירושלמי מגילה פ\"ג ה\"ב."],["61","61","ובליקוטי ביאורים (מז, ד — להרה\"צ כו' ר\"ה מפאריטש. מאמרי אדהאמ\"צ קונטרסים ע' קמד) שחסידי או\"ה הם מק\"נ, ומצויין שם לשער החמ\"צ בסידור."],["62","62","דא\"א לארכבי' אתרי רכשי (ע\"ד כתובות נה, ב) דכל הטעם שמפקירו כיון שרוצה שיתקיים אצלו גם לאחר הפסח הרי ביטול והפקר צ\"ל בלב שלם כו'."]]],[1300161153,"דעם אז די „צוקערקעס\" זאלן געהערן צו א אינו יהודי אדער זיין הפקר זאל זיי זיין אייניקל (כ\"ק אדמו\"ר מהורש\"ב) אויפעסן און זיי זאלן ווערן דם ובשר כבשרו⁶³.\nיא. פון כהנ\"ל קומט ארויס נאך מער בהפלאה די הוראה אין גודל ההשתדלות ואופן החינוך:\nוויבאלד אז די „צוקערקעס\" זיינען געווען ביים רבי\"ן (מהורש\"ב) נ\"ע אזוי טייער, אז צוליב דעם האט ער זיי געהאלטן גאנץ ביי זיך ברשותו — אפילו מוותר געווען אויף דעם עס זאל ווערן דם ובשר כבשרו — און ס'איז דערביי ניט דא קיין איסור זיי צו מפקיר זיין אדער פארקויפן וכו' — האט מען דאך לכאורה בעסער געדארפט אים צוליב טאן וואלט ער זיי געהאט תמיד (אויך נאך פסח), דאס וואלט עם תמיד מזכיר געווען און מעורר געווען אויף דער קדושה, כניסה לחדר וכו' — איי וואס י\"ל אז — בפנימיותו — נעקרה הקדושה און לפי שעה איז דאס געווען ברשות האינו יהודי וכו', איז ער דאך געווען א קינד בן שלש⁶⁴ און ניט געוואוסט דער־פון וכו'.\nנאר דא זעט מען גודל ההשתדלות אין ענין החינוך, ניט נאר אין ענייני דאורייתא ודרבנן, אפילו אין א הידור מצוה, נאר אויך אין מנהגים וענינים פון חסידים — און אז יעדער זאך זאל זיין לאמתתו.\nאון דאס דארף מען טאן ניט נאר דאן ווען דאס קומט אן גרינג, נאר אויך בשעת ס'איז פארבונדן מיט א תנועה וואס לפי\"ע המחנך איז עס אן ענין פון מס\"נ (מסירת הרצון). און ווי די כמה סיפורים וואס מ'געפינט אויך בנוגע דעם חינוך פון כ\"ק מו\"ח אדמו\"ר בעצמו.\nוואס דעמאלט געוואוינט מען איין דעם קינד ניט נאר „לשנות מדותיו ה־טבעיים\", נאר אויך „טבעי\" מדותיו⁶⁵.\nאון כאטש דאס איז א דרך אין חינוך וואס מען דערציילט בנוגע יחידי סגולה — נשיאי ישראל, ווײבאלד מ'האט דאס מגלה געווען יעדן, איז דאס א הוראה פאר יעדערן, און ווי ער זאגט אין דער שיחה „אט אזא חינוך דארפן מיר האבן\" —\nאון דעם כח אויף דערויף האט מען פון רבותינו נשיאינו וואס בתר רישא גופא אזיל⁶⁶, צו גיין באורחותיהם ובדרכיהם אשר הורונו נס\"ו.\n(משיחות ש\"פ בלק תשל\"ג)",[["63","63","בשו\"ת ערוגת הבושם שם דאיידי דחביבא הואיל והי' מונח על השלחן גבוה של מרן ז\"ל נכון לקיים בו מצות שריפת חמץ כהאי דאמרינן בברכות לט, ב. .. כי הוי מתרמי להו ריפתא דערובא .. הואיל ואתעביד בי' מצוה חדא נעביד בי' מצוה אחריתא. אבל ראה שו\"ת אבני זכרון שם אות ה' דלא מצינו ענין בשריפת חמץ הואיל ואתעביד בה מצוה חדא כו' רק בהושענא דלא מידי דאכילה הוא (וראה לקמן ע' 183 ואילך)."],["64","64","ראה חנוך לנער ע' 8. ---"],["65","65","לקו\"ד ח\"א נו, א."],["66","66","עירובין מא, א."]]],[1300161154,"<h3>יו״ד שבט</h3>\nא. דער תוכן פון א יארצייט פון יום הסתלקות פון א צדיק, ווען עס זיינען עולה „כל מעשיו ותורתו ועבודתו אשר עבד כל ימי חייו״¹, איז (פאר אונז) בעיקר אויף צו מתבונן זיין זיך אין „מעשיו ותורתו ועבודתו״ פון בעל ההילולא, כדי ארויסצונעמען פון דעם די הוראה אין חיי יום יום פאר יעדערן פון ההולכים בעקבותיו אין מעשיו תורתו ועבודתו של האדם.²\nוויבאלד אז בא יעדער אידן איז מעשיו ותורתו ועבודתו אשר עבד כל ימי חייו הוא ריבוי ענינים, ועאכו״כ בא א נשיא ישראל, איז דעריבער ניט אלע־מאל ברור וגלוי וואס עס איז די נקודה עיקרית פון עבודתו וואס פון דעם דארף מען ארויסנעמען די עיקר הוראה. בנדו״ד אבער — דער יארצייט פון כ״ק מו״ח אדמו״ר — האט מען דאך די קלארע הוראה — די תורה (אויך פון לשון הוראה)³ פון בעל ההילולא, דער מאמר ד״ה באתי לגני וואס דער רבי בעל ההילולא אליין האט ארויסגעגעבן\nצו זיין יום ההסתלקות, וואס פון דער תורה ווייס מען אין וואס עס דארף זיין דער עיקר התבוננות ביום ההילולא שלו, און וואס מ׳דארף דערפון מיט־נעמען בעבודת האדם בפועל.\nב. בסיום המאמר רעדט דער רבי וועגן גודל ונחיצות ענין הזריזות אין עבודת ה׳ בקיום התורה והמצות, וארום „מי הוא היודע עתו וזמנו״, ווי ער זאגט אין מדרש⁴ „אין אדם שליט לומר המתינו לי עד שאעשה חשבונותי ועד שאצוה לביתי״,\nוואס מיט דעם ווערט ארויסגע־בראכט⁵, אז דער ענין הזריזות בעבודת ה׳ איז ניט נאר א פרט אין דער עבודה, וכפשטות מחז״ל⁶ „אין מחמיצין את המצות״, נאר דאס איז נוגע צו כללות העבודה, ער קען פארלירן די גאנצע זאך. און די הוראה „אין אדם שליט לומר כו׳״ איז בכל יום ורגע פון כל משך ימי חייו עלי אדמות, מאה ועשרים שנה.\nאון נאך מער שטייט ברמז אין מאמר רז״ל הנ״ל „אין מחמיצין את המצות .. אם באת מצוה לידך עשה אותה מיד״: בשעת מ׳לייגט אפ די מצוה, איז אנ־שטאט „ושמרתם את המצות״ — „את המצוות״ — ווערט דאס „חמץ״, היפך המצוה.⁷\nאון אין תחילת המאמר רעדט ער אין",[["1","1","אגה״ק סי׳ זך (קמו, א־ב). ושם מבואר שכן הוא בשעת ההסתלקות, אבל מזה מובן שכ״ה גם בנוגע ליום השנה, שהרי בכל שנה ושנה חוזרות וניעורות ההארות וההמשכות שבפעם הראשונה, כידוע (ראה רמ״ז בספר תיקון שובבים הובא ונתבאר בספר לב דוד (להחיד״א) פכ״ט). וראה אגה״ק סי׳ יד (קכ, ב) „בכל שנה ושנה יורד כו׳״."],["2","2","ראה אגה״ק שם (קמז, ב): והארת אורות עליונים אלו מאירה על כל תלמידיו שנעשו עובדי ה׳ על ידי תורתו ועבודתו כו׳. וראה גם סי׳ כח שם (קמח, א) „שכל עמל האדם שעמלה נפשו בחייו למעלה כו׳ מתגלה ומאיר בבחי׳ גילוי מלמעלה למטה כו׳״. וראה סידור שער הל״ג בעומר (דש, ב־ג)."],["3","3","זח״ג נג, ב."],["4","4","דב״ר פ״ט, ג."],["5","5","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071097\" data-slug=\"likkutei-sichot\" data-id=\"1300071097\">לקו״ש ח״ז ע׳ 85</a>."],["6","6","מכילתא ופרש״י בא יב, יז."],["7","7","ראה שם „כדרך שאין מחמיצין את המצה כך אין מחמיצין את המצוה אלא אם באת מצוה לידך עשה אותה מיד״."]]],[1300161155,"וואס עס דארף זיין די עבודה, אין וועלכן ענין דארף זיין די זריזות, אין דעם וואס „נתאווה הקב״ה להיות לו ית׳ דירה בתחתונים״⁸ — מאכן א דירה בתחתונים.\nג. אע״פ אז דורך יעדער פעולה פון א אידן בקיום התורה והמצות, און עד״ז אין „כל מעשיך יהיו לשם שמים״⁹ ו„בכל דרכיך דעהו״¹⁰, ווערט אויפ־געטאן א דירה לו ית׳ בתחתונים און עס פירט זיך דורך דער „נתאווה״ פון אוי־בערשטן¹¹ —\nאיז אבער פארשטאנדיק, אז די הוראה אין דעם ענין פון „נתאווה הקב״ה להיות לו ית׳ דירה בתחתונים״ וואס מ׳דארף ארויסנעמען פון יום ההילולא, איז (ניט נאר א זירוז כללי אויף כללות העבודה פון תורה ומצותי׳, נאר) א הוראה מיוחדת¹² — אין וועלכן ענין עס דארף זיין דער עיקר עבודת האדם בימינו אלה,\nמתאים צו „מעשיו ותורתו ועבודתו״ פון דעם בעל ההילולא.\nויובן בהקדם הביאור אין דיוק הלשון וואס דער רבי ברענגט אין מאמר „נתאווה הקב״ה להיות לו ית׳¹³ דירה בתחתונים״, וואס אין דעם נתאווה זיינען דא דריי פרטים: א) לו ית׳, ב) דירה, ג) בתחתונים.\nא) „לו ית׳״ — די דירה איז לעצמותו¹⁴ ית׳, ניט (נאר) צו מדריגות פון אורות וגילויים. ב) „דירה״ — דער אופן ווי עצמותו ית׳ געפינט זיך למטה איז ניט באופן עראי, נאר באופן של „דירה״ — בקביעות¹⁵. ג) „בתחתונים״ — די דירה לעצמותו איז דוקא „בתחתונים״, ניט בעולמות עליונים¹⁶.\nדי דריי ענינים זיינען תלוי זה בזה: מצד בחי׳ הגילויים אפילו גילויים הכי נעלים, וויבאלד אז מציאותם איז ניט מעצמותם, ובפרט אז זייער גילוי איז ברצון, איז ניט שייך ביי זיי דער ענין פון „דירה״ — קביעות, היות מציאותם איז ניט קיין מציאות אמיתית מצד עצמם¹⁷.\nאון וויבאלד אז ס׳איז דא א געווייסע הגדרה למציאותו¹⁸ איז מובן אז זייער גילוי איז בלויז דארט וואו עס איז שייך דער ענין פון א כלי צו גילוי אלקות. משא״כ אין תחתונים, וואס זיינען ניט קיין כלי צו אלקות, קען דארט, כביכול, ניט נתגלה ווערן אלקות.\nמשא״כ מצד עצמות, וואס ער איז ניט בגדר העלם וגילוי, און איז למעלה פון",[["8","8","תנחומא נשא טז. שם בחוקותי ג. במדב״ר פי״ג, ו."],["9","9","אבות פ״ב מי״ב."],["10","10","משלי ג, ו. טושו״ע או״ח סי׳ רלא."],["11","11","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל״ו</a>־לז."],["12","12","ראה קונטרס התפלה פי״ג. קונטרס העבודה פ״ז. ועוד."],["13","13","ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא שם</a> (ובכמה מקומות בדא״ח) הלשון „נתאווה הקב״ה להיות לו דירה בתחתונים״ — ההוספה דתיבת „ית׳״ — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091027\" data-slug=\"likkutei-sichot\" data-id=\"1300091027\">לקו״ש ח״ט ע׳ 27</a> ואילך."],["14","14","אוה״ת בלק ריש ע׳ תתקצז. המשך תרס״ז בתחלתו (ס״ע ג). ובכ״מ."],["15","15","בפרטיות יותר, בלשון „דירה״ יש ב׳ פרטים (ראה לקו״ש ח״ד ע׳ 1054. ועוד. וראה הנסמן בהערה שלפנ״ז): א) שנמצא בה כל העצם, ב) ושהעצם נמצא בה בגילוי — ומתאימים ב׳ ענינים אלו (שב„דירה״) לב׳ הענינים („לו ית׳״ ו„דירה״) שבפנים."],["16","16","תניא שם. וראה בהבא לקמן גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061021\" data-slug=\"likkutei-sichot\" data-id=\"1300061021\">לקו״ש ח״ו ע׳ 21</a> ואילך ובהערות שם. וראה לקמן בפנים."],["17","17","ראה המשך תרס״ו ע׳ קסט ואילך. ע׳ תלב ואילך. ד״ה בסוכות תרס״ד. וראה ד״ה ביום שמחתכם תרנ״ח. הגהות לד״ה פתח אליהו תרנ״ח. ובכ״מ. וראה ספר הערכים־חב״ד ע׳ אוא״ס(א) סעיף ג־ד, וש״נ."],["18","18","ראה המשך שם ע׳ קסח."]]],[1300161156,"גדר השינויים, היות אז מציאותו מעצמותו¹⁹, איז המשכתו (אין דעם אופן וואס עס איז שייך צו זאגן המשכה אין עצמות²⁰), באופן של „דירה״, קביעות²¹,\nאון בתחתונים דוקא, וארום עולמות עליונים — גילויים, וויבאלד אז זיי זיינען ירידה מאור פניו ית׳²¹*, זיינען זיי ניט קיין „כלי״ צו עצמותו ית׳; דוקא אין תחתונים, וואו ס׳איז ניטא דער ענין פון גילויים, דא ווערט א דירה לעצמותו ית׳²².\nד. לפ״ז איז אויך מובן בנוגע עבודת האדם, אז די עבודה צו מאכן „לו ית׳ דירה בתחתונים״, דארף געטאן ווערן באופן כזה וואס זאל מתאים זיין צו דער דירה לעצמותו ית׳ וואס ווערט גע־מאכט בתחתונים.\nא) „לו ית׳״ — די עבודה דארף גע־טאן ווערן בלויז „לו ית׳״, אז עס זאל זיך אויספירן זיין רצון, דער נתאווה פון עצמותו ית׳, ניט על מנת לקבל פרס²³, אפילו ניט צוליב ווערן דבוק מיט\nאלקות, אדער אפילו אז דער אדם העובד זאל דורכפירן דעם אוי־בערשטנ׳ס כוונה²⁴, נאר עס זאל זיך אויספירן דעם אויבערשטנ׳ס „נת־אווה״²⁵.\nב) „דירה״ — די עבודה דארף זיין באופן של קביעות. ד.ה. ניט אז דער אדם העובד שטייט בעבודתו אין שינויים, ער איז ניט אין דעם זעלבן תוקף בתמידיות כל הזמן, וואס דאס בא־ווייזט אז זיין עבודה איז ניט באופן של דירה — קביעות, נאר באופן „עראי״.\nג) „בתחתונים״ — די עבודה דארף זיין (בעיקר) אין ענינים תחתונים, סיי בנוגע צו תורה, סיי בנוגע צו מצות, ועד״ז בנוגע אידן (כדלקמן).\nאון אויך די דריי ענינים בעבודת האדם זיינען אפהענגיק איינער אין דעם צווייטן:\nווען עבודתו של האדם איז צוליב זיין אייגענער מציאות, אפילו — צו וועלן ווערן דבוק צו אלקות (אדער אפילו אין א העכערע דרגא: ער וויל מקיים זיין רצון הבורא, אבער אין זיין עבודה איז אריינגעמישט דער הרגש אז ער פירט דורך דעם רצון השם) — דעמאלט קענען זיין שינויים בעבודתו, מתאים צו זיין הרגש האהבה והדביקות באותה שעה, ס׳איז ניט קיין קביעות — דירה. און ס׳איז אויך דא א חילוק אין וואס די עבודה איז, צי אין ענינים נעלים אדער אין ענינים תחתונים, וואו ער פילט ניט (אין דער עבודה) אזא חיות ותענוג.\nדוקא ווען עבודתו איז „לו ית׳״, עס זאל זיך אויספירן דעם אויבערשטנ׳ס",[["19","19","אגה״ק סי׳ כ (קל, ב). ובארוכה בהנסמן בהערה 17."],["20","20","ראה המשך תער״ב ח״ב ע׳ א׳קמא. ד״ה תקעו תרצ״ד (תשי״א) פ״ב."],["21","21","ולכן עיקר ענין ה„דירה״ — קביעות, תהי׳ בביהמ״ק השלישי דוקא, כיון שהוא „בנינא דקוב״ה״ — מבחי׳ עצמותו, ולכן יהי׳ קיים בקיום נצחי, משא״כ בית ראשון וב׳ שהם „בנינא דבר נש״ — מבחי׳ הגילויים „לית בי׳ קיומא כלל״ (זח״ג רכא, א. (בפי׳ הכתוב דפרשתנו (בשלח טו, יז) „מכון לשבתך פעלת הוי׳ מקדש אדני כוננו ידיך״). ח״א כח, א). וראה פרש״י עה״פ: ואימתי יבנה בשתי ידים בזמן שה׳ ימלוך לעולם ועד לעתיד לבוא כו׳. ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091026\" data-slug=\"likkutei-sichot\" data-id=\"1300091026\">לקו״ש ח״ט ע׳ 26</a> ואילך. וש״נ. *21) <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל״ז</a>."],["22","22","ראה גם ד״ה מצותה משתשקע החמה תרע״ח. ספר המאמרים באתי לגני ע׳ לב ואילך. וש״נ."],["23","23","אבות פ״א מ״ג."],["24","24","ראה ד״ה ואתם תהיו לי תר״ס. ד״ה וזאת התרומה עת״ר. וראה שם סד״ה תקעו, ד״ה בסוכות."],["25","25","להעיר מבחי׳ בני עלי׳ (<a class=\"ft-cite\" href=\"#/read/tanya/3401310015\" data-slug=\"tanya\" data-id=\"3401310015\">תניא ספ״י</a>)."]]],[1300161157,"כוונה, דאן זיינען אלע ענינים וואס פירן צו דער השלמה פון דער כוונה בא אים גלייך, ובמילא איז זיין עבודה באופן של קביעות בתמידות — „דירה״, און ווי־באלד אז דער נתאווה פון אויבערשטן איז „להיות לו ית׳ דירה בתחתונים״, איז זיין עבודה (בעיקר) אין ענינים תח־תונים.\nה. די הנהגה הנ״ל, אין די אלע דריי פרטים, האט מען געזען בגלוי בא דעם בעל ההילולא אליין:\nכידוע — און ווי שוין פיל מאל גע־רעדט²⁶ — איז די עבודה פון בעל ההילולא בהרבצת התורה וחיזוק היהדות געווען אין המשך פון מסירת נפש, וכלשון פון דעם בעל ההילולא אין סיום המאמר הנ״ל²⁷ — „למעלה מטעם ודעת״. וואס די עבודה פון מסנ״פ בא־ווייזט דאך אז ער טוט דאס ניט צוליב שכר רוחני וכיו״ב, צוליב שלימות מציאותו, אפילו ניט כדי לדבקה בו ית׳, נאר בלויז „לו ית׳״, און זיין אייגענע מציאות איז אין דעם כלל ניטא²⁸. ובפרט — מעין פון דעם אופן ווי עס איז געווען בא דעם בעל ההילולא, „שהשליך חייו מנגד״²⁹, כפשוטו, אויף הרבצת התורה וחיזוק היהדות³⁰.\nאון דער תוקף ואופן המסנ״פ איז בא אים געווען שטענדיק כל משך זמן נשיאותו, וואס האט זיך אויסגעדריקט בכל האופנים פון מסנ״פ.\nווי גערעדט בארוכה²⁶, דער חילוק פון די דריי תקופות פון „עשר שנים״ במשך זיינע נשיאות־יארן בעלמא דין, אז אין די אלע גאר פארשידענע אופני עבודה איז בא אים געווען דער זעל־בער תוקף המסנ״פ.\nוואס נוסף אויף דעם וואס די עצם עבודה פון מסירת נפש איז דאך ניט קיין עבודה באופן של עראי, נאר קביעות בלי שינויים, היות אז די עבודה איז מצד עצם הנשמה, וואס איז העכער פון שינויים — האט זיך דאס אויסגעדריקט אויך אין דעם אופן גלוי פון מסנ״פ, אז אין די אלע פארשידענע סארטן עבודות איז בא אים געווען דער זעלבער תוקף פון מסירת נפש.\nואע״פ אז די הרבצת התורה וחיזוק היהדות ארבעט ביז צו הפצת המעינות איז בא אים געווען אויף אלע געביטן, האט מען אבער געזען בא אים א השתדלות יתירה אין א) מסדר זיין כיתות ושיעורים וכדומה אויף צו לערנען הלכה למעשה אויף רבנות, בכדי צו אויפשטעלן מורי הוראה בפועל, שיקן רבנים אין פארשידענע קהילות און מושבים אא״ו. ב) אין דער הפצה פון קיום מצות מעשיות צווישן יעדער סוג אידן, דורך מעשה בפועל (שיקן שלוחים צו בויען מקוואות, שיקן מוהלים וכיו״ב), ג) אין דעם ענין פון חינוך על טהרת הקודש פון תינוקות של בית רבן, מייסד זיין חדרים, שיקן מלמדים כו׳.\nוואס די אלע ענינים איז בחי׳ „תחתונים״ אין תומ״צ גופא, כדלקמן.",[["26","26","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181311\" data-slug=\"likkutei-sichot\" data-id=\"1300181311\">לקו״ש חי״ח ע׳ 302</a> ואילך, וש״נ. ובכ״מ."],["27","27","פ״ה."],["28","28","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא רפי״ט</a>."],["29","29","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370443\" data-slug=\"torah-or\" data-id=\"3901370443\">תו״א צט, ב</a> (וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380092\" data-slug=\"likkutei-torah\" data-id=\"4001380092\">לקו״ת ויקרא ד, ג</a>) — לענין מסנ״פ."],["30","30","שזה גם למעלה מענין המסנ״פ על קדוש השם (המבואר בהנ״ל הערה הקודמת). וראה המשך ההילולא פי״א שבשביל ניצוח המלחמה „גם חייו משליך המלך מנגד״. ולהעיר מההפרש בין מסנ״פ דאברהם ומסנ״פ דרע״ק (סה״מ ה׳ש״ת ע׳ טו. 30. וראה סה״מ באתי לגני ע׳ לא)."]]],[1300161158,"ו. די הסברה אין דעם: אין לימוד התורה זיינען דא כמה אופנים, אנ־הויבנדיק פון לימוד התורה ווי דאס איז למעלה אין מתיבתא דקוב״ה ומתיבתא דרקיע³¹, ביז ווי זי ווערט געלערנט למטה, וואס אויך למטה זיינען דא כו״כ דרגות, ובהן — דער לימוד פון דרוש וקבל שכר, יגדיל תורה ויאדיר³², און דער לימוד „לאסוקי שמעתא אליבא דהילכתא״³³.\nוואס בכללות איז דאס דער חילוק צווישן „עליונים״ אין לימוד התורה און „תחתונים״ אין תורה: ווען ער קאכט זיך אין דעם אופן הלימוד פון „יגדיל תורה ויאדיר״ (ועכ״פ ניט צוליב הלכה למעשה), איז ער בעיקר פארקאכט אין דער שקו״ט פון תורה, און זיין תענוג וחיות איז אין השגת התורה; משא״כ ווען ער לערנט „אסוקי שמעתא אליבא דהילכתא״, ליגט ער בעיקר (ניט אין דער שקו״ט און שכל התורה, נאר) צו וויסן די הוראה דערפון במעשה בפועל.\nעד״ז איז אויך בנוגע צום קיום מצות מעשיות: נוסף לזה וואס דאס איז בחי׳ תחתונים לגבי לימוד התורה בכלל³⁴, איז דא ווי ענין המצות איז דא „מצד תורה, ועד״ז כל העוסק בתורת עולה כאילו הקריב עולה כו׳³⁵, ס׳דא כמ״פ וואס במקום וואו מ׳קען ניט מקיים זיין די מצוה במעשה בפועל, איז מען עוסק בתורה פון דער מצוה — אעפ״כ זאגט מען נאר אז דאס איז כאילו הקריב:\nעס איז דא כוונת המצות א.ז.וו.\nמשא״כ (בזמן שבית המקדש קיים) א איד וואס האט ניט קיין ידיעה אין הלכות קרבנות נאר ער פארלאזט זיך אויפן כהן המקריב את הקרבן (ולוי בדוכנו וישראל במעמדו)³⁶, איז ער מקיים די מצוה און דעם חיוב הקרבת הקרבנות שעליו.\nובפרטיות יותר: דער ענין פון קיום המצות במעשה איז בחי׳ „תחתונים״ לגבי דעם דיבור המצוה, און נאך מער, לגבי כוונת המצוה במחשבה ולב.\nעד״ז איז אויך מובן בנוגע צו אידן, מיט וועמען מ׳לערנט תורה: דער לימוד פון תינוקות של בית רבן, ובפרט בהתחלת הלימוד — דער לימוד פון אל״ף בי״ת כו׳ — איז דער ענין פון „תחתונים״ בסוגי התלמידים מיט וועל־כע מ׳לערנט.\nז. ועפ״ז איז פארשטאנדיק ווי די התעסקות אין די ג׳ בחי׳ תחתונים האמורות קומט דוקא ווען זיין עבודה איז באופן כזה אז ער זוכט ניט קיין תועלת ושלימות פאר זיך, נאר בלויז „לו ית׳״.\nבשעת מ׳איז עפעס א מציאות לעצמו, דעמאלט איז דער עיקר קאך און חיות אין בחי׳ עליונים פון תורה, אין דעם שכל, און נאך מער אין דעם אור אלקי וואס לייכט אין תורה. און במילא איז ער גרייט צו לערנען אויך מיט אזעלכע אידן וואס זיינען כלים ראויים צו אזא סארט לימוד הן בנגלה שבתורה ועאכו״כ בפנימיות וסודות התורה. וואס",[["31","31","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380169\" data-slug=\"likkutei-torah\" data-id=\"4001380169\">ראה ב״מ פו, א</a>. זח״ג רג, ב. לקו״ת תזריע ד״ה בגמ׳ ב״מ (כב, סע״ב ואילך) ושם בסוף המאמר (כד, ד). וראה לקוטי דיבורים ח״א ט, א."],["32","32","ישעי׳ מב, כא. חולין סו, ב."],["33","33","יומא כו, א."],["34","34","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל״ז</a>."],["35","35","ראה מנחות קי, א. שו״ע אדה״ז או״ח מהדו״ת ס״א ס״ט. מהד״ק שם סי״א ואילך."],["36","36","ואף מי שלא הי׳ בלבו לשם אחד מכל אלו („ששה דברים הזבח נזבח״) כשר שהוא תנאי ב״ד (זבחים מו, ב)."]]],[1300161159,"דעמאלט זעט זיך ווי אלקות ווערט נתפשט און נתגלה אין וועלט.\nאבער אין דעם לימוד לאסוקי שמעתא אליבא דהילכתא, ועד״ז אין דעם לימוד פון אל״ף בי״ת מיט תינוקות של בית רבן — אין דעם האט ער ניט קיין קאך, ער זעט אין דעם ניט די „רייכקייט״ וגילוי שמו ית׳.\nועד״ז בנוגע לקיום המצות, איז דער עיקר חיות זיינער אין כוונת המצוה, ביז לדבקה בו ית׳, ניט אזוי אין דעם מעשה המצוה, אין דעם קיום רצון העליון.\nדוקא ווען זיין עבודה איז „לו ית׳״, עס זאל זיך אויספירן די כוונה פון דעם אויבערשטן, ווען דער עובד אליין איז ניט קיין מציאות לעצמו, דעמאלט איז זיין עבודה בעיקר אין די בחי׳ תחתונים, וארום דוקא עי״ז פירט זיך דורך דער „נתאווה הקב״ה להיות לו ית׳ דירה בתחתונים״.\nח. היינט דארף מען יעדער ענין „אפטייטשן״ אין פשוט׳ע ווערטער: פון די פילע הוראות הנ״ל זיינען דא צוויי ענינים וואס בתקופתנו זו איז געווארן אין זיי א חלישות:\nדער ערשטער ענין איז — לימוד הלכה למעשה. מ׳זעט אז בעזרת השי״ת איז דער לימוד התורה (בכלל) הולך ומתרבה, סיי בכמות און סיי באיכות. אבער דער לימוד אין אן אופן פון לאסוקי שמעתא אליבא דהילכתא — אז פון דעם לימוד זאלן ארויסקומען רבנים וואס קענען פסק׳נען א שאלה אין אלע פיר חלקי השו״ע (ובפרט אין אורח חיים) — איז מדור לדור ומשנה לשנה ומחודש לחודש, איז דאס הולך ופוחת ר״ל.\nדאס וואס מ׳קען ניט די דינים פון חו״מ, איז מצד מצב והנהגת המדינה דארף מען האפן אז דערפון וועלן ניט ארויסקומען קיין גרויסע קלקולים; אבער בנוגע צו אבן העזר, יורה דעה, ועאכו״כ בנוגע צו אורח חיים [די הלכות וואס זיינען נוגע בפועל ממש, ניט נאר אין זמנים קבועים, נאר אין טאג טעג־לעכן לעבן, כשמו — „אורח חיים״], האט מען כמעט ניט ביי וועמען צו פרעגן.\nבשעת מ׳קומט צו איינעם, וואס גיט אפ זיין גאנצע צייט אויף לימוד התורה, און מ׳פרעגט ביי אים א הלכה, ענט־פערט ער: איך בין פארנומען מיט לימוד התורה אין אן אופן פון „יגדיל תורה ויאדיר״, און הולך ומוסיף ואור; אבער פסק׳נען א דין אין הל׳ ברכות הנהנין, אין הל׳ תפלה, אדער הל׳ ק״ש — די הלכות האט ער ניט געלערנט!\nבנוגע צו אורח חיים איז דא א צווייענדיקער חסרון: נוסף לזה וואס עס פעלן אויס רבנים וואס זאלן קענען פסק׳נען אין די דינים, קומט צו די סכנה אז יעדער איינער זאל ווערן א „פוסק״ פאר זיך:\nא בעה״ב א סוחר, ניט קיין רב (אויב נאר ער איז א ירא שמים), וועט זיך ניט איינרידן אז ער קען אליין פסק׳נען א שאלה אין הל׳ גיטין, און אפילו ניט א שאלה אין יורה דעה. ווען עס מאכט זיך בא אים א שאלה וועט ער אויפזוכן א רב ומורה הוראה בפועל. משא״כ אין אורח חיים קען ער זיך איינרידן אז ער קען אליין ווערן א „פוסק״ — ער וועט א קוק טאן אין קיצור שולחן ערוך [אויף לשון קודש, און אויב ער פארשטייט ניט לשון קודש — אויף ענגליש, פראנצויז וכיו״ב] און טאן ווי בא אים קומט אויס דער פשט אין קצש״ע!\nאויב בנוגע צום שו״ע פון ב״י איז געווען א גאנצע שקו״ט ווי מ׳קען פון\n---"],[1300161160,"דארט פסק׳נען א הלכה ניט וויסנדיק די מקורות וטעמים³⁷ — פארשטייט מען שוין וואס עס קען ארויסקומען דערפון וואס מ׳גיט אפ די תורה בידו של כאו״א, אז ער זאל אליין פסק׳נען פון קיצור שו״ע!\nאון אין דעם דארף זיין דער „והחי יתן אל לבו״³⁸ — פון דער עבודה פון בעל ההילולא, וואס ער האט זיך איינגע־שטעלט אפילו ווען ס׳איז געווען פאר־בונדן מיט סכנת נפשות ממש, צו מייסד זיין (דאס וואס ווערט איצטער אנגע־רופן) בתי מדרש לרבנים —\nנעמט מען ארויס די הוראה, אז די אלע וואס זיינען ראויים לזה (און אפילו אויב ס׳איז דא א ספק צי זיי זיינען ראויים, איז ווי דער מצב איז איצטער, דארף מען זיכער גיין לחומרא), זאלן לערנען אין אן אופן פון לאסוקי שמעתא אליבא דהילכתא.\nאון זכות הרבים מסייעתם, ובפרט אז דאס איז נוגע ניט נאר צו א רבים פון איין שטאט, נאר לויט דעם מצב בהווה, איז דאס נוגע צו הונדערטער קהילות אין ארצות הברית און אנדערע לענ־דער, וועלכע זיינען געבליבן כפשוטו, אן רבנים מורי הוראה אין שו״ע. ועד״ז הונדערטער מושבים אין ארץ הקודש — „ארץ אשר גו׳ עיני ה״א בה מרשית השנה ועד אחרית שנה״³⁹, וואס האבן ניט קיין רבנים — אז עס וועט זיין סייעתא דשמיא וועלכע מ׳דארף האבן אויף מכוון זיין להלכה⁴⁰, מ׳זאל זיין „דן דין אמת לאמתו״, וואס דורך דעם\nווערט מען א שותף להקב״ה במעשה בראשית⁴¹.\nט. די צווייטע נקודה וואס איז נוגע בפרט אין היינטיקער תקופה — דעם אופן החינוך פון תינוקות של בית רבן:\nמצד די חוקי המדינה פון מדינה זו והדומות לה, איז געווארן א מצב מבהיל. ס׳איז איינגעשטעלט געווארן אז ביי א קינד — ניט נאר א בן חמש למקרא, נאר אפילו שוין אין עלטער פון בן עשר למשנה און בן י״ג למצות און בן חמש עשרה לגמרא — קען ניט דורכ־גיין א טאג פון שנת וימי הלימודים וואס ער זאל ניט לערנען קיין לימודי חול.\nאון אויף דעם דארף מען ארוס־נעמען די הוראה פון דעם בעל ההילולא, וואס ער האט זיך מוסר נפש געווען בפועל — און אויך געשיקט אנדערע אידן אויף מסנ״פ — צוליב איינשטעלן חדרים פאר אידישע קינדער, און אז דער לימוד אין די חדרים זאל זיין על טהרת הקודש, און ניט משנה זיין ח״ו די דרכי החינוך ווי זיי זיינען געווען איינגעפירט ביי אידן במשך כל הדורות,\nאיז דאך על אחת כמה וכמה בימינו אלה, און אין דער מדינה וכיו״ב, וואס עס איז ניט ח״ו א מצב של סכנה בגוף, דארף מען לייגן די גרעסטע השתד־לות, אז דער חינוך פון אידישע קינדער זאל זיין אינגאנצן על טהרת הקודש, ניט אריינמישן אין דעם קיין לימודי חול, נאר ווען דער חוק לאזט ניט קיין מעג־ליכקייט אויף ניט צו לערנען און — נאר אין דער כמות.\nיו״ד. אפילו די וואס קענען ניט ביי־שטיין דעם נסיון — איז אבער דער",[["37","37","ראה יד מלאכי כללי השו״ע אות א׳. וראה קו״א להל׳ ת״ת לאדה״ז רפ״ב."],["38","38","קהלת ז, ב. וראה תרגום שם."],["39","39","עקב יא, יב."],["40","40","סנהדרין צג, ב. וראה יומא שם."],["41","41","שבת י, א."]]],[1300161161,"אמת אז בכמה וכמה אופנים קען מען יוצא זיין מיט א פרט שבפרט און אין א פארנעם הכי קטן. ס׳איז לגמרי קיין הכרח ניט אז די לימודי חול זאלן זיין אין דער כמות ואיכות ווי זיי זיינען איצטער איינגעפירט אין בתי ספר וועלכע געפינען זיך אונטער די הנהלה פון אנשים (או נשים) יר״ש.\nמ׳דארף זיי נאר מעורר זיין און מעודד זיין, אז זייער השתדלות דארף זיין ניט אזוי אויף מדייק זיין אין מקיים זיין די חוקי המדינה, נאר מקיים זיין די מצות וחוקים פון, להבדיל, דעם אוי־בערשטן, וואס מ׳איז „מושבע ועומד מהר סיני״⁴² נאך איידער עס זיינען גע־ווען חוקי המדינה.\nאמת טאקע, אז „דינא דמלכותא דינא״⁴³ איז אבער (נוסף לזה וואס אין ענינים פון אידישקייט „האבן מיר אידן אויף זיך ניט קיין דעה זאגער״⁴⁴, איז אפילו אזא וואס קען ניט ביישטיין דעם נסיון פון לערנען נאר לימודי קודש, איז) אין דער מסגרת וואס חוקי המדינה ערלויבן, דארף זיין די השתדלות און מערער צייט פון די תלמידים ותלמידות, ועאכו״כ מערער שימת לב, זאל זיין פארבונדן מיט לימודי קודש, און בלויז דאס וואס איז מוכרח לכל הדעות זאל מען אפגעבן אויף לימודי חול.\n(דאס איז אין צוגאב צו דעם אז דאס לערנען לימודי חול זאל ניט זיין אי־נדערפרי בתחילת הלימוד — „ראשית עריסותיכם״⁴⁵,\nעס איז לגמרי ניט נגד החוק, אז „ראשית עריסותיכם״ זאל זיין „תרימו תרומה לה׳״ — מ׳זאל אויפהויבן דעם קינד צום אויבערשטן, דורך לימוד תורתו של הקב״ה⁴⁶, און ערשט דער־נאך, בשעת דער קינד איז שוין פאר־מאטערט, און מ׳האט ניט קיין ברירה, גיט מען א משך זמן הכי מצומצם אויף לימודי חול).\nאון וויבאלד אז „איני מבקש כו׳ אלא לפי כחן״⁴⁷, איז א זיכערע זאך, אז מיט א השתדלות הכי קלה ובשימת לב המתאימה קען מען גלייך מקטין זיין דעם זמן וואס אידישע קינדער לערנען לימודי חול, און אפגעבן שלא בערך מערער זמן, סיי בכמות סיי באיכות, אויף לימודי קודש — די החלטה דארף נאר זיין אין אן אופן וואס מ׳פילט אז דער ענין איז א דבר המוכרח וארום אזוי איז דער פסק דין אין הל׳ ת״ת⁴⁸, און דעמאלט איז א דבר ברור אז מ׳וועט דאס דורכפירן.\nאון כשם ווי מ׳האט געזען ביים בעל ההילולא, אז ניט קוקנדיק אויף דעם וואס בימיו האט זיך ניט געזען קיין אויסזיכט אין דרך הטבע אז זיין השד־תלות אין חינוך על טהרת הקודש במדינה ההיא זאל מצליח זיין — זעט מען איצטער די פירות פון דער השתדל־לות בעיני בשר\n— אז מ׳גייט ארויס אין גאס אין די",[["42","42","שבועות כא, ב. וש״נ."],["43","43","גיטין י, ב. וש״נ."],["44","44","לשון כ״ק אדמו״ר (מהורש״ב) נ״ע כשה־מלוכה דרשה מהרבנים לעשות שינויים בחינוך כו׳ — חזר עליו כ״ק מו״ח אדמו״ר בצאתו ממאסרו לנסוע לעיר מקלטו קאסטראמא — נדפס בסה״מ קונטרסים ח״א ע׳ 350. לקו״ד ח״ד תרצב, א. ועיי״ש המשך הדיבור."],["45","45","שלח טו, כ. וראה סה״מ קונטרסים שם קסה, א."],["46","46","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081318\" data-slug=\"likkutei-sichot\" data-id=\"1300081318\">לקו״ש ח״ב ע׳ 319</a>. ח״ח ע׳ 307 ואילך."],["47","47","במדב״ר פי״ג, ב."],["48","48","לאדה״ז פ״ג ס״ז, וש״נ."]]],[1300161162,"גרויסע שטעט אין ארצות הברית אדער ערגעץ אנדערש און מ׳טרעפט אייניק־לעך וואס שטאמען פון עלטערן וואס זיינען געווען מיט צוואנציק אדער פערציק יאר צוריק במדינה ההיא, און מ׳זעט אז דער אייניקל פירט זיך בדרך התורה והמצוה, און מ׳פרעגט: ווי האט מען זיך געקענט האלטן ביי אידיש־קייט?!\nאיז בשעת מ׳איז חוקר ודורש געפינט מען אויס, אז דער פאטער, זיין מדריך, אדער זיין זיידע וכו׳ האבן געהאט א קשר צי א מגע ומשא מיט איינעם פון די שלוחים פון דעם בעל ההילולא וועל־כער האט אים מעורר געווען אויף ענינים פון אידישקייט, און האט גע־לערנט מיט אים און האט זיך באהאלטן מיט אים צוזאמען אויפן בוידעם אדער אין א קעלער כדי צו לערנען וכו׳ — און\nדערפאר איז ער געבליבן ביי אידיש־קייט —\nאיז עד״ז ביי די אלע וואס „הולכים באורחותיו נס״ו״⁴⁹, אז דורך דער השתדלות אין דער עבודה הנ״ל פון מחזק זיין דעם חינוך על טהרת הקודש, וועט מען זיכער מצליח זיין צו אויפ־שטעלן די „צבאות ה׳״⁵⁰ וואס וועלן בקרוב ממש ארויסגיין פון גלות זה האחרון, אין דער גאולה האמיתית והשלימה ע״י משיח צדקנו, ובעגלא דידן.\n(משיחת יו״ד שבט תשל״ז)",[["49","49","אגה״ק סי׳ זך (קמו, א)."],["50","50","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370271\" data-slug=\"torah-or\" data-id=\"3901370271\">תו״א ס, ג</a>. המשך מאמרי ההילולא סעיף יו״ד ואילך."]]],[1300161163,"<h3>בשלח</h3>\nא. אויפן פסוק1 „ויקח שש מאות רכב בחור וגו'\" זאָגן חז\"ל אין מכילתא2 אַז די „בהמות\" וואָס פרעה האָט גענוצט פאַר די „שש מאות רכב\" זיינען געווען פון די „מקנה שהניס הירא את דבר ה'\" — און „מכאן הי' ר' שמעון אומר טוב שבגוים הרוג טוב שבנחשים רצוץ את מוחו\".\nס'איז ידוע די קשיא וואָס מ'פרעגט אויף דעם מאמר: היתכן צו זאָגן, אַז די תורה זאָל פסקנ'ען מ'זאָל הרג'נען אפי' אַ „טוב שבגוים\" — ס'איז דאָך היפך הצדק והיושר3?\nאויף דער קשיא זיינען געזאָגט געווארן כמה וכמה תירוצים4 (וואָס איי־ניקע פון זיי וועלן דאָ ווייטער דער־מאנט ווערן) — ובפרט אין די וויכוחים וואָס גדולי ישראל האָבן געפירט מיט שונאי ישראל במשך הדורות (די וויכוחים וואָס ס'האָט געפירט ר' יחיאל מפריז — פון די גדולי בעלי התוספות — ביז דורותינו האחרונים).\nב. אויף רש\"י בפירושו עה\"ת שטעלט זיך אויף דעם פסוק, איז מע־תיק די ווערטער „וכל רכב מצרים\"5 און איז מפרש6 (ווי אין מכילתא): „ומהיכן",[["1","1","פרשתנו יד, ז."],["2","2","כאן. ועד\"ז בתנחומא כאן (ח). תנחומא באבער וארא כ. יל\"ש שם רמז קפו (אבל שם ובכמה דפוסי ירושלמי — דלקמן — נשמט „טוב שבגוים הרוג\"! — ואולי זהו מפני הצענזאר). ועוד. ובתוס' ע\"ז (כו, ב ד\"ה ולא) גריס כן בירושלמי קידושין (פ\"ד הי\"א). וראה שינויי נוסחאות שם."],["3","3","וגם ע\"ד ההלכה — ראה רע\"ב, לבוש האורה* וצידה לדרך בפירש\"י כאן. וש\"נ."],["4","4","כמה מהם הובאו בתורה שלמה מילואים לפ' וארא (סי\"ט). באוצר הוויכוחים (אייזנשטיין). ועוד."],["5","5","במכילתא (וכן בתנחומא, תנחומא באבער ויל\"ש שם. וראה רש\"י וארא ט, י) הקושיא „משל מי היו הבהמות כו'\" היא על התיבות „ויקח שש מאות רכב בחור גו'\". ומה שרש\"י (משנה ו)מקשה רק על „וכל רכב מצרים\" — אף שלכאו' גם ב„שש מאות רכב גו'\" קשה „משל מי היו הבהמות כו'\" — יש לומר: ב„שש מאות רכב גו'\" אפשר לומר שקנו מתגרי האומות (כמובן בפשטות דסחרו עמהם. וראה גם בראשית לז, כה. מקץ מא, נז. ועוד); משא\"כ „וכל רכב מצרים\" דמדגיש מצרים, ועוד שעכצ\"ל שהי' ריבוי מופלג — דאל\"כ, למה יראו בנ\"י כשראו „מצרים נוסע אחריהם\" (פרשתנו שם, י), והרי היו „שש מאות אלף גו' לבד מטף וגם ערב רב גו'\" (בא יב, לז-לח)? ובפרט את\"ל שכל המצריים היו רוכבים, ולא רגלי (ראה לקמן יד, כג. שם, כה ובפרש\"י). שם, כה (וברש\"י). טו, א. אבל ראה ראב\"ע כאן פסוק ט). וראה גם הערה הבאה. וראה דבק טוב באו\"א קצת. ובזה מתורץ בפשטות למה השמיט רש\"י בבא הג' שבמכילתא — „וא\"ת משל פרעה היו והלא כבר נאמר כו'\" — כי ע\"פ הפשט, אין מסתבר לומר אפילו בקס\"ד שהי' ריבוי בהמות כ\"כ של פרעה (ולהעיר מויגש מז, יז. מ\"א ה, ו. שם י, כו)."],["6","6","לאחרי שמפרש „וכל רכב מצרים — ועמהם כל שאר הרכב\". וי\"ל דכוונתו בזה לשלול הפי' (כבפס\"ז (לקח טוב) ומדרש שכל טוב כאן) דה„רכב בחור\" לא הי' ממצרים אלא ממקומות אחרים, וכדמשמע ממש\"נ „וכל רכב מצרים\" — לכן פרשי' דמש\"נ „וכל רכב מצרים\" פירושו „ועמהם כל שאר *) לכאו' הי' אפשר לומר, דזה נכלל (ע\"ד הפשט) במש\"נ „א\"ת משל מצרים\" — אבל אינו, כי גם ע\"ד הפשט יש מקום לומר שבהמות פרעה לא לקו (וראה לעיל בא י, כה), וכמו שפרעה לא לקה במכת בכורות, אף שגם פרעה בכור הי' (פרש\"י בא יב, כט). וראה לקמן הערה 52. ולהעיר מפרש\"י וארא ו, יג: צום עליו כו'. *) בהנדפס באוצר פירושים (וורשא תרכ\"ב. וכמ\"פ לאח\"ז) השמיטו ההתחלה והסיום של פירושו כאן."]]],[1300161164,"היו הבהמות הללו, א\"ת משל מצרים הרי נאמר7 וימת כל מקנה מצרים ואי\"ת משל ישראל והלא נאמר8 וגם מקננו ילך עמנו, משל מי היו מהירא את דבר ה'9. מכאן הי' ר' שמעון אומר כשר10\nשבמצרים11 הרוג טוב שבנחשים רצוץ את מוחו\".\nאיז לכאורה אינגאנצן ניט פאר־שטאנדיק: חאטש פרש\"י איז געמיינט און עס דארף צו עם אנקומען אפילו אַ גדול בישראל, וואָס דערפאַר איז דער פסק דין בנוגע שנים מקרא ואחד תרגום אז „ירא שמים יקרא תרגום וגם פירש\"י\"12, איז, ווי גערעדט פיל מאַל, פירוש רש\"י אויף חומש צוגעפאַסט און פאַרשטאַנדיק אויך פאַר אַ בן חמש (למקרא), און אין אַן אופן אז צו פאַר־שטיין פשוטו של מקרא13 לאמתתו — דאַרף ער ניט אנקומען צו נאָך מפרשים א.ז.וו. — רש\"י גיט עם אלס בפשטות פירושו, לא חסר דבר (ולא יתור) — על אתר, אָדער אין די פירושי רש\"י וואָס ער האָט געלערנט פריער,\nעפ\"ז, ווײַבאַלד די אויבנדערמאָנטע תמי' איז אַ אויבנאויפיקע אז זי דער־וועקט זיך אויך ביי אַ בן חמש — טאָ ווי ברענגט רש\"י אַראָפ דעם מאמר פון ר' שמעון „כשר שבמצרים הרוג\" ניט צוגעבנדיק דערביי קיין שום ביאור ותירוץ אויף דער תמי'?",[["","","הרכב\", אבל גם ה„שש מאות רכב בחור\" שלפנ\"ז היו ממצרים*. ועפ\"ז מובן מה שרש\"י מביא הקושיא „ומהיכן היו הבהמות הללו\" רק לאחרי שמפרש הנ\"ל: בלי פרש\"י הנ\"ל אין מקום לשאול „מהיכן היו כו'\" על ה„שש מאות גו'\", שהרי אפשר לומר שקנו מאומות העולם, וכנ\"ל בהערה הקודמת (וראה בשכל טוב שם, שמקשה (רק) על „וכל רכב מצרים\" — „ומהיכן הי' הרכב במצרים\"): אבל ע\"פ הנ\"ל דגם ה„שש מאות גו'\" היו ממצרים — הרי שוב קשה גם עליהם „ומהיכן היו הבהמות הללו\". וראה דבק טוב שבהערה הקודמת."],["7","7","וארא ט, ו."],["8","8","בא י, כו."],["9","9","ל' הכתוב וארא שם, ב. וראה רש\"י שם, י. ראי\"ם וס' זכרון בפרש\"י כאן."],["10","10","במכילתא שלפנינו (וכן בכמה מקומות. וכן בדפוס שני דרש\"י): טוב. אבל בירושלמי* קדושין (פ\"ד הי\"א), מכילתא דרשב\"י כאן, תנחומא באבער שם, ס' והזהיר (עה\"פ הירא את דבר ה'), פס\"ז וארא ט, כ (משא\"כ כאן), ומדרש הגדול כאן (וכן הוא גירסת התוס' (ע\"ז כו, ב ד\"ה ולא) במס' סופרים (ספט\"ו)): כשר. וראה לקמן הערה 34."],["11","11","במכילתא שלפנינו (וכן בכמה מקומות. וכן בדפוס שני וכמה כת\"י דרש\"י*): שבגוים. אבל בתנחומא כאן, תנחומא באבער, ופס\"ז וארא שם (וכן גריס הבחיי במס' סופרים (שם). וכ\"ה בבעה\"ט* וארא שם): שבמצרים. ולכאורה כ\"ה הגירסא הנכונה (עכ\"פ ברש\"י) — שהרי נלמד „מכאן\", שהמדובר במצרים. אבל גם בכמה מפרשי רש\"י הובא „שבגוים\" (וכיו\"ב). ואין מסתבר שהבחור הזעצער שינה מ„שבמצרים\" ל„שבגוים\" — כי מה „תיקון\" בזה? (משא\"כ בשינוי מ„שבגוים\" ל„שבמצרים\", כמובן)."],["12","12","שו\"ע (ואדה\"ז) תאו\"ח סרפ\"ה ס\"ב."],["13","13","פרש\"י בראשית ג, ח. ובכ\"מ. *) ומה שנפרטו בפ\"ע — מפני שהיו „רכב בחור\". ולכן מדייק רש\"י „ועמהם כו'\", כלומר שהיו טפלים להם. וכמ\"ש במפרשי רש\"י (גו\"א. דבק טוב. נח\"י (הובא במשכיל לדוד). ועוד) כאן. ברא\"ם כ' דכוונת רש\"י ב„ועמהם כל כו'\" שהם „הלכו מעצמם כו' לא שהם מהלקוחים\" — אבל (נוסף לזה, בפשטות קאי תיבת „ויקח\" גם על „וכל רכב מצרים\". וראה נחל\"י שם — הרי) לפ\"ז זה העיקר חסר בפירש\"י, והול\"ל „ועמהם הלכו\" וכיו\"ב. ומ\"ש במשכיל לדוד, דממש\"א ר\"ש „כשר שבמצרים הרוג\" הוי ראי' להרא\"ם דהלכו מרצונם הטוב — אי\"ז סתירה שגם הם „מהלקוחים\" — ראה לקמן הערה 42 ובשוה\"ג שם. *) בכמה דפוסי ירושלמי נשמטה בבא זו, כנ\"ל. *) אבל בהוצאה חדשה (א\"י, תשל\"א): „שבגוים\", ומציין דכ\"ה בדפו\"י (ובכתי\"י חסרה מלה זו)."]]],[1300161165,"נאָך שווערער איז: דער בן חמש האָט שוין פריער געלערנט14, אַז ווען אברהם אבינו איז געווען אין מצרים, האָט פרעה מטיב געווען צו אברהם'ען און אים אוועקגעשיקט פון דאָרט מיט דער כוונה צו פאַרהיטען אים און שרה פון שלעכטס;\nנאָך מער דערפון האָט ער געלערנט: בשעת יעקב ובניו זיינען געקומען זיך צו באַזעצן אין מצרים, האָט פרעה אליין מיט זיין אייגענעם ווילן, פאַרגעלייגט צו באַזעצן זיי אין „מיטב הארץ\"15, ביז אז דער באַזעצן זיך איז געווען אין אַן אופן (ווי דער פסוק16 דערציילט) פון „ויאחזו בה ויפרו וירבו מאד\"17 —\nהיינט ווי איז שייך צו זאָגן אז „כשר שבמצרים הרוג\", בשעת מ'געפינט אז עס זיינען געווען אזעלכע מצרים וואָס האָבן זיך באַצויגן צו אידן ווי עס דאַרף צו זיין, מיט זיי געלעבט בשלום ושלוה, ואדרבא — מטיב געווען וכו'?\nביים בן חמש וועט די סתירה זיין נאָך שאַרפער ווען ער וועט לערנען פ' תצא18, וואו עס קומט א ציווי מפורש: „לא תתעב מצרי גו'\" — אז ס'איז אן איסור צו נאָר אפילו „מתעב\" זיין א מצרי, און אוודאי ניט צו הרג'נען אים!\nועוד: אויב „כשר שבמצרים הרוג\", ווי קען מען מקיים זיין (דעם המשך הכתוב, דארט) „דור שלישי יבוא להם בקהל ה'\"19? — אמת אז דאָס וואָס ער קומט זיך\nמגייר זיין, איז א סימן אז ער איז א „כשר שבמצרים\" — זאָגט דאָך אבער ר' שמעון אז אפילו „כשר שבמצרים הרוג\"!\nאון ווײַבאַלד אזוי, האָט עס רש\"י עכ\"פ געדאַרפט באוואַרענען אין פ' תצא.\nג. איינער פון די תירוצים וואָס מ'געפינט אין אַ סך ספרים20 איז: אין מס' סופרים21 איז די גירסא „הטוב שבעכו\"ם בשעת מלחמה הרוג\", אַז דאָס וואָס מען מעג (אָדער מ'דארף) הרג'נען אפילו אַ „טוב שבעכו\"ם\", איז דאָס געזאָגט געווארן נאָר בשעת מלחמה מיט אידן, אבער ניט אין אַנדער מצב — פון ניט־מלחמה, ומכל שכן בשעת שלום.\nעד\"ז וואָלט מען לכאורה געקענט איינלערנען אויך אין פירוש רש\"י22: ער מיינט נאָר בשעת מצרים קומען מלחמה האלטן מיט אידן — ווארום דאָס וואָס דער „ירא את דבר ה'\" איז דעמאָלט נענש געווארן, איז עס פארגעקומען ווען די מצרים האָבן נאכגעיאגט די אידן מלחמה צו האלטן מיט זיי ביים ים סוף.\nמען קען אבער אזוי ניט לערנען אין פירוש רש\"י (דרך הפשט) — ווייל „מכאן הי' ר\"ש אומר כשר שבמצרים הרוג\" מיינט: א) אז פון דאנעט לערנט אַפ אויך אנדערש וואו, ב) מכאן — פון",[["14","14","לך יב, טז. שם, כ ובפרש\"י (יט-כ)."],["15","15","ויגש מה, יח ובפרש\"י. שם מז, ו."],["16","16","ס\"פ ויגש."],["17","17","ואף להפירוש ב„ויקם מלך חדש\" (שמות א, ח וברש\"י) „שנתחדשו גזירותיו\" — הרי ממש\"נ „ויקם מלך חדש\" (ו„נתחדשו גזירותיו\") מובן שהי' ענין של חידוש."],["18","18","כג, ח."],["19","19","פסוק ט."],["20","20","ראה בספרים שבהערה 4. לקמן הערה 22. תוס' ע\"ז שבהערה 2. כס\"מ הל' רוצח פ\"ד הי\"א. ב\"י וב\"ח יו\"ד סקנ\"ה. ש\"ך שם. סמ\"ע חו\"מ סתכ\"ה סקי\"ח."],["21","21","ספט\"ו. ובתוס' ע\"ז שם לא גריס כן במס' סופרים, כ\"א בירושלמי קידושין (שם). אבל בירושלמי שלפנינו ליתא תיבות „בשעת מלחמה\", וכמ\"ש בצידה לדרך כאן."],["22","22","כדפי' בגו\"א כאן. וראה בחיי וצידה לדרך כאן. ובלבוש האורה: עכשיו נהפך לבם לשונאים ולהרוג ולאבד רדפו."]]],[1300161166,"דעם „ויקח גו' רכב מצרים\" — פון דער פאַסירונג פון דעם נעמען, ווייבאַלד אז דער „ירא את דבר ה'\" פון די מצרים האָט געגעבן זיינע בהמות צו פרעה, איז צוליב דעם איז ער ווערט געווען דעם עונש וואָס דער אויבערשטער האָט אויף אים געבראַכט בשעת קרי\"ס — „הרוג\"23; ד.ה. אז עונש מיתה האָט אים געקומט ניט מצד זיין מלחמה בפועל מיט אידן, נאָר צוליב דעם אַליין וואָס ער האָט געגעבן די בהמות צו פרעה מיט דער שלעכטער כוונה — נאָר פאַר דער „שעת מלחמה\", נאָך איידער פרעה און די מצרים זיינען אריין אין מלחמה בפועל מיט אידן.\nד. אפילו מ'זאָל זאָגען אז אויך דאָס (ויקח — צוליב שפעטער מלחמה האָבן) ווערט געמיינט מיט „בשעת מלחמה\" — קען מען אבער מצד אן עיקר'דיקן טעם ניט זאָגן אז רש\"י מיינט „בשעת מלחמה הרוג\": ווי געזאָגט, האָט רש\"י געשריבן זיין פירוש אויך פאַר אַ בן חמש — און דעריבער איז, כנ\"ל, אַלץ וואָס ס'איז נויטיק אין פשש\"מ האָט רש\"י געשריבן פשוט און קלאָר — ובמילא, אויב רש\"י וואָלט געמיינט „בשעת מלחמה הרוג\", וואָלט ער אָט די ווערטער געבראַכט בפירוש אין זיין פירוש (און וואָלט זיך ניט פארלאָזט, אז דער בן חמש וועט זוכען ביז ער וועט אויסגעפינען זיין — רש\"י'ס — כוונה . . אין מס' סופרים).\nובפרט אז לויט דעם תירוץ איז דאָך „שעת מלחמה\" — אַ תנאי עיקרי!\nאון מהאי טעמא, איז אויך שווער איינצולערנען די אַנדערע תירוצים וואָס ווערן געבראַכט אין ספרים —\n[לדוגמא: א) אז דער פירוש פון ר' שמעון'ס כלל מיינט (ניט אז דער „כשר שבמצרים\" איז ווערט דעם עונש פון „הרוג\", נאָר): אפילו אַ „כשר שבמצרים\" [איז אזאַ — וואָס זאָגט] „הרוג\" — בשעת ס'האַנדלט זיך וועגן משפט'ן אַ חוטא וואָס איז פארדעכטיקט אין רציחה, איז אויך דער „כשר שבמצרים\" גרייט אים צו פאר'משפט'ן צום טויט („הרוג\") אויפן סמך פון בלויז אַן אומדנא, אַן געהעריקער חקירה און אַן צו זוכן זכותים24; משא\"כ בא אידן איז דער סדר „ושפטו העדה גו' והצילו העדה\"25, אַז עס פאַדערן זיך עדים און התראה וכו' און מ'דאַרף זוכן זכותים אויפן גע'משפט'ן.\nב) אַז דאָס איז געזאָגט געווארן בלויז בדרך גוזמא, און ס'איז על דרך ווי דער פירוש אין דעם המשך פון ר' שמעון'ס מאמר (ווי ער איז אין מס' סופרים<sup data-n=\"26\">26</sup>: „הכשירה שבנשים בעלת כשפים\" — וואָס, ח\"ו צו זאָגן אויף אַ בת שרה רבקה רחל ולאה, און נאָך „הכשירה שבהן\", אַז זי איז אַ „בעלת כשפים\"! — נאָר ס'איז געזאָגט געווארן בדרך גוזמא צו מדגיש זיין אויף וויפל מ'דאַרף אין דעם זיין געוואָרנט אפילו בשייכות צו „כשירה שבנ־שים\"27; און עד\"ז ביי „כשר שבמצרים",[["23","23","בלבוש שם פי' המשך דברי רש\"י: „מכיון שכל הבהמות הללו הי' משל הירא דבר ה' בלי ספק כל מי שהי' לו בהמה משלו הי' הוא בעצמו ראשון מן הרודפים כו'\" (וראה לקמן הערה 42), ולכן נהרגו להיותם מן הרודפים (וכנ\"ל בהערה הקודמת) — אבל מפשטות המשך דברי רש\"י — „משל הירא את דבר ה' מכאן הי' רש\"א כו'\" — משמע, שרק משו\"ז שנתנו בהמתם צ\"ל — „הרוג\"."],["24","24","בויכוח דון שמואל אברבנאל ודון שלמה הלוי — נדפס בס' שבט יהודה (נעתק בס' שבהערה 4. והובא בסמ\"ע חו\"מ שם)."],["25","25","מסעי לה, כד-כה. ראה ר\"ה כו, א. ועוד."],["26","26","שם. וכן בירושלמי קידושין שם. ועוד."],["27","27","ראה פני משה לירושלמי קידושין שם."]]],[1300161167,"הרוג\", אז דאָס מיינט ניט כפשוטו, נאָר מיט אַ גוזמא'דיקער שטאַרקער הדגשה ווי ווייט מ'קען זיך אויף זיי ניט פאַר־לאָזן.\nג) אין דער צייט פון ר' שמעון האָבן אידן געליטן אַ סך צרות וגזירות פון שונאי ישראל — און זיי האָט ר' שמעון געמיינט מיט זיין מאמר „כשר שבמצרים הרוג\", ווייל זיי האָבן ארויסגעוויזן אַן אפענע שנאה צו אידן (בדוגמא ווי אַ „נחש\" — וואָס ווערט דערמאָנט גלייך נאָכדעם — וואָס איז פול מיט גיפט); אבער ער מיינט ניט גוים בכלל, און אפילו ניט די מצריים. והא ראי', מען געפינט דאָך כמה מאמרי רז\"ל וואָס זיינען מדגיש ווי דער אויבערשטער האָט רחמנות געהאַט אויף די מצריים, און נאָכמער איז דאָס בולט אין דעם (טעם אויפן) ציווי „לא תתעב מצרי כי גר היית בארצו\"28] —\nאָט די פירושים וכל כיוצא בהם איז שווער איינצוטייטשן אין פירוש רש\"י, ווייל ווייבאַלד זיי ליגן ניט אין פשטות המשמעות פון די ווערטער וואָס רש\"י ברענגט „כשר שבמצרים הרוג\", האָט רש\"י געדאַרפט צולייגן ווערטער צו מבאר זיין דעם מיין פון „כשר שבמצרים הרוג\";\nהיות אז רש\"י טוט עס ניט, נאָר איז מעתיק נאָר די געציילטע ווערטער פון ר' שמעון ווי זיי שטייען אין מכילתא, מוז מען אננעמען, אז דער ביאור פון דעם ליגט אין ר' שמעון'ס ווערטער גופא, אזוי אז רש\"י דארף גאָרניט צוגעבן אויף צו פאַרענטפערן די קשיא, אפילו ניט צוליב אַ בן חמש.\nה. פון דעם אלעם קומט מען צו דער גרעסטער תמי' אין דעם ענין: נניח אז מ'וועט פארענטפערן רש\"י מכל צד ופינה; מ'וועט מבאר זיין פארוואס ביים בן חמש איז מלכתחילה לגמרי פאר־שטאנדיק און גלאט דער מאמר „כשר שבמצרים הרוג\" — ווערט קשה לאידך גיסא: ווי קומט עס, אז במשך דורות האבן גדולי ישראל זיך געמאטערט צו פארענטפערן די קשיא און האבן זיך ניט באגנוגנט מיט אט דער אויפקלערונג וואס רש\"י האט פאר א בן חמש?\nווארום עס איז זיכער, אז דא ווערט ניט געמיינט צו פארענטפערן די שאלה פון א בן חמש מיט א הסבר לפי השגתו, וואס איז אבער ניט דער אמת'ער טעם וביאור (וועלכן ער וועט ערשט געפינען בספרים הנ\"ל ווען ער וועט גרעסער ווערן) — ח\"ו צו זאגן אז רש\"י לערנט מיט א בן חמש שלא אליבא דאמת — נאר געוויס איז אז רש\"י איז אויסן דעם טעם וביאור האמיתי, וועלכער איז אזויפיל פשוט אז רש\"י דארף גארניט מוסיף זיין אויפן לשון המכילתא — אפילו צוליב דעם בן חמש; און לאידך, האט מען זיך ניט באגנוגנט מיט אט דעם ביאור אין די אלע וויכוחים!\nו. אויך דארף מען פארשטיין:\nא) פירוש רש\"י איז ניט קיין ספר צו פסק'נען הלכות, נאר צו מפרש זיין דעם פשט פון די כתובים — טא וואס איז בכלל נוגע אין פירוש הכתובים צו אראפברענגען „מכאן הי' ר\"ש אומר כו'\"? — אויף צו פארענטפערן די קשיא „מהיכן היו הבהמות הללו\" איז דאך גענוג צו זאגן אז זיי זיינען געווען „מהירא את דבר ה'\" — און ניט מער.\nב) אויב אפילו רש\"י דארף דאס באווארענען אז אויך דער „ירא את דבר ה'\" האט ניט געטויגט — כדי צו פארענטפערן די שאלה: ווי קומט א „ירא את",[["28","28","וראה גם גו\"א כאן."]]],[1300161168,"דבר ה'\" געבן זיינע בהמות צו פירן אַ מלחמה מיט אידן — איז אבער נאָך אלץ ניט גלאטיק: וואָס איז נוגע דער אויס־פיר אז ער איז ווערט דעם עונש פון „הרוג\"?\nג) דער המשך וסיום „טוב שבנחשים רצוץ את מוחו\" האָט, לכאורה, לגמרי קיין שייכות ניט צום פירוש פון אונזער פסוק29?\nד) וואָס דארף'ן אַפלערנען „מכאן\" אַז „טוב שבנחשים רצוץ את מוחו\"30 — ס'איז דאָך מקרא מלא דיבר הכתוב31: „ואיבה אשית בינך גו' הוא ישופך ראש\"32?\nז. אויך זיינען דא נאָך דיוקים אין דעם פירוש רש\"י:\nא) צוליב וועלכן טעם ברענגט דאָ רש\"י אויך דעם נאָמען פון בעל המימ־רא — ר' שמעון33? — וואָרום (ווי גערעדט כמה פעמים) דערמאָנט עס רש\"י נאָר דאָן ווען דאָס איז מוסיף ביאור אין זיין פירוש.\nב) ביי „כשר שבמצרים\" זאָגט ער דעם לשון „הרוג\" און ביי „טוב שבנ־חשים\" — „רצוץ את מוחו\"34?\nג) באם לשון „רצוץ\", וואָלט רש\"י לכאורה געדארפט זאָגן „רצוץ את ראשו\"35, בהתאם צום לשון הכתוב: „הוא ישופך ראש\", „רצצת ראשי לו־יתן\"*35?\nד) וואָס איז דער דיוק „מכאן הי' ר' שמעון אומר כו'\", וואָס קומט שולל צו זיין אז מ'קען עס ניט אפלערנען ממקום אחר, נאָר דוקא „מכאן\"?\nח. בכדי צו מבאר זיין דעם ענין דארף מען מקדים זיין נאָך אַ כלליות־דיקע שאלה וואָס מ'קען פרעגן אין דעם פירוש רש\"י:\nלכאורה, איז דאָך די גירסא ווי זי שטייט אין מס' סופרים — „הטוב שבעכו\"ם בשעת מלחמה הרוג\" — אויסגעהאלטן אויך אין פשש\"מ: היות די מצרים זיינען געקומען מלחמה האלטן מיט אידן [און אויך דאָס וואָס דער אוי־בערשטער האָט מעניש געווען די מצרים איז געווען אין אַן אופן פון",[["29","29","וראה רא\"ם כאן: לאו מהכא דייק לה אלא אגב כו'."],["30","30","ראה רא\"ם שבהערה הקודמת ד„לאו מהכא דייק לה\" (וראה ריב\"א כאן ע\"ד הדרש) — אבל ראה גו\"א ולבוש כאן."],["31","31","בראשית ג, טו."],["32","32","ואין לומר דהחידוש הוא „טוב שבנחשים כו'\", דאין לסמוך גם על נחש שהוא בן תרבות (ראה גו\"א ולבוש כאן. פני משה לירושלמי קדושין שם) — שהרי גם בפסוק „ואיבה אשית גו' הוא ישופך ראש\" נאמר באופן סתמי — על כל הנחשים, והרי כולם בכלל „זרעך\"."],["33","33","בל' רש\"י שבריב\"א (וכן בדפוס שני דרש\"י): ר' ישמעאל. אבל בשאר דפוסי רש\"י, וכן במקומות שבהערה 2 (לבד מתנחומא. ושם: מכאן אמרו כו'). פס\"ז ושכל טוב וארא ט, כ. פס\"ז כאן, ועוד (וכן בירושלמי ומס' סופרים שם) הוא — ר' שמעון (סתם — בן יוחאי)."],["34","34","ואף שכ\"ה במכילתא (ושאר המקומות שבהערה הקודמת) — הרי כמדובר כמ\"פ, רש\"י אינו מעתיק בפירושו לשונות של רז\"ל שאינם שייכים לפשש\"מ ופירוש הכתובים על אתר (ולפעמים גם משנה בלשון רז\"ל או אפילו בלשון הכתוב שיתאים לפשש\"מ, כמדובר כמ\"פ), ובמילא מובן שהלשון „רצוץ את מוחו\" שייך לפירוש הכתובים כאן. ומה שרש\"י בוחר בהגירסא „כשר שבמצרים\" (ראה לעיל הערה 10) — אף שבנחש כ' „טוב\" — י\"ל, דבא לרמז דאף שהמצרי „כשר\", וראוי להיות (או שיהי' ממנו) גר, בכ\"ז — „הרוג\". ראה גו\"א כאן. וראה לקמן הערה 54."],["35","35","כבמדרש שכל טוב וארא שם. *35) תהלים עד, יד. וראה שינויי נוסחאות בירושלמי שם."]]],[1300161169,"„מלחמה\", ווי דער פסוק זאָגט36: „ה' ילחם לכם גו'\", „ה' נלחם להם גו'\"] פאַר־שטייט אויך אַ בן חמש אז ווען מ'פירט אַ מלחמה מיט אַ שונא קען מען ניט אויס־טיילן די „כשרים\" פון דעם צד שכנגד (בשעת דער מלחמה גופא) —\nאון אויב אזוי — איז זי, אדרבא, גלאטער פון דער גירסא וואס רש\"י ברענגט — פון דער מכילתא, וואו עס שטייט סתם — „כשר שבמצרים הרוג\" [וואָס: א) דאָס מיינט צו יעדער צייט און ביי אלע אומשטענדן — וואָס דאָס איז לגמרי היפך הצדק והיושר; ב) דאָס איז מדגיש אז דעם „ירא את דבר ה'\" האָט געקומען מיתה בלויז דערפאַר וואָס ער האָט געגעבן זיינע בהמות צו פרעה (כנ\"ל ס\"ג)]?\nנאָר אין דער אמת'ן איז דאָס קיין קושיא ניט: אין דרך הפשט איז פאַר־שטאַנדיק, אז דער נס פון קרי\"ס און פארטיליקונג פון די נאכיאגנדיקע מצרים, איז ניט געקומען בלויז מחמת דעם וואָס די מצרים האָבן נאכגעיאגט די אידן און מיט זיי מלחמה געהאט — וואָרום עס שטייט פריער אין פסוק37 אז דער אויבערשטער האָט געזאָגט משה'ן: „וחזקתי את לב פרעה ורדף גו'\", און אזוי אויך אין פסוק שפעטער38 „ויחזק ה' את לב פרעה גו', וירדף גו'\", און ווייבאַלד דאָס נאכיאגן דערפאר וואָס דער אויבערשטער האָט געשטארקט פרעה'ס הארץ, קומט דאָך ניט קיין עונש דערפאַר!39 — נאָר ס'איז געווען אַ המשך פון די אלע פריערי־\nדיקע מכות וואָס דער אויבערשטער האָט געבראַכט אויף די מצרים צוליב דעם וואָס זיי האָבן די אידן געפייניקט און משעבד געווען במשך אזויפיל יארן40; און אלס אפשלוס41 פון די אלע מכות האָט דער אויבערשטער גע־בראַכט דעם גרעסטן עונש — דעם נס פון קרי\"ס וואָס דורך דעם „לא נשאר בהם עד אחד\".\nאון דערפאַר קען רש\"י ניט ברענגען די גירסא פון מס' סופרים אז (נאָר) „בשעת מלחמה\" דארף מען הרג'נען אפי' אַ „טוב שבעכו\"ם\" — היות דער פסוק מיינט ניט צו זאָגן אז די רדיפה ומלחמה פון די מצרים איז געווען די סיבה פון זייער אומקום בים סוף.\nט. לויט דעם איז מובן פארוואס רש\"י מוז אראפברענגען „מכאן הי' ר\"ש אומר כו'\" (הגם פרש\"י איז ניט קיין ספר הלכות): פון דעם וואָס רש\"י זאָגט אז די וואָס זיינען געווען „ירא את דבר ה'\" האָבן געגעבן זייערע בהמות צו פרעה, איז מובן אז אויך זיי זיינען געווען ביי קרי\"ס42 און במילא, אז אויך זיי זיינען",[["36","36","פרשתנו יד, יד. שם, כה."],["37","37","שם, ד."],["38","38","שם, ח."],["39","39","להעיר מפרש\"י וארא ז, ג. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061062\" data-slug=\"likkutei-sichot\" data-id=\"1300061062\">לקו\"ש ח\"ו ס\"ע 62</a> ואילך."],["40","40","ראה פרש\"י לקמן (יד, כה): שכשם שאלו כו' כך לוקים אותם שנשארו במצרים. אבל להעיר מפרש\"י לך (טו, יד): „דן אנכי — בעשר מכות\"."],["41","41","וראה לקו\"ש ח\"ג (ע' 878 ואילך. וש\"נ) דקרי\"ס הי' הגמר דיצי\"מ, עיי\"ש."],["42","42","כמ\"ש בלבוש כאן (נעתק לעיל הערה 23). ויובן יותר ע\"פ פרש\"י לעיל (פסוק ו) ד„לקח עמו\" — „משכם בדברים כו' אני אשוחה עמכם בחלק כו'\", ומזה מובן שגם לקיחת הבהמות היתה באופן כזה ע\"י ש„משכם בדברים\"* [אף שהפירוש ב„ויקח\" כאן *) ובזה מתורצת בפשטות קושיית המשכיל לדוד כאן (וכן קושיית הלבוש שבהערה 46) „דילמא לעולם כשרים היו אלא דבאונס המלך לקח כל הבהמות שלהם\" (ובפרט שע\"כ צריך לפרש כן הס\"ד „וא\"ת משל ישראל היו\" — שהרי פשוט שבנ\"י לא נתנו בהמתם לפרעה מעצמם) — כי כבר פרש\"י לעיל דאופן הלקיחה הי' ע\"י ש„משכם בדברים\"."]]],[1300161170,"באשטראפט געווארן צוזאַמען מיט די אַנדערע מצרים — פאַדערט זיך אַ סברה43: ווי קומט עס וואָס אויך דער „ירא את דבר ה'\" איז אומגעקומען ביי קרי\"ס צוגלייך44 מיט די וואָס זיינען ניט געווען „ירא גו'\" (ווי דער פסוק זאָגט45: „לא נשאר בהם עד אחד\") בלויז צוליב דעם וואָס זיי האָבן געגעבן זייערע בהמות?\n(אויב מ'וואָלט געזאָגט אז זייער אומ־קומען איז געווען צוליב זייער רדיפה לשם מלחמה וואָלט געווען רעכט פאַר־שטאַנדיק — וואָס עס קומט זיי אָט דער עונש (און רש\"י דארף עס גאָרניט באווארענען<sup data-n=\"46\">46</sup>: ווייבאַלד אבער איז ניט דער נאכיאגן איז געווען די סיבה, איז שווער צו פאַר־שטיין, פארוואס דער עונש איז געווען אויף די וואָס זיינען געווען „ירא את דבר ה'\")\nהוא כפשוטו — פעולת הלקיחה — שהרי קאי על „רכב\"] — ובמילא פשוט ש(לא רק שנתנו בהמתם, אלא) גם הם רדפו „בשביל ממונם שהשאילום\" (פרש\"י לעיל פסוק ה').\n(אבל לולי זה אפ\"ל ש„הירא את דבר ה'\" נשארו במצרים, שהרי גם לאחרי קרי\"ס נשארה אומה במצרים, וכדמוכח ממש\"נ (שלח יד, ד) „נתנה ראש ונשובה מצרימה\" (וראה תשא לב, יב. פרש\"י לקמן יד, כה. ועוד), וכמובן גם בפשטות הדברים שלא כל האומה יצאה לצבא).\nובפרט, אז דער בן חמש האָט שוין געלערנט אין דער פרשה פון סדום ועמורה47, אַז אויב דארטן וואָלטן זיך געפונען בלויז (ניין) צען צדיקים, וואָלטן זיי ניט נאָר אַליין געראטעוועט געווארן, נאָר זייער זכות וואָלט מגין געווען אויף אלע אינוואוינער פון זייער שטאָט; און דאָ איז געווען פונקט דער היפך: ניט נאָר האָבן זיי (פונעם סוג פון „ירא את דבר ה'\") ניט מגין געווען צו ראטעווען די אנדערע מצרים פון כלי', נאָר אויך זיי אליין זיינען ניט ניצל געווארן.\nדערפאַר ברענגט רש\"י דעם מאמר פון ר\"ש „מכאן כו' כשר שבמצרים הרוג טוב שבנחשים כו'\", בכדי צו מסביר זיין, אז דער עונש פון דעם „ירא\" איז ניט געווען צוליב דעם אַליין וואָס ער האָט געגעבן זיינע בהמות צו פרעה'ן: נאָר דער הארבער עונש פונעם „ירא\" איז אַ הוכחה, אז זיין געבן די בהמות איז אַ תוצאה פון זיין שנאה צו אידן, אין וועלכער ער איז גלייך מיט די אַנדערע מצרים48 — אָט די גיפטיקע שנאה (בדוגמא פון אַ נחש) וואָס האָט באַ־וואויגן אלע מצרים צו פייניקן די אידן אזוי שטארק און אזויפיל יארן, און וואָס דערפאַר איז אויף זיי אלע נגזר גע־וואָרן (אויך אויף דעם „ירא\"), דער עונש פון „הרוג\" — „לא נשאר בהם עד אחד\".\nי. דערמיט איז אויך מובן די הד־גשה „מכאן כו' כשר שבמצרים הרוג\" — ווייל ביז דעם עונש פון קרי\"ס איז נאָך ניטאָ קיין קלאָרער באַוויז אז אויך ביים „ירא את דבר ה'\" איז געווען די",[["43","43","וע\"ד מ\"ש בלבוש כאן."],["44","44","בענין המיתה — וראה פרש\"י לקמן טו, ה (ד\"ה כמו אבן)."],["45","45","יד, כח."],["46","46","וראה צידה לדרך כאן. — בלבוש שם כ' דאפ\"ל „שלא הלכו להרוג את ישראל רק הלכו לכבוד פרעה כו'\", ולכן מביא רש\"י „כשר שבמצרים הרוג\", כלומר „ודאי הש\"י הבוחן כל לבות כו' יודע כו' עכשיו נהפך לבם לשונאים ולהרוג ולאבד רדפו כו'\" — אבל (נוסף על המבואר לעיל ס\"ג ובהערה 23, דכוונת רש\"י היא שנהרגו (לא משום שרדפו אחרי בנ\"י, כ\"א) משום שנתנו בהמתם לפרעה — הרי) מפרש\"י לעיל (פסוק ו) מוכח שהלכו מרצונם הטוב, וכנ\"ל הערה 42."],["47","47","וירא יח, כג ואילך."],["48","48","ולא רק כמ\"ש בלבוש ד„עכשיו נהפך לבם לשונאים כו'\"."]]],[1300161171,"שנאה און רשעות צו אידן און אזא גרוי־סער מאָס אז אים זאָל קומען דערפאַר דער עונש „הרוג\" צוגלייך מיט אַלע מצרים:\nדאָס וואָס ביי די מכות (אויסער דבר49 און ברד<sup data-n=\"50\">50</sup> געפינען מיר ניט אז דער „ירא\" זאָל זיין אויסגעטיילט פון די אַנדערע מצרים, איז נאָך קיין ראי' ניט אַז ער איז פון זיי ניט אפגעשטאַנען אין זיין שנאה און רשעות צו אידן, ווייל ווײַבאַלד יענע מכות זיינען ניט געווען דער גרעסטער, פולער עונש, פון מיתה51, פאַדערט זיך ניט די גרעסטע פולע מאָס רשעות פון די מצרים, ער קען קומען אלס עונש אויף אַ קלענערע מאָס שנאה און רשעות וואָס דאָס האָט אויך געהאַט דער „ירא את דבר ה'\", און דערפאַר איז ער אויך ווערט געווען דעם עונש פון די מכות52:\nאון אפילו מכת בכורות, וואָס איז שוין געווען אַן עונש מיתה („הרוג\") — האָט דאָך שוין רש\"י פריער53 מפרש געווען אַז „למה לקו בני השפחות שאף הם היו\nמשעבדים בהם ושמחים בצרתם\", ד.ה. אז אויך אָט דער עונש מיתה, זייענדיק אבער ניט אויף דער גאנצער משפחה — נאָר אויף אַ קליינע טייל פון דער משפחה — אויף די בכורות, איז ניט דוקא פאַר דער פולסטער רשעות פון די מצרים, און דערפאַר זיינען אויך די „בני השפחות\" געווען בכלל די מכה;\nדוקא „מכאן\" — וואו די פארניכטונג פון די מצרים (ביי קרי\"ס) איז געווען אין אַן אופן פון „לא נשאר בהם עד אחד\"54 — איז אַ ראי' אז אויך דער „ירא את דבר ה'\" („כשר שבמצרים\") פון יענעם דור, איז געווען בשווה ממש מיט אלע אַנדערע מצרים אין זיין פולסטע שנאה ורשעות צו אידן, און דערפאַר אויך אין דעם עונש פון „הרוג\".\nיא. לויט דעם איז אויך פאַר־שטאַנדיק פארוואס „כשר שבמצרים הרוג\" — רש\"י ברענגט עס בכדי צו פאַרענטפערן די שוועריקייט אין דעם פסוק, פארשטייט מען פשוט אז „כשר שבמצרים כו'\" מיינט די מצרים (פון",[["49","49","פרש\"י וארא ט, י."],["50","50","וארא שם, כ."],["51","51","וגם מכת ערוב — לא נאמרה בה מיתה. ועיין בפרש\"י (וארא ח, יז): „והיו משחיתים בהם\" — שהוא ע\"ד „תשחת הארץ\" (שם, כ)."],["52","52","ומה שלא לקו במכת דבר וברד — מפני שהי' צ\"ל בזה מיתה, וכמש\"נ (ט, טו): כי עתה גו' ותכחד מן הארץ (אלא שבעבור זאת כו' — פרש\"י שם). וי\"ל (ע\"ד ההלכה) דגם בפועל הרי הי' בהן מיתת בהמתם — ראה מרז\"ל (מכילתא, שמו\"ר ויל\"ש — עה\"פ פרשתנו יז, ג. והובא ברמב\"ן שם) דבהמתו של אדם היא חייו כו'. וראה להלכה שו\"ע אדה\"ז חאו\"ח סרמ\"ח סי\"ג (ממג\"א שם). ולהעיר מרשב\"א ב\"ק (קיב, א): דדיני השור כדיני נפשות דכמיתת הבעלים כך מיתת השור. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161330\" data-slug=\"likkutei-sichot\" data-id=\"1300161330\">לקו\"ש חי\"ו ס\"ע 330</a> ואילך."],["53","53","בא יא, ה. וראה גם פרש\"י שם יב, כט (לענין „בכור השבי\"): שהיו שמחין כו' (אבל ראה פרש\"י --- שם יא, ה — ד\"ה עד בכור השבי). ולהעיר מזה דגם „בכורות אחרים והם במצרים\" נהרגו (פרש\"י שם יב, יב. שם, כט)."],["54","54","וי\"ל (ע\"ד הרמז): במכת בכורות ד„וה' הכה כל בכור גו'\", אפ\"ל דגלוי לפניו שבין המוכים לא היו כאלה שעתידים להיות מהם גרים, ולכן אא\"פ ללמוד מכאן (הוראה לבנ\"י) „כשר שבמצרים הרוג\" — שהרי אולי יהיו ממנו גרים (ראה לעיל הערה 34): משא\"כ קרי\"ס ד„ה' ילחם לכם\" („בשבילכם\" — פרש\"י) — שלחם עם מצרים במקום מלחמת בנ\"י ובדוגמת מלחמת בר\"ד כביכול [וראה לקו\"ש ח\"ה ע' 256, שמטעם זה מדגיש הכתוב (יד, כג) „סוס פרעה\" — ל' יחיד — להגיד ש(אעפ\"כ) „אין כולם חשובין לפני המקום אלא כסוס אחד\" (פרש\"י שם)] שהם אין יכולים להבחין כו', ובכ\"ז לחם באופן ד„לא נשאר בהם עד אחד\" — למדים „מכאן\" דגם „כשר (וראוי להיות ממנו גרים) שבמצרים הרוג\"."]]],[1300161172,"יענעם דור) וועגן וועלכע עס רעדט זיך אין פסוק — אז יענע מצרים (אפי' דער „כשר\" פון זיי) קומט דער עונש פון „הרוג\" — ומטעם הנ\"ל:\nוועגן די מצרים פון אַנדערע דורות, סיי כשרים סיי רשעים, רעדט רש\"י בכלל ניט.\nפרעגט אבער דער בן חמש: פונעם לשון „מכאן הי' ר\"ש אומר כו'\", איז דאָך משמע אז דער ענין איז אויך נוגע פאַר אַנדערש וואו, פאַר די שפעטערדיקע דורות — למאי נפקא מינה פאַר די אַנדערע דורות דאָס וואָס דער „כשר שבמצרים (אין יענעם דור איז) הרוג\"?\nדערפאַר ברענגט רש\"י דעם המשך פון ר\"ש'ס מאמר „טוב שבנחשים רצוץ את מוחו\", וואָס דערמיט דייטעט ער אָן אַז די נפק\"מ לדורות איז ניט דער ענין פון „כשר שבמצרים הרוג\" גופא, נאָר אויף וויפל אָט דער ענין לערנט אונז בנוגע דעם כלל „טוב שבנחשים רצוץ את מוחו\".\nועוד להוסיף: דערפון („מכאן\") ווייס מען אויך אז אויב עס וועט זיין איינער וואָס זיין באציאונג לדעה צו אידן וועט זיין אזוא וואָס מ'וועט עס קענען אנרופן „נחש\", ער איז מוחזק אין דעם — ע\"ד ווי מען געפינט למעליותא אז שמשון ווערט אנגערופן נחש55 — גייט אויף דעם דער כלל: טוב שבנחשים כו'56.\nולהעיר אז אין רש\"י'ס (און זיינע תלמידים'ס) צייטען — איז געווען אַסך\nוואָס זיינען געווען צו אידן בדוגמת „נחש\" — ווי מ'זעט עס אויך אין די קינות געשריבן פון רש\"י ותלמידיו.\nיב. דערמיט איז אויך פאַרשטאַנדיק דער אויפטו אין „טוב שבנחשים רצוץ את מוחו\" (כאַטש ס'איז אַ מקרא מפורש „הוא ישופך ראש\"): פונעם פסוק „הוא ישופך ראש ואתה תשופנו עקב\" וויים מען נאָר אז „ישופך ראש\" איז פאַר־בונדן און איז אַ באַוואַרעניש צו „אתה תשופנו עקב\" — צעשמעטערן דעם „ראש\" פון נחש דאָן ווען ער איז במצב פון „ואתה תשופנו עקב\"57:\nאויף דעם איז ר' שמעון מחדש: פונקט ווי מ'געפינט אז אפילו די כשרים שבמצרים איז הרוג צוליב זייער גיפ־טיקער שנאה צו אידן [און ניט צוליב זייער מלחמה־אנפאל אויף אידן, כנ\"ל] — אָט אזוי אויך ביי אַ נחש, וואָס דער אויבערשטער האָט גזור געווען „ואיבה אשית בינך ובין גו'\", דארף מען ניט ווארטן ביז דער נחש פאַלט אַן אויפן מענטשן (און דאמאלס „ישופך ראש\"), נאָר גלייך ווי מ'דערזעט אַ נחש — „רצוץ את מוחו\" — ווייל אויך אַ „טוב שבנחשים\" איז אזוי ווי אַ כשר שבמצרים פון דער פרשה (פון יענעם דור) — דיין סכנות'דיקער שונא („ואיבה אשית גו'\")58.\nאון בא ללמד ונמצא למד59: דורך דעם וואָס רש\"י ברענגט אויך דעם סיום פון דברי ר\"ש „טוב שבנחשים רצוץ את",[["55","55","ויחי מט, יז ובפרש\"י."],["56","56","ולהעיר ממצות מחיית עמלק (ס\"פ תצא). ובפרש\"י פרשתנו (בסופה): מלחמה ואיבה בעמלק עולמית כו'. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101103\" data-slug=\"likkutei-sichot\" data-id=\"1300101103\">לקו\"ש ח\"י ס\"ע 103</a> ואילך. וראה קה\"י (ערך המן): „המן משורש נחש יצא צפע .. עמלק .. ע\"כ המן ר\"ת הוא משורש נחש\", עיי\"ש."],["57","57","כמ\"ש בלבוש כאן: מיד שתראה שהיא מתרגזת כו'."],["58","58","ראה גם גו\"א כאן."],["59","59","ולהעיר מהגירסא (תנחומא באבער ופס\"ז לוארא ט, כ. ס' והזהיר שם. ועד\"ז הובאה גם במכילתא — מהדורת האראוויטץ־רבין) שמקדים „טוב שבנחשים כו'\" ל„כשר שבמצרים כו'\"."]]],[1300161173,"מוחו\", ווערט קלערער אויך דער אנהויב פון מאמר „כשר שבמצרים הרוג\" — אז דאָס מיינט נאָר דעם דור פון מצרים וואָס מיט זייער שנאה צו אידן זיינען זיי געווען אין דער דוגמא צו דער שנאה פון אַ נחש צום מענטשן („ואיבה אשית וגו'\").\nיג. וואָס איז טאקע די סיבה וואָס פונקט דעמאלט איז געווען אזא אויס־נאַם־דור? — אויף דעם איז רש\"י מדייק אראפצובראנגען דעם לשון (פון מכילתא) „טוב שבנחשים רצוץ את מוחו\" (ע\"ד ווי געזאָגט פריער, אז בא ללמד ונמצא למד):\nכשם ווי ביים נחש, איז די סיבה צו דער גזירה „ואיבה אשית גו'\" איז געווען דאָס וואָס „והנחש הי' ערום גו'\"60 — „מוחו\" — וואָס אלס תוצאה דערפון איז געקומען דער חטא עה\"ד וכו' — אזוי האָט אויך די שנאה פון די מצרים גע־האַט איר באזונדערע סיבה (און דערפאַר אזא אומפאַרגלייכבארע שנאה) אין דעם וואָס פרעה האָט געזאָגט „הבה נתחכמה לו גו'\"61 — אלע מצרים זאָלן זיין נתחכמה — ערום — וואָס דאָס האָט געפירט צום קושי השעבוד ועינוי פון בני ישראל.\nאון דאָס איז רש\"י מרמז אינעם ווארט „מוחו\" (און ניט „ראשו\"): דעם נחש דארף מען אומבראנגען צוליב זיין „מוח\" („והנחש הי' ערום\") וואָס האָט דערפירט צו „ואיבה אשית גו'\"; און אזוי\nאיז אויך דער „כשר שבמצרים הרוג\" געקומען צוליב זייער התחכמות, דער „הבה נתחכמה לו\", וואָס האָט דער־פירט צום קושי השעבוד ועינוי מצרים.\nיד. עס שטעלט זיך אבער אַ שאלה אויפן כללות הביאור: פון וואנעט איז די ראי' אז דאָס וואָס מ'האָט געהרג'ט אויך דעם „כשר שבמצרים\" איז געווען צוליב זייער יעדערענס שנאה און רשעות, אפשר איז דאָס געווען ווי אַ גזירה61* פון אויבערשטן אַן אַ טעם גלוי?\nדערפאַר ברענגט רש\"י אראפ דעם נאָמען פון בעל המימרא — ר' שמעון — ווייל ר' שמעון איז דער וואָס איז „דריש טעמא דקרא\"62, און ער גייט אויך דאָ לשיטתו.\nטו. לויט דעם איז מובן פארוואס אין די אלע וויכוחים בשייכות דעם מאמר פון ר\"ש (ווי דערמאנט) האָט מען זיך ניט געקענט באנוצן מיט דער סברה: דער ביאור האמור איז פשוט בהחלט, ער איז אבער מתאים נאָר אין פירוש רש\"י, ווייל — א) רש\"י איז אויסן צו מפרש זיין נאָר „פשוטו של מקרא\", נאָר דעם פסוק אויף וועלכן ער שטעלט זיך, און דערפאַר איז (אין פרש\"י) דער טייטש פון „כשר שבמצרים\" — די מצרים וועגן וועלכן עס רעדט זיך אין דעם פסוק; ב) אין פרש\"י קומט „טוב שבנחשים רצוץ את מוחו\" אלס המשך צו „כשר שבמצרים הרוג\" (וואָס דער־פאַר ווערט אויך „טוב שבנחשים כו'\"",[["60","60","בראשית ג, א."],["61","61","שמות א, י. ולהעיר מחה\"פ להרמב\"ם (פ\"ח): „פרעה וסיעתו מרו בבחירתם כו' ויאמר אל עמו גו' הבה נתחכמה לו וזאת הפעולה כו'\". ועד\"ז בהל' תשובה (פ\"ו ה\"ג): „לפי שחטא מעצמו תחלה כו' שנאמר הבה נתחכמה לו\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061063\" data-slug=\"likkutei-sichot\" data-id=\"1300061063\">לקו\"ש ח\"ו ע' 63</a> הערה 37. *61) להעיר מפרש\"י שמות (ב, יד): ישראל כו' ראויים לכך — שעפ\"ז, לכאורה, אין טעם להעניש המצריים."],["62","62","גיטין מט, ב. וש\"נ. וראה לקו\"ש חלק ח' ע' 179 (הערה 43) דלשיטת רש\"י פליגי ר\"ש ורבנן גם בדליכא נפקותא לדינא (אבל ע\"פ המבואר לקמן בפנים סט\"ז, יש גם נפקותא לדינא — גבי נחש)."]]],[1300161174,"אפגעלערנט „מכאן\"), ובמילא איז דאָס אויך אַ הוכחה און גילוי דעת אז „כשר שבמצרים הרוג\" מיינט בלויז די מצרים פון יענעם דור, כנ\"ל.\nאבער ווען ס'רעדט זיך וועגן ר' שמעון'ס מאמר ווי ער ווערט געבראכט אין מס' סופרים63 וכיו\"ב, וואו דער נוסח איז אין אַ סגנון סתמי: „תני רשב\"י הטוב שבעכו\"ם כו' הרוג הטוב שבנחשים רצוץ את מוחו הכשירה שבנשים בעלת כשפים\" — קען מען אזוי ניט מבאר זיין, ווייל עס רעדט זיך דאָ ניט וועגן אַ געוויסן דור אָדער סוג64 פון „גוים\" (אָדער מצרים<sup data-n=\"65\">65</sup>:\nאויב — ווײַבאַלד איז דאָ (במס' סופ־רים וכו') קומט צו אַ דריטער פאל „הכשירה שבנשים בעלת כשפים\", וואָס האָט קיין שייכות ניט צו „הטוב שבעכו\"ם כו'\"66 — דארף מען זאָגן, אַז יעדע איינע פון די דריי בבות איז אַ באַ־זונדער ענין פאַר זיך: „הכשירה שבנשים כו'\" — אַ הוראה אין שייכות מיט דעם טבע פון נשים; „הטוב שבנחשים כו'\" — וועגן דעם טבע פון נחשים,\n— און ביידע — ניט פארבונדן מיט אַ באשטימטן דור —\nאזוי איז אויך „הטוב שבעכו\"ם כו'\" — אַ הוראה (פאַר אלע צייטן) אין שייכות מיט דעם טבע פון אַ גוי.\nטז. ווי גערעדט כמה פעמים, קען מען פון רש\"י על התורה אויסלערנען בכו\"כ מקומות אויך ענינים וואָס זיינען נוגע דעם חלק ההלכה שבתורה:\nוועגן אַ „זאב וכו' והנחש\" זאָגט ר' אליעזר אין סנהדרין67: „כל הקודם להורגן זכה\", און מ'דארף ניט קיין ב\"ד של כ\"ג (כדעת הת\"ק); און אין דעם איז דא אַ פלוגתא68 צווישן ר' יוחנן און ריש לקיש: ר\"ל האלט אז דאָס איז געזאָגט געווארן נאָר ווען דער נחש האָט געטויט אַ מענטשן — וואָס דעמאלט קומט אים מיתה — דארף מען ניט אויף דעם קיין ב\"ד (ווי עס פאדערט זיך ביי אַ שור וכו'); אויב אבער דער נחש האָט קיין מענטשן ניט ממית געווען, טאר מען דעם נחש ניט הרג'נען; אבער ר' יוחנן האלט, אז „אע\"פ שלא המיתו\" זאָגט מען אויך „כל הקודם להורגן זכה\", ווייל „אין להם תרבות\".\nלויט ווי רש\"י טייטשט (אין פשש\"מ), אז „טוב שבנחשים כו'\" ווערט ארויס־גלערנט פון „כשר שבמצרים הרוג\" (און דברי רש\"י על התורה דארפן דאָך געטייטשט ווערן לכל לראש — כפשוטם), דארף אויסקומען:\nא) אז מ'דארף ניט האבן קיין משפט בב\"ד אויף צו הרג'נען דעם נחש, פונקט ווי מ'האט ניט גע'משפט יעדער מצרי באזונדער [וואס דעמאלט איז דאָך דער סדר „ושפטו העדה גו' והצילו העדה\"68* — מ'דארף זוכן אַ זכות — און דא זיינען געהרג'ט געווארן אויך די וואָס „ירא את דבר ה'\" ביז — „עד אחד\"69],",[["63","63","וכן בירושלמי קידושין שם."],["64","64","ואף שבמס' סופרים מוסיף „בשעת מלחמה\" — הרי בירושלמי קידושין שם (וכן במדרש הגדול כאן) — שגם שם כל הג' בבות — ליתא תיבות אלו."],["65","65","ובפרט שלרוב הגי' (ראה לעיל הערה 11) ל\"ג „שבמצרים\", כ\"א „שבגוים\" (סתם)."],["66","66","אבל להעיר ממדרש הגדול כאן: מכאן הי' רשב\"י אומר הכשר שבגוים כו' היפה שבנחשים כו' כשרה שבנשים כו'."],["67","67","בתחלתה (במשנה)."],["68","68","שם טו, ב. *68) נסמן לעיל הערה 25."],["69","69","דהיתכן דבחיפוש לא הי' נמצא זכות אפילו על אחד מהם?!"]]],[1300161175,"נאָר די גזירת כלי' האָט ארומגענומען אַלע מצרים ובבת (ובגדר ובמדה) אחת.\nב) אז מ'דארף הרג'נען אַ נחש אפי' „כשלא המיתו\" — ווארום אפי' אַ „טוב שבנחשים רצוץ את מוחו\" [ע\"ד ווי ב\"י ביי „כשר שבמצרים הרוג\", וואָס איז גע־וען (ניט צוליב זייער מלחמה מיט אידן, נאָר) מצד דעם עצם שנאה זייערע צו אידן].\nג) אז דאָס אלץ איז נאָר בשייכות צו אַ נחש70, וואָס אויף אים איז דאָ די גזירה „ואיבה אשית בינך ובין גו'\", משא\"כ ביי אנדערע בע\"ח קען מען זאָגן אז „יש להם תרבות\"71.\nיז. די הוראה פון דעם פאַר יעדערן אין זיין עבודה הפרטית:\nחז\"ל72 זאָגן אז נחש איז „דא יצה\"ר\". און אמאל איז דא אַ „פרומער\" יצה\"ר — אַ „טוב שבנחשים\": ער טענה'ט, אז ער ווייל מאכן „שלום\" מיטן יצר טוב, נאָר מ'זאל מאכן אַ פשרה — ער וועט לאזן דעם אידן לערנען תורה וכו' בזמן תורה וכו', און דער יצ\"ט זאל אים לאזן זיך נאכגעבן „אביסל\" אין זיינע תאוות וכו' בזמן האכילה וכו'.\nזאָגט דערויף ר\"ש „טוב שבנחשים רצוץ את מוחו\": מ'טאר ניט מאכן קיין „שלום\" מיטן יצה\"ר, ווייל ער איז אַ „נחש\" און האָט דיר פיינט ווי ער זאל\nזיך ניט פארשטעלן73; און דאָס וואָס ער איז גרייט דיר נאכצוגעבן אין איניקע זאכן, איז דאָס מתחבולות היצר, וואָס „היום אומר לו עשה כך ולמחר אומר לו כו' עבוד ע\"ז כו'\"74 — און דערפאַר איז די עצה דערצו: „רצוץ את מוחו\" — מ'דארף צעשמעטערן זיין „מוח\", די ערמומיות ותחבולות פון דעם יצה\"ר.\nנאָך אַן ענין אין דעם: ס'איז ידוע75 דער דיוק אין דעם וואָס ס'שטייט76 „יגיע כפך כי תאכל\" — אז די יגיעה פון אַ אידן אין עסקי הפרנסה דארף זיין בלויז מיט „כפך\", מיטן כח המעשה שלו, אבער זיין קאָפ („ראשך\" — שכל שבמוח) דארף אלעמאל זיין פול מיט תורה וכו'.\nאון דאָס מיינט „רצוץ את מוחו\": מ'דארף צעבראכן דעם מוח פונעם יצה\"ר, כדי דער מוח זאל זיין אינגאנצן איבערגעגעבן צו תורה וקדושה.\nאון דורך דעם וואָס אידן זיינען מקיים הוראת רז\"ל „טוב שבנחשים רצוץ את מוחו\" אין משך זמן הגלות, איז מען זוכה צו דעם קיום היעוד פון „גם אויביו ישלים אתו\"77, און ווי חז\"ל78 טייטשן „זה הנחש\" — אז אויך דער „נחש\" וועט נתהפך ווערן, ביז אז „ישלים אתו\".\n(משיחות ש\"פ בשלח, פורים, וש\"פ תשא תשכ\"ט)",[["70","70","וראה ב\"ק (טו, ב): והנחש מועד לעולם. וראה פרש\"י ותוס' שבהערה הבאה."],["71","71","וראה דעת רע\"ק בסנה' שם, ד(רק) בנחש ס\"ל כר\"א. ומזה שהביא רש\"י שם (ד\"ה איכא) מב\"ק (שם) ד„נחש מועד לעולם\", משמע קצת דמפרש דאתי כר\"י דאין להם תרבות ואין להם בעלים — אבל ראה תוס' ב\"ק (טו, ב — ד\"ה ר\"א), וסנה' שם (ד\"ה ור\"י). ואכ\"מ."],["72","72","זח\"א לה, ב."],["73","73","ראה ב\"ר רפנ\"ד. מדרש תהלים מזמור לד."],["74","74","שבת קה, ב."],["75","75","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380483\" data-slug=\"likkutei-torah\" data-id=\"4001380483\">לקו\"ת שלח מב, ד</a>. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011062\" data-slug=\"likkutei-sichot\" data-id=\"1300011062\">לקו\"ש ח\"א ע' 62</a>. ועוד."],["76","76","תהלים קכח, ב."],["77","77","משלי טז, ז."],["78","78","ירושלמי תרומות פ\"א ה\"ג. ב\"ר שם. וראה אוה\"ת בראשית מז, סע\"ב ואילך."]]],[1300161176,"<h3>בשלח ב</h3>\nא. אין פירוש רש״י אין דער היינטיקער סדרה געפינט מען א דבר פלא: רש״י שטעלט זיך אפ אויפן זעלבן ענין צוויי מאל, חזר׳ט איבער נאכאמאל א טייל פון דעם פריערדיקן פירוש מיט אלע פרטים — און אין צוגאב צו דעם — אין צוויי פסוקים וועלכע שטייען גלייך איינער נאכן צווייטן!\nאין ענטפער אויף די תלונות פון אידן (נאכדעם ווי „כלה הלחם״<sup data-n=\"1\">1</sup> — „מי יתן מותנו גו׳ בשבתנו על סיר הבשר באכלנו לחם לשובע גו׳״2 — זאגט דער פסוק3: ויאמר משה ואהרן אל כל בנ״י ערב וידעתם כי ה׳ הוציא אתכם מארץ מצרים. ובקר וראיתם את כבוד ה׳ בשמעו את תלונותיכם על ה׳ גו׳.\nאיז רש״י מסביר4: „..כך אמר להם, ערב וידעתם כי היכולת בידו ליתן תאותכם ובשר יתן אך לא בפנים מאירות יתננה לכם כי שלא כהוגן שאלתם אותו ומכרס מלאה, והלחם ששאלתם לצורך בירידתו לבקר תראו את כבוד אור פניו שיורידהו לכם דרך חיבה בבקר שיש שהות5 להכינו וטל מלמעלה וטל מלמטה כמונח בקופסא6״.\nאין דעם פסוק גלייך נאכדעם שטייט: ויאמר משה בתת ה׳ לכם בערב בשר לאכול ולחם בבקר לשבוע בשמוע ה׳ את תלונותיכם אשר אתם מלינים עליו גו׳.\nפרעגט רש״י (נאכן מפרש זיין „בשר לאכול, ולא לשובע למדה תורה דרך ארץ שאין אוכלין בשר לשובע״<sup data-n=\"7\">7</sup>: „ומה ראה להוריד לחם בבקר ובשר בערב (און פארענטפערט) לפי שהלחם שאלו",[["1","1","לשון רש״י פרשתנו טז, ב."],["2","2","שם, ג."],["3","3","שם, ו־ז."],["4","4","ע״פ מכילתא עה״פ (וראה ג״כ שם פסוק ח, יב, יג). וראה יומא עה, סע״א ואילך וברש״י שם."],["5","5","בכמה דפוסים: שעות [ובדפוס א׳ ליתא התיבות „בבקר שיש שהות להכינו״]. אבל בדפוס ב׳, רוב כת״י וכמה דפוסים לפנינו הוא כבפנים. וכן נעתק ברמב״ן פסוק ו׳."],["6","6","בכמה כת״י רש״י: בחפיסה. וראה רש״י לקמן פסוק יג־יד."],["7","7","הטעם שרש״י מקשה „ומה ראה כו׳״ לאחרי ובהמשך ל„למדה תורה ד״א כו׳״ — ראה לקמן הערה 36 (וראה גו״א שהובא לקמן הערה 9)*. ואין להקשות: מנ״ל לרש״י דזה שניתן בשר רק „לאכול״ (ולא לשובע) הוא משום ד״א, דילמא זהו מפני ששאלו בשר שלא כהוגן ולכן ניתן להם רק מעט בשר**? כי מכיון ש„ותעל השליו ותכס את המחנה״ (לקמן פסוק יג), מובן שהנתינה היתה בריבוי מופלג (וראה אברבנאל שם), ועכצ״ל דזה שנאמר „בשר לאכול ולחם גו׳ לשבוע״ הוא רק ללימוד — „למדה תורה דרך ארץ שאין אוכלין בשר לשובע״. *) בדברי דוד מתרץ, כי בלא הקדמה זו (שאין אוכלין בשר לשובע) הו״א שכ״ה דרך העולם, שבבקר אוכלים לחם לשובע ובערב אוכלים בשר לשובע (וראה יומא שם), ולכן הוריד הלחם בבקר ובשר בערב; אבל מאחר שאין אוכלין בשר לשובע, עכצ״ל ש(גם) בערב השביעו עצמם עם לחם, וא״כ קשה „מה ראה כו׳״. אבל פירושו אינו מובן. כי מכיון שעיקר זמן אכילת לחם הוא בבקר, ואכילת בשר הוא בערב (אלא שמוסיפים גם לחם כדי לשבוע) — שוב אין מקום לשאול „ומה ראה להוריד לחם בבקר ובשר בערב״. **) כפי׳ החדא״ג יומא שם. — בלבוש כאן משמע, דמה שניתן להם בשר שלא בפנים מאירות היינו שהי׳ בצמצום. אבל צע״ג, שהרי מפורש ברש״י שמה שהבשר הי׳ רק לאכול (ולא לשובע) הוא משום דרך ארץ (ולא עונש)."]]],[1300161177,"כהוגן .. אבל בשר שאלו שלא כהוגן .. לפיכך נתן להם בשעת טורח שלא כהוגן״.\nאיז תמוה: פארוואס חזר׳ט עס רש״י איבער א צווייטן מאל8?\nב. לכאורה וואלט מען געקענט זאגן, אז די צוויי פירושי רש״י ריידן וועגן באזונדערע ענינים9:\nדעם ערשטן מאל — קומט רש״י פארענטפערן פארוואס ביי נתינת לחם (בקר) שטייט „וראיתם גו׳״ און ביי בשר (ערב) שטייט „וידעתם גו׳״ — און איז מסביר דעם חילוק אין דעם אופן הנתינה: דער בשר איז געגעבן געווארן „לא בפנים מאירות״ (ס׳איז דערביי ניטא ראיית „כבוד ה׳״), און דער לחם איז געגעבן געווארן אין אן אופן אז „בירידתו .. תראו את כבוד אור פניו .. דרך חיבה כו׳״;\nדעם צווייטן מאל — קומט ער מסביר זיין דעם טעם החילוק אין זמן הנתינה10 [„מה ראה להוריד לחם בבקר ובשר בערב״] — אז דער לחם (וואס „שאלו כהוגן״) וועט זיין בבקר דערפאר וואס דאס איז א זמן „הגון״, און דער בשר (וואס „שאלו שלא כהוגן״) וועט זיין בערב — „בשעת טורח שלא כהוגן״.\nאבער דאס איז ניט מספיק. ווייל\n[נוסף אויפן עיקר, אז דאס פארענטפערט ניט פארוואס רש״י דארף איבערחזר׳ן די פרטים וואס ער האט שוין געזאגט אין ערשטן פירוש (אז די שאלת לחם איז געווען כהוגן און די שאלת בשר שלא כהוגן וכו׳) — איז]\nפון דעם וואס רש״י זאגט (גלייך אין ערשטן פירוש) אז „והלחם ששאלתם לצורך .. (ש)יורידהו לכם דרך חיבה בבקר שיש שהות להכינו11 כו׳״, איז מוכח, אז שוין אין ערשטן פירוש איז דא א טעם פארוואס „הוריד לחם בבקר (ובשר בערב)״; און [ניט נאר ווייל „ערב״ איז מרמז אויף „פנים חשיכות״ („לא בפנים מאירות״) און „בקר״ — אויף „פנים מאירות״12 — נאר] טאקע צוליבן זעלבן ענין וואס רש״י זאגט אין צווייטן פירוש, אז „בקר״ איז א זמן וואס „יש שהות להכינו״ (און פון דעם איז שוין במילא פארשטאנדיק, אז דער געבן בשר איז בערב ווייל (אלס תוצאה פון „לא בפנים מאירות יתננה לכם״, איז דער זמן הנתינה אזא וואס) דעמאלט איז ניטא קיין „שהות להכינו״) —\nאון וויבאלד אז אויך דער חילוק צווישן בשר ולחם (צי ס׳איז געגעבן געווארן בשעת טורח אדער ניט) איז שוין נכלל אין ערשטן פירוש רש״י, איז הדרא קושיא לדוכתא: פארוואס דארף רש״י דאס איבער/חזר׳ן? און נאך מער: ער הויבט אן דעם צווייטן פירוש בלשון שאלה „ומה ראה להוריד לחם בבקר ובשר בערב״: אפילו ווען ס׳איז נויטיק",[["8","8","ולהעיר, שגם במכילתא נשנה ענין זה כמ״פ (כנ״ל הערה 4)."],["9","9","דברי דוד. וראה עד״ז בלבוש. ומה שתירץ בגו״א [דהוקשה לי׳ לרש״י „מנ״ל דלמדך ד״א שמא בשביל שלא הי׳ להם פנאי בערב לטרוח הרבה בכו׳, ולכן מבאר רש״י שנתינת הבשר בערב הי׳ עונש, ע״ש] — לא זכיתי להבין איך תתורץ האריכות שברש״י, ובפרט השאלה „ומה ראה כו׳״ (נוסף על מה שצ״ע בגוף פירושו. ואכ״מ)."],["10","10","שלכן לא הובא כאן „טל מלמעלה כו׳״ שאינו נוגע כ״כ לזמן הנתינה."],["11","11","מלשון הלבוש (שהביא רק זה שהמן הי׳ מונח בקופסא) משמע קצת, שלא גריס תיבות אלו ברש״י (כבדפוס א׳, וכנ״ל הערה 5). אבל נמצא הוא בשאר כל הדפוסים וכת״י."],["12","12","כפשטות לשון המכילתא. וכמפורש זה ברמב״ן כאן (פסוק ו׳)."]]],[1300161178,"צו איבער/חזר׳ן דעם פירוש נאכאמאל — איז אבער ניט מתאים צו פרעגן „ומה ראה כו׳״, נאכדעם ווי ער האט דאס ערשט מסביר געווען אין דעם פריערדיקן פסוק?\nג. אין די צוויי פירושי רש״י, זיינען אויך דא כו״כ שינויי ודיוקי לשונות, איז די שאלה כללית: וואס איז דער טעם פון די שינויים ודיוקים? און נאכמער: בהשקפה ראשונה איז די סברא מחייב, אז בכמה מהם האט בדוקא געדארפט שטיין בהיפך:\nא) וויבאלד רש״י טייטשט אויס אין ערשטן דיבור אז די „פנים מאירות״ ביים געבן דעם לחם איז אין דעם וואס דאס וועט געגעבן ווערן „בבקר שיש שהות להכינו״ — האט ער דארט געדארפט זאגן בנוגע דעם בשר, אז דער „לא בפנים מאירות״ איז אין דעם וואס עס וועט זיין נתינתו בערב „בשעת טורח״ — פארוואס זאגט רש״י דעם ענין ערשט אין צווייטן דיבור?\nב) בפשטות איז דער סדר, אז פריער דערציילט מען א זאך מיט אלע נייטיגע פרטים, און ביים איבער/חזר׳ן באנוגנט מען זיך מיט א קיצור פון דעם; בנדו״ד אבער, בנוגע דער הסברה פון „לחם שאלו כהוגן״ און „בשר שאלו שלא כהוגן״, זעט מען אין די פירושי רש״י א פארקערטן סדר:\nאין ערשטן דיבור זאגט ער בקיצור, אז „והלחם ששאלתם לצורך .. ובשר שלא כהוגן שאלתם אותו ומכרס מלאה״; און אין צווייטן דיבור איז רש״י מאריך ומסביר: שהלחם שאלו כהוגן שאי אפשר לו לאדם בלא לחם13 .. בשר שאלו שלא כהוגן שהרבה בהמות היו להם ועוד שהי׳ אפשר להם בלא בשר.\nג) אין ערשטן דיבור איז רש״י מסביר פריער וועגן בשר און דערנאך וועגן לחם — מתאים צום סדר אין פסוק „ערב וידעתם גו׳ ובקר וראיתם גו׳״ — משא״כ אין צווייטן דיבור איז רש״י מהפך דעם סדר „ומה ראה להוריד לחם בבקר (און דערנאך) ובשר בערב״ [און אזוי אויך אין אויספיר „לפי שהלחם שאלו כהוגן כו׳ (און דערנאך) אבל בשר כו׳״]14; וביותר קשה: דאס איז היפך פון דעם סדר אין דעם פסוק גופא: בתת ה׳ לכם בערב בשר לאכול (און דערנאך) ולחם בבקר לשבוע גו׳.\nד. נוסף אויף דעם וואס אין צווייטן דיבור איז רש״י מער מאריך ווי אין ערשטן, זיינען אויך דא שוין (בנוגע דער הסברה בענין הבשר) שינויים אין לשון (ומשמעות):\nא) פון לשון רש״י (אין ערשטן דיבור) „כי שלא כהוגן שאלתם אותו ומכרס מלאה״ — איז מוכח15, אז „ומכרס מלאה״ איז ניט קיין נתינת טעם פארוואס זייער שאלה איז „שלא כהוגן״, נאר א טעם נוסף פארוואס די שאלת בשר האט ניט געטויגט; און ווי מפרשים16 זיינען מסביר, אז מיט „שלא כהוגן״ מיינט רש״י אז די שאלה איז געווען „שלא לצורך״, ווייל „הי׳ אפשר להם בלא בשר״ (ווי רש״י זאגט אין צווייטן דיבור), „ומכרס מלאה״ מיינט (ווי רש״י זאגט אין צווייטן דיבור) „שהרבה בהמות היו להם״17 —",[["13","13","מכילתא שם, יב."],["14","14","כ״ה גם ביומא שם — לפי גירסת רש״י (וכ״ה גירסת הע״י שם. וראה עיון יעקב לע״י שם). אבל פשוט שאא״פ לומר שהסדר ברש״י עה״ת הוא לא כפש״מ, כ״א מפני שכ״ה סדרם בגמרא."],["15","15","משא״כ ברש״י יומא שם: בשר שאלו שלא כהוגן, מתוך כרס מלאה כו׳. ובדפוס א׳ דרש״י: שהרי ממלא מעים שאלתם אותו שלא כהוגן."],["16","16","שפ״ח."],["17","17","וכמפורש ברש״י יומא שם."]]],[1300161179,"דארף מען פארשטיין: אין ערשטן דיבור פון רש״י איז „שלא כהוגן״ (וואס מיינט „הי׳ אפשר להם בלא בשר״ כנ״ל) פריער פון „ומכרס מלאה״, און אין צווייטן דיבור איז ער מהפך דעם סדר — פריער „שהרבה בהמות היו להם״ און דערנאך „שהי׳ אפשר להם בלא בשר״?\nב) אין ערשטן דיבור זאגט רש״י „ומכרס מלאה״ — מיט א ואי״ו המוסיף (אז דאס איז אויך אן עיקר טעם), און אין צווייטן דיבור זאגט ער „שהרבה בהמות היו להם ועוד שהי׳ אפשר להם כו׳״ — וואס איז מדגיש אז דאס קומט ווי א טפל צום עיקר טעם („שהרבה בהמות היו להם״).\nג) אין ערשטן דיבור איז דער לשון „ומכרס מלאה״ סתם — ניט דערמאנענדיק מיט וואס ס׳איז „מלאה״18 — משא״כ אין צווייטן דיבור איז דאס מפורט „שהרבה בהמות היו להם״.\nה. וועט מען דאס פארשטיין בהקדים א תמי׳ כללית אין די עטלעכע פסוקים — פריער שטייט אין פסוק3 „ויאמר משה ואהרן .. ערב וידעתם גו׳ ובקר וראיתם גו׳״ און גלייך נאכדעם שטייט „ויאמר משה בתת ה׳ לכם בערב בשר לאכול ולחם בבקר לשבוע גו׳״:\nפארוואס איז דער ענין פאנאנדערגעטיילט אין צוויי באזונדערע אמירות — פריער אן אנזאג סתם „ערב וידעתם גו׳ ובקר וראיתם גו׳״ (ניט אויסטייטשנדיק דורך וואס וועט זיין דער „וידעתם גו׳ וראיתם גו׳״), און דערנאך אין א באזונדערער אמירה — באופן מפורט „בתת ה׳ לכם בערב בשר לאכול ולחם בבקר לשבוע גו׳״19 —\nאון ניט ביידע צוזאמען אין איין דיבור: „בתת ה׳ לכם בערב בשר לאכול וידעתם גו׳ ולחם בבקר לשבוע וראיתם גו׳״?\nאע״פ אז מ׳געפינט בכמה מקומות אז פריער זאגט מען אן ענין בכללות און דערנאך איז מען מפרט לפרטיו — איז אבער דא שווער אזוי צו לערנען, ווייל\n[נוסף אויף דעם, וואס בנדו״ד (א) וואלט מען פארשפארט די גאנצע צווייטע אמירה דורך צוגעבן בלויז עטלעכע ווערטער אין ערשטער אמירה. (ב) דאס פארענטפערט ניט פארוואס עס וערט איבער׳געחזר׳ט דער צווייטער טייל פסוק („בשמוע ה׳ את תלונותיכם גו׳ ונחנו מה גו׳״) וואס שטייט שוין בפירוש אין פריערדיקן פסוק („בשמעו את תלונותיכם גו׳ ונחנו מה גו׳״) — איז]\nפון דעם וואס אין ערשטער אמירה שטייט „ויאמר משה ואהרן״ און אין צווייטער אמירה „ויאמר משה״ (אליין) איז מוכח, אז דאס זיינען צוויי באזונדערע ענינים: די ערשטע אמירה איז אן ענין וואס האט שייכות צו משה און צו אהרן, און די צווייטע — נאר צו משה׳ן20, כדלקמן.\nו. איז דער ביאור בכל זה:\nאין דער כללות׳דיקער התלוננות פון די אידן (צוליב דעם וואס „כלה הלחם״) זיינען דא צוויי ענינים אויף וועלכע דער אויבערשטער האט געענטפערט:",[["18","18","ולהעיר, שבמכילתא (שם, יב) הלשון „ממלא מעיים״ הוא הניגוד ל„אי אפשר לבו״ד בלא לחם״ (ומשמע, שהכוונה בזה שאפשר לאדם בלחם בלי בשר)."],["19","19","ראה ראב״ע, רמב״ן, אברבנאל, אוה״ח ועוד."],["20","20","ראה גם אלשיך כאן."]]],[1300161180,"א) וועגן באזארגן די צרכים (גשמים) פון אידן — דורך קובע זיין וואס ס׳איז נויטיק פאר זיי און וואס ס׳איז ניט נויטיק [וואס דאס איז דער חילוק צווישן לחם ובשר, כדלקמן סעיף ט׳];\nב) וועגן באווארענען און מתקן זיין די הנהגה פון אידן בנידון זה — היות אז די תלונות פון אידן האבן באוויזן אז זיי זיינען אין א מצב רוחני וואס פאדערט תיקון21.\nאון דאס איז דער חילוק כללי צווישן די צוויי אמירות (ופירושי רש״י):\nאין ערשטער אמירה האבן משה ואהרן איבערגעגעבן אידן ווי דער אויבערשטער וועט זיך פירן מיט זיי אויף צו פארבעסערן זייער הנהגה, וואס דער ענין איז שייך צו משה און צו אהרן, היות אז צו זיי ביידע האט דער אויבערשטער געזאגט הוציאו את בנ״י מארץ מצרים על צבאותם22 און זיי ביידע האבן געהאט דעם תפקיד צו מדריך זיין אידן בדרך הישר:\nאין צווייטער אמירה אבער רעדט זיך וועגן דעם ווי דער אויבערשטער וועט געבן אידן זייערע צרכים — „בערב בשר לאכול ולחם בבקר לשבוע״; און דער ענין איז שייך צו משה׳ן, ער איז דער רועה ישראל וואס באזארגט אידן מיט זייערע צרכים — „כאשר ישא האומן את היונק״23.\nאון דערפאר האט ניט קיין ארט, אז דער ענין פון „בתת ה׳ גו׳ בשר גו׳ ולחם גו׳״ זאל שטיין אין ערשטער אמירה, ווייל דארט וערט ניט גערעדט וועגן די צרכים וואס אידן וועלן באקומען, נאר אן ענין פון הוראה ומוסר וועגן דער הנהגה פון אידן.\nז. די תלונות פון אידן האבן באוויזן אויף א דבר והיפוכו:\nפון איין זייט, איז זייער בעטן לחם ובשר געווען אין אן אופן פון תלונה24, וואס דאס איז א באוויז אויף א מצב שלא כדבעי.\nלאידך אבער, איז מודגש אין תוכן התלונות — אין זייער מאנען ביים אויבערשטן זייערע צרכים — אז זיי גלויבן אז דער אויבערשטער קען זיי דאס געבן און אז ער איז דער זן ומפרנס לכל, ביי וועמען מ׳דארף דאס בעטן און מאנען25.\nאון בהתאם צו די צוויי ענינים (וואס די תלונות ברענגען ארויס) זיינען געקומען די צוויי אמירות, וואס זאגן אן",[["21","21","ולהעיר, שגם גבי ב׳ התלונות דבנ״י בנוגע למים שבפרשתנו — במרה (טו, כד ואילך) ורפידים (יז, א ואילך) — מצינו [לא רק שהקב״ה נתן להם מים — שהרי בקשה צודקת היא (ראה אוה״ח טו, כד. רש״י שם, כה), כ״א גם] ענין של מוסר כו׳ על אופן הבקשה (תלונה כו׳): לאחרי התלונה במרה — „שם שם לו חק ומשפט ושם נסהו״ (טו, כה), וכפי׳ הרשב״ם ש„התחיל להוכיחם שיקבלו עליהם את החוקים וכו׳ והוא יעשה צרכיהם״ (וראה רש״י שם ד״ה ושם נסהו ובמפרשים שם); והתלונה ברפידים גרמה ל„ויבא עמלק גו׳״ (שם, ח), וכפרש״י שם: סמך .. לומר תמיד אני ביניכם ומזומן לכל צרכיכם ואתם אומרים .. חייכם שהכלב בא ונושך אתכם ואתם צועקים כו׳. ועפ״ז נמצא, שהמוסר כו׳ על ג׳ התלונות (מרה, מדבר סין ורפידים) היו מן הקל אל הכבד: במרה — ע״י נתינת חוקים כו׳; בנדו״ד — ע״י אמירת דברי תוכחה („ערב וידעתם גו׳״) נגד תלונתם (כפרש״י עה״פ); ברפידים — נענשו כו׳ (כלב בא ונושך כו׳)."],["22","22","וארא ו, כו."],["23","23","לשון הכתוב — בהעלותך יא, יב."],["24","24","ראה רש״י לעיל טו, כד־כה. — ובפרט בנדו״ד שהי׳ באופן ד„תלינו״ (ראה רש״י טז, ז־ח)."],["25","25","ראה אברבנאל לעיל פסוק ג׳. מלבי״ם פסוק ד׳. — ולכן הטענה לבנ״י הוא רק על אופן השאלה (כפרש״י לעיל (טו, כה) גבי התלונות דמרה), ולא על עצם השאלה."]]],[1300161181,"צוויי אופני הנהגה פון אויבערשטן מיט אידן:\nאויף זייער תלונה וטענה „מי יתן מותנו גו׳ בארץ מצרים גו׳ כי הוצאתם אותנו אל המדבר גו׳״, איז געווען דער ענטפער אז „ערב וידעתם כי ה׳ הוציא אתכם מארץ מצרים״: דער אויבערשטער וועט (שולל זיין די תלונה הנ״ל און וועט) באווייזן „כי ה׳ הוציא אתכם מארמ״צ״26 (און אז ער פירט זיי אין מדבר);\nאון אלס ענטפער אויף זייער תלונה ותביעה, אז דער אויבערשטער דארף זיי זן ומפרנס זיין, וואס דאס דריקט אויס זייער אמונה אין אים — וועט זיין די הנהגה (מדה כנגד מדה) פון „וראיתם את כבוד ה׳״: דער אויבערשטער וועט זיי באווייזן „כבוד ה׳״.\n[דערמיט איז פארענטפערט וואס די ווערטער „בשמעו את תלונותיכם על ה׳ גו׳״ שטייען בהמשך צו „ובקר וראיתם את כבוד ה׳״ — דלכאורה איז דאס („בשמעו את תלונותיכם גו׳״) א טעם אויף להיפך27:]\nנאר ווייל מיט די ווערטער האבן משה ואהרן (בעיקר) געמיינט צו מדגיש זיין די צופרידנקייט פון אויבערשטן ביים „הערן״ אין זייערע תביעות („בשמעו את תלונותיכם (אשר<sup data-n=\"28\">28</sup> על ה׳״) זייער אמונה אז ער איז דער זן ומפרנס לכל וואס דארף זיי צושטעלן זייערע צרכים, און דערפאר — „וראיתם את כבוד ה׳״29].\nח. ע״פ כהנ״ל וועט וערן פארשטאנדיק דער חילוק צווישן די צוויי פירושי רש״י הנ״ל — בהתאם צום חילוק הנ״ל צווישן די צוויי אמירות:\nאין ערשטער אמירה איז רש״י אויסן צו מבאר זיין די שייכות פון „וידעתם גו׳ וראיתם גו׳״ [די צוויי אופני הנהגה פון אויבערשטן מיט אידן] צו די צוויי נתינות פון בשר און לחם [וואס דערפאר איז „ערב (דוקא) וידעתם גו׳״ — דורך נתינת הבשר, „ובקר (דוקא) וראיתם גו׳״ — דורך נתינת הלחם]:\nדי תלונות פון אידן („מי יתן מותנו גו׳״) — וואס האבן ארויסגערופן דעם ענטפער ועניו פון „וידעתם כי ה׳ הוציא אתכם מארמ״צ״ — האבן זיך אויסגעדריקט אין זייער בעטן בשר, וואס „שלא כהוגן שאלתם אותו כו׳״, און דעריבער איז די נתינה געווען אין אן אופן פון „לא בפנים מאירות״:\nאון זייער בקשת לחם וואס איז געווען „לצורך״, איז א תוצאה פון זייער אמונה (אז דער אויבערשטער איז מספיק זייערע צרכים)30, און דעריבער — „בירידתו לבקר תראו את כבוד אור פניו״.\n[און היות אז עס איז א חידוש צו זאגן אז דער מילוי פון בקשת לחם (נתינת המן) איז געווען „בפנים מאירות״ — ווארום כללות הבקשה פון די אידן (אויך אויף לחם) איז געווען אין אן אופן פון „וילונו גו׳״ — דעריבער איז רש״י מפרש ומסביר אין וואס עס האט זיך",[["26","26","כפרש״י עה״פ."],["27","27","בקושיית הרמב״ן פסוק ו׳."],["28","28","רש״י עה״פ. וראה מפרשי רש״י."],["29","29","ראה בארוכה מלבי״ם הנ״ל."],["30","30","ויומתק עפ״ז דיוק לשון רש״י „לצורך״ — ולא „כהוגן״ (כלשונו כאן בנוגע לבשר. והוא מיומא שם) או „בהלכה״ (מכילתא עה״פ). [ובא׳ מכת״י רש״י גם כאן הלשון „כהוגן״. וברמב״ן פסוק ו׳: לצורך כהוגן]."]]],[1300161182,"אנגעזען די חיבה פון אויבערשטן בירידת המן: (א) בבקר שיש שהות להכינו און (ב) טל מלמעלה וטל מלמטה כמונח בקופסא.\nמשא״כ בנוגע „בשר״ זאגט רש״י סתם „לא בפנים מאירות יתננה לכם״ — ניט אויסטייטשנדיק דערבי אזוי ווי דאס האט זיך אויסגעדריקט אין פועל ממש (ביי נתינת הבשר) — ווייל אין דעם פסוק איז ניט נוגע צו ריידן וועגן דעם אופן פון נתינת הבשר, נאר בלויז ארויסברענגען דעם פרט אז די נתינה איז געווען פארבונדן מיט ניט־צופרידנקייט31 („לא בפנים מאירות״)].\nמשא״כ אין פירוש רש״י אויפן פסוק „בתת ה׳ לכם גו׳״ — וואו עס רעדט זיך דער אויבערשטער וועט באזארגן די צרכים פון אידן — איז כוונתו צו מבאר זיין ווי דער חילוק צווישן נתינת לחם בבקר און בשר בערב איז נוגע אויך אין דעם ענין, אז לויט דער נויטיקייט פון זייערע בקשות, איז געווען דער חילוק אין דעם אופן ווי מ׳האט זיי ממלא געווען:\nדער לחם וואס „שאלו כהוגן״ האט דער אויבערשטער געגעבן בבקר (אין א באקוועמער צייט „שיש שהות להכינו״<sup data-n=\"32\">32</sup>, און דעם בשר וואס „שאלו שלא כהוגן״ — „נתן להם בשעת טורח״.\nט. עפ״ז וועט וערן פארשטאנדיק בפשטות די חילוקי לשונות אין רש״י:\nאין ערשטן דיבור איז רש״י סותם אז בשר „שלא כהוגן שאלתם אותו ומכרס מלאה .. והלחם (ש)שאלתם לצורך״, ווייל ער מיינט ניט צו מבאר זיין די טעמים פארוואס די בקשה איז געווען לצורך אדער ניט — דא איז נאר נוגע דער גדר הבקשה: די שאלת לחם איז געווען אן ענין רצוי (וויבאלד עס איז „לצורך״), און דערפאר האט עס געבראכט „וראיתם את כבוד ה׳״; און די שאלת בשר איז געווען (א) שלא כהוגן (מיט תלונות כו׳), און (ב) „מכרס מלאה״ — וואס בעטן בשר בשעת מ׳האט א „כרס מלאה״ ווייזט אויף א שפל המצב33 — און דעריבער האט דאס געבראכט צו „לא בפנים מאירות כו׳״.\nמשא״כ אין צווייטן דיבור איז רש״י מבאר דעם חילוק צווישן בשר ולחם בשייכות צו זייער נויטיקייט פאר אידן: די שאלת לחם איז געווען „כהוגן״ ווייל „א״א לו לאדם בלא לחם״ (דאס מוזן זיי האבן); און די שאלת בשר איז געווען „שלא כהוגן״, ווייל „הרבה בהמות היו להם״: ס׳איז ניטא קיין סיבה צו געבן בשר, א זאך וואס זיי האבן שוין;\nאון דערנאך איז רש״י מוסיף „ועוד שהי׳ אפשר להם בלא בשר״: אפילו ווען זיי וואלטן ניט געהאט קיין בהמות, איז אויך זייער שאלת בשר ניט אזוי „כהוגן״ ווי שאלת לחם34, ווייל בשר איז ניט אזא נויטיקייט וואס אן דעם קען מען ניט אויסקומען — „אפשר להם בלא בשר״.\nיו״ד. דער טעם אויף די צוויי סוגי נתינה — „בערב בשר״ (אין א „שעת",[["31","31","בסגנון אחר קצת: עצם הדבר שהבשר ניתן להודיע „כי ה׳ הוציא אתכם גו׳״ (כדי לשלול תלונתם כו׳) הו״ע של העדר שביעת רצון („לא בפנים מאירות״). ובפרט את״ל שזהו טעם נתינתו בערב (כנ״ל בפנים סעיף ב׳ והערה 12)."],["32","32","ואין רש״י צריך לכתבו בפירוש, כי סומך על פירושו בפסוק שלפנ״ז."],["33","33","ראה ברכות לב, א."],["34","34","אף שיש מקום לשאלת בשר (שלכן הוא רק ענין נוסף — „ועוד״. וברש״י יומא שם לא הובא ענין זה כלל). וראה רש״י יב, כ. רמב״ם הל׳ דיעות פ״ה ה״י."]]],[1300161183,"טורח״) „ולחם בבקר״ — איז מודגש אין המשך הפסוק „בשמוע ה׳ את תלונותיכם אשר אתם מלינים עליו״:\n„בשמוע ה׳ את תלונותיכם״ — אז די נקודת הבקשה פון אידן איז אזא וואס דער אויבערשטער הערט און נעמט אן (כנ״ל ס״ז) — איז א נתינת טעם אויף „בתת ה׳ גו׳ ולחם בבקר״: און „אשר אתם מלינים עליו — את האחרים״35, וואס ברענגט ארויס דער הנהגה לא טובה פון אידן — איז דער טעם אויף „בערב בשר״, אין א שעת טורח36.\nועפ״ז קען מען זאגן, אז דערפאר איז רש״י מהפך דעם סדר אין צווייטן דיבור („מה ראה להוריד לחם בבקר (און דערנאך) ובשר בערב״) — ווייל דאס איז בהתאם צום סדר בפסוק אין טעם החילוק: פריער „בשמוע ה׳ גו׳״ — דער טעם אויף „לחם בבקר״: און דערנאך „אשר אתם מלינים עליו״ — דער טעם אויף „בשר בערב״.\nאון דערמיט (מיטן היפך הסדר) מיינט רש״י צו קלאר מאכן, אז „ומה ראה כו׳״ איז ניט א שאלה וואס וערט ביי רש״י [וואורום רש״י האט שוין פארענטפערט די שאלה אין פריערדיקן פסוק (כנ״ל ס״ב)], נאר כאילו ווי די שאלה איז א טייל פון פסוק:\nנאכן זאגן „בתת ה׳ גו׳ בערב בשר גו׳ ולחם בבקר גו׳״, וערט שווער „ומה ראה להוריד לחם בבקר ובשר בערב״?\nאון די קושיא (בעיקרה) איז: וויבאלד אז דער אויבערשטער האט נאכגעגעבן די תלונות בנ״י ווען „כלה הלחם״, און דערפאר געזאגט הנני ממטיר לכם לחם גו׳*36 (ניט דערמאנענדיק בכלל דאס מאלס בשר) האט ער עס געדארפט גלייך טאן, ניט וואַרטנדיק ביז אינדערפרי „ומה ראה להוריד להם לחם בבוקר (און וויבאלד אז עס איז געווען איין סיבה — די תלונות — פארוואס איז דער צווייטער מסובב) ובשר בערב״ (ניט צוזאמען)?\nאיז דער פסוק מבאר: „בשמוע ה׳ את תלונותיכם״ — דאס מיינט (ווי רש״י איז מסביר) אז די שאלת לחם איז געווען כהוגן און איז דעריבער געגעבן געווארן בבקר: „אשר אתם מלינים עליו״ — די שאלת בשר איז געווען שלא כהוגן, און איז דעריבער געגעבן געווארן בערב „בשעת טורח״.\nיא. פון יינה של תורה וואס איז מרומז אין דעם פירוש רש״י:\nדער חילוק צווישן לחם און בשר (שליו) בפנימיות איז: לחם איז נגלה",[["35","35","רש״י עה״פ. וראה רש״י לעיל פסוק ז׳ (ד״ה כי תלינו עלינו). ועפ״י המבואר בפנים יומתק השינוי בב׳ הכתובים: כאן (פסוק ח׳) נאמר ב׳ ענינים (בנוגע תלונתם על ה׳): (א) בשמוע ה׳ את תלונותיכם, (ב) אשר אתם מלינים עליו — כי בא בהמשך לב׳ הענינים שבכתוב: (א) בערב בשר לאכול (ב) ולחם בבקר לשבוע; משא״כ לעיל (פסוק ז׳) נאמר רק „בשמעו את תלונותיכם על ה׳״ [ו„כי תלינו״ (ראה רש״י שם) הוא „עלינו״ (משה ואהרן), בהמשך ל„ונחנו מה״] — כי בפסוק זה נאמר לפנ״ז רק (ענין אחד) „ובקר וראיתם גו׳״ (וכנ״ל בפנים סעיף ז׳)."],["36","36","ועפ״ז מתורץ בפשטות זה שקושיית רש״י „ומה ראה כו׳״ היא בהמשך ל„למדה תורה ד״א כו׳״: הי׳ אפ״ל דב׳ הענינים שבכתוב [(א) בשמוע גו׳ (ב) אשר אתם מלינים עליו] הם טעם על החילוק בנתינת בשר ולחם — הלחם לשבוע (כי שאלו כהוגן) ובשר רק לאכול (כי שאלו שלא כהוגן), וכנ״ל הערה 7: אבל מאחר שחילוק זה הוא רק משום ד״א, עכצ״ל שב׳ ענינים הנ״ל הם טעם על חילוק הב׳ שבין בשר ולחם (זמן הנתינה — ערב או בקר), וא״כ קשה „ומה ראה כו׳״. *36) טז, ד."]]],[1300161184,"דתורה37, און שליו — וואס איז „(מין עוף) ושמן מאד״38, בחי׳ שמן39 — „שמן״ שבתורה, פנימיות התורה, און אין דעם גופא — רזי דרזין דאורייתא40. און דער ענין פון „שמן״ ווי ער איז אין בחי׳ „בשר״ מיינט, אז די רזי דרזין דאורייתא קומען אראפ אין (א אופן דאכילה—) הבנה והשגה41 (וואס דאן האט עס א טעם און געשמאק).\nאון אע״פ אז אויך דער מן, זייענדיק לחם מן השמים, איז מרמז אויף פנימיות התורה42 — איז דא א חילוק צווישן דעם מן און שליו:\nדער מן וואס איז אראפגעקומען אלס לחם (וואס ווייזט, כנ״ל, אויף נגלה דתורה) איז דאס די דרגא אין פנימיות התורה וואס איז מלובש אין נגלה דתורה43: משא״כ דער שליו, וואס (אויך) קומענדיק למטה איז ער געווען בגילוי אין א ציור פון „שמן״ (שמן מאד), איז עס פנימיות התורה מצד עצמה.\nדערמיט וועט מען פארשטיין די חילוקים צווישן מן און שליו:\nא) אע״פ אז דער מן איז אויך בהמשכתו למטה פארבליבן א מהות, וואס איז ניט אזוי געבונדן מיט גדר מקום וגבול (און דערפאר „לא44 העדיף המרבה והממעיט לא החסיר״)45, איז ער אבער געגעבן געווארן מיט א מידה — „עומר לגולגולת גו׳״46, דאקעגן ביים שליו געפינט מען ניט אז עס זאל זיין א מידה וויפל יעדער האט געקענט נעמען47 —\nוויבאלד אז נגלה דתורה „היא בבחי׳ מדידה והגבלה״48, איז מובן, אז אויך די דרגא פון פנימיות התורה וואס איז מלובש אין נגלה האט זיך אין א מידה וגבול; משא״כ בפנימיות התורה בפ״ע איז דא דער „בלי גבול״ שבתורה48.\nב) אע״פ אז אויך השפעת המן האט זיך אויפגעטאן ביום השבת49 (דערפאר וואס שבת האט א שייכות צו פנימיות התורה<sup data-n=\"50\">50</sup> — איז עס נאר וואס זיין המשכה למעלה איז געווען בשבת,",[["37","37","אמרי בינה שער הק״ש פנ״ג. וראה לקמן הערה 43."],["38","38","לשון רש״י לקמן פסוק יג. וראה יומא עה, ב."],["39","39","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380438\" data-slug=\"likkutei-torah\" data-id=\"4001380438\">לקו״ת בהעלותך לב, א</a>. שם, ב ואילך. ע״ש."],["40","40","ראה בארוכה אמרי בינה שם (פנ״ד ואילך) בהחילוק דיין ושמן שבתורה. וי״ל ד„שמן מאד״ היינו שב„שמן״ גופא הוא דרגא הכי נעלית שבו."],["41","41","עדמ״ש בלקו״ת שם, שהשליו הוא החיבור דביטול (דחכמה) ויש (דבשר), ע״ש."],["42","42","מאמרי אדה״ז — הנחות הר״פ ע׳ עז-עת. סה״מ תקס״ח ע׳ מ. ועוד. וב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550150\" data-slug=\"torat-chaim\" data-id=\"2300550150\">תו״ח פרשתנו (שה, ב</a>): וע״כ גם בירידתו למטה הי׳ טעמו כטעם לשד השמן וכצפיחית בדבש שזהו .. פנימי׳ התורה ברזין וסודות הטעמים כו׳, ע״ש. וראה זח״ב קפג, ב."],["43","43","ע״ד המבואר בכ״מ (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380772\" data-slug=\"likkutei-torah\" data-id=\"4001380772\">לקו״ת עקב יד, ג</a>־<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550306\" data-slug=\"torat-chaim\" data-id=\"2300550306\">ד. סדור קס, א</a>. קי, ג. תו״ח שם שיב, א. שיג, ב) שירידת המן (למטה) היא בכדי ליתן כח בעבודת הבירורים (דלחם מן הארץ). [ולהעיר, דמה שהתורה נק׳ „לחם״ (שגם המן נק׳ לחם כנ״ל) הוא מצד זה שנותנת כח ועוז להתגבר על הגוף ונה״ב כו׳ (קונט׳ עה״ח פ״ד. ושם, ד„לחם״ הוא מלשון מלחמה. ע״ש)]. ובלקו״ת וסדור שם, שהוא ע״ד מה שמיחוע״ע נמשך הכח ועוז ליחרית — והרי זהו דוגמת פעולת פנימיות התורה בנגלה דתורה (כמשנ״ת בארוכה בקונט׳ עה״ח פי״א ואילך)."],["44","44","פרשתנו טז, יח."],["45","45","ראה בכ״ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091017\" data-slug=\"likkutei-sichot\" data-id=\"1300091017\">לקו״ש ח״ט ע׳ 17</a> ואילך, ושם״נ."],["46","46","פרשתנו שם, טז."],["47","47","ולהעיר ממש״נ גבי שליו דפ׳ בהעלותך — יא, לב."],["48","48","סד״ה ביום השני תרפ״ה (בסה״מ קונט׳ ח״ב בסופו). ועוד. וי״ל שזהו ג״כ טעם הפנימי לזה שלחם ניתן לשובע ובשר רק לאכול — כי מכיון שפנימיות התורה היא למעלה ממדודה אא״פ להיות בזה שב״עה."],["49","49","זח״ב סג, ב. פח, א."],["50","50","ראה תו״ח שם שיא, ב."]]],[1300161185,"אבער זיין ירידה למטה (אלס „לחם״ כנ״ל) איז געווען דוקא בימות החול51.\nמשא״כ שליו, וואס זיין השפעה והמשכה למטה האט זיך אנגעהויבן (לדעת רש״י<sup data-n=\"52\">52</sup> ביום השבת53; און נאכמער — שבת בין הערביים54, דער זמן פון רעווא דרעווין, וואס אין שבת גופא, איז דער זמן פון שבת שייך באופן מיוחד צו פנימיות התורה.\nיב. אויף דעם זאגט רש״י, אז די שאלת לחם איז געווען „לצורך״ ו„כהוגן״, ווייל „א״א לו לאדם בלא לחם״ — אן נגלה דתורה, לידע את המעשה אשר יעשון ואלה אשר לא תיעשנה, קען מען ניט אויסקומען; און וויבאלד אז כדי נגלה דתורה זאל זיין כדבעי דארף מען אנקומען צו פנימיות התורה — האט מען זיי געגעבן מן, לחם מן השמים.\nאבער די שאלת בשר איז געווען „שלא כהוגן״, און מצד צוויי טעמים:\nא) „שהרבה בהמות היו להם״, וואס פון דעם איז מוכרח אז לויט פרש״י האבן אידן געבעטן בשר בהמה55, וואס איז חומרי ביותר (און ניט אזוי קיין כלי צו בחי׳ „שמן״, וואס ווייזט אויף ביטול) — ובנוגע תורה מיינט עס, אז אידן האבן געוואלט „נעמען״ פנימיות התורה ווי זי קומט אראפ אין השגה פון נפש הבהמית, וואו עס הערט זיך ניט אזוי דער אור אלקי פון דער השגה,\n[און דערפאר האט מען זיי געגעבן שליו — „מין עוף״, ווייל בשר עוף איז ניט אזא חומרי ווי בשר בהמה און איז דעריבער א כלי צו בחי׳ שמן; ובנפש האדם איז „עוף״ און שליו בפרט ווי נפש האלקית טוט זיך אן אין נפש השכלית56, דער שליו איז ווי פנימיות התורה קומט אראפ אין השגה פון נפש האלקית און דורך איר אין נפש השכלית].\n(ב) „ועוד שהי׳ אפשר להם57 בלא בשר״: זיי, זייענדיק דאן פאר מ״ת, איז ניט געווען קיין הכרח מגלה זיין די חמדה גנוזה58 — הבנה והשגה אין פנימיות התורה. נאכמער: וויבאלד עס איז געווען פאר דעם ביטול הגזירה צווישן „עליונים״ ו„תחתונים״, האט דאן ניט געקענט זיין דער חיבור פון „עליון״",[["51","51","כי ירידתו למטה היא בשביל עבודת הבירורים (כנ״ל הערה 43), ולכן היא בששת ימי החול, זמן עבודת הבירורים (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380778\" data-slug=\"likkutei-torah\" data-id=\"4001380778\">לקו״ת שם טז, רע״א</a>. סדור ותו״ח שם)."],["52","52","ראה רש״י פרשתנו (טז, א) „וירד להם מן בט״ז אייר ויום א׳ בשבת הי׳ כדאיתא במס׳ שבת (פז, ב)*. והרי השליו התחיל לירד בערב שלפנ״ז (ראה פסוק יג). אבל בבחי׳ שם: השליו והמן התחילו לבא באחד בשבת."],["53","53","ולכאורה הוא חידוש גדול. וראה מפרשי רש״י (טז, א) ועוד. וצ״ע וחיפוש. וגם בירור — מתי אספו אותו. ועוד שנאמר „בין הערבים תאכלו בשר״. וגם — לאחר מ״ת הרי נאסרו בכל מלאכות שבת (משא״כ במרה — שלפרש״י (טו, כה) (רק) נתן להם כו׳ פרשיות של תורה שיתעסקו בהם שבת כו׳. וראה לקו״ש חלי״א ס״ע 86 ואילך). ואכ״מ."],["54","54","פרשתנו טז, יב [ומזה מוכח, ד„ערב״ כאן (פסוק ו, ח, יג) פירושו (לא לילה, כ״א) זמן מנחה (ראה רש״י בא יב, ו)]. *) משא״כ לדעת הסדר עולם רבה (פ״ה. וראה שבת פח, רע״א) שט״ו באייר א׳ בשבת הי׳."],["55","55","וי״ל שזהו ההכרח (ע״ד הפשט) לפירוש רש״י שהשליו הי׳ „שמן מאד״ — כי מכיון שבקשו בשר בהמה, ניתן להם בשר שמן (שדומה עכ״פ לבשר בהמה). ולהעיר מרש״י בהעלותך יא, כג."],["56","56","ראה לקו״ת ח״ד ע׳ 1295."],["57","57","ע״פ המבואר בפנים יומתק מה שבנוגע ללחם לשון רש״י הוא „א״א לו לאדם״, ואילו בבשר אומר „הי׳ אפשר להם״ [אלא שבאחדים מכת״י רש״י איתא „אפשר לחיות בלא בשר״. ובא׳ מכת״י רש״י: אפשר להם לחם בלא בשר]."],["58","58","שבת פח, סע״ב."]]],[1300161186,"ו„תחתון״, אז פנימיות התורה (בחי׳ „עליונים״ שבתורה) זאל אראפקומען כמו שהיא אין השגה, ובפרט אין השגה פון נפש הבהמית (בחי׳ „תחתונים״).\n[און דערפאר איז דער שליו געגעבן געווארן ש„לא בפנים מאירות״ — די פנימיות שלמעלה האט ניט מאיר געווען אין בשר השליו].\nעפ״ז קומט אויס, אז דער ענין השליו (אראפטראגן בחי׳ „שמן״ שבתורה אין „בשר״ — השגה) איז דעמאלט געווען פארבונדן מיט אן ענין של ירידה.\nמשא״כ נאך מתן תורה, ובפרט נאכן גילוי האריז״ל ואמירתו אז „מצוה לגלות זאת החכמה59״, ובפרטי פרטיות נאך גילוי (תורת החסידות, ובמיוחד) תורת חסידות חב״ד — זיינען רזי דרזין דאורייתא געגעבן געווארן אין אן אופן אז יעדערער זאל זיי קענען פארשטיין מיט חב״ד שבנפשו60.\nיג. דער ביאור — אז „הי׳ אפשר להם בלא בשר״ איז מצד דערויף וואס זיי זיינען דאן געווען פאר מ״ת — איז נאר לויט דער דיעה61 (ואת״ל) אז דער שליו וואס רעדט זיך ווענגן און וועלכן איז אונזער סדרה, איז געווען פאר זייער א קורצן זמן (בלויז פאר מ״ת).\nפון דעם אבער וואס רש״י דערמאנט ניט דעם חילוק צווישן מן ושליו (אז דער שליו בערב איז געווען ווען לחם בבוקר נאר דריי וואכן, אע״פ אז דער לחם האט אנגעהאלטן במשך ארבעים שנה), איז משמע, אז רש״י (בפירושו על התורה<sup data-n=\"62\">62</sup> נעמט אן, אז דער חילוק צווישן זיי איז נאר בנוגע זמן הנתינה (בערב אדער בבקר) — אבער אויך דער שליו איז געווען די גאנצע צייט וואס דער מן האט יורד געווען (און אזוי איז אויך לרוב הדיעות<sup data-n=\"63\">63</sup>.\n— איז דער ביאור אין „הי׳ אפשר להם בלא בשר״ לויט די דיעות (כולל פרש״י):\nכשם ווי משה איז דרגתו — ראי׳64 אין אלקות, און ער האט געפרעגט מיט א תמי׳ „מאין לי בשר״65 (ווייל ער איז העכער פון בחי׳ בשר<sup data-n=\"66\">66</sup> — אזוי אויך ביים דור המדבר, דור דעה67, דורו של משה68: ביי זיי איז געווען ראי׳69 אין אלקות, זיי זיינען געווען ארומגערינגלט פון די ענני הכבוד, זיינען געווען דור המדבר (בחי׳ מחשבה<sup data-n=\"70\">70</sup> וכו׳:\nאיז ביי זיי, דער ענין פון בשר (כולל בשר השליו) — הבנה והשגה אין אלקות — און ענין של ירידה71.",[["59","59","אגה״ק סכ״ו (קמב, ב)."],["60","60","ראה לעיל בפנים, ד„שליו״ הוא רזין דאורייתא כפי שבאים בהשגה."],["61","61","סדר אליהו רבה פי״ג (פי״ב) ועוד."],["62","62","וראה ג״כ בפירושו על הש״ס (ערכין טו, ריש ע״ב), הרמב״ן כאן ועוד."],["63","63","נקבצו בתו״ש עה״פ טז, יג."],["64","64","ראה לקו״ת ואתחנן ג, א ואילך."],["65","65","בהעלותך יא, יג."],["66","66","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380437\" data-slug=\"likkutei-torah\" data-id=\"4001380437\">לקו״ת בהעלותך (לא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380443\" data-slug=\"likkutei-torah\" data-id=\"4001380443\">לג, ב</a>) שזהו למטה ממדרגתו לגמרי."],["67","67","ראה ויק״ר פ״ט, א. במדב״ר פי״ט, ג. וש״נ."],["68","68","ראה ע״ח שער הכללים פי״א. ש׳ הפסוקים ר״פ שמות. ובכ״מ. לקו״ת שנעתק לקמן הערה 71."],["69","69","ראה לקו״ת ואתחנן (שם, ד) דבחי׳ ראי׳ דמשה היא מצד זה שדרגתו יסוד אבא — ודור המדבר שייכים ליסו״א (כדלקמן הערה 71)."],["70","70","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380461\" data-slug=\"likkutei-torah\" data-id=\"4001380461\">לקו״ת שלח לז, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380465\" data-slug=\"likkutei-torah\" data-id=\"4001380465\">לח, ב</a>."],["71","71","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380437\" data-slug=\"likkutei-torah\" data-id=\"4001380437\">לקו״ת בהעלותך (לא, ד</a>): שש מאות אלף רגלי דור המדבר היו תלמידים שהיו ג״כ מבחי׳ יסוד אבא .. וא״כ איך אפשר להיות (הבשר) למאכל להם שהם מיסוד אבא וכו׳."]]],[1300161187,"[און דאס איז אויך וואס מ׳זאגט אז דער שליו איז געגעבן געווארן „בשעת טורח״ — לגבי ראי׳ אין אלקות, איז השגה אן ענין פון „טירחא״].\nמשא״כ אין שפעטערדיקע דורות, ובפרט בדורותינו אלה, דעקבתא דמשיחא, איז די „שאלת בשר״ כהוגן וכהוגן, ואדרבה — דוקא דורך יפוצו מעינותיך חוצה, די מעינות שבתורה,\nאיז אתי מר72 דא מלכא משיחא, ובלשון הרעיא מהימנא73: בהאי חבורא דילך .. ספר הזהר יפקון בי׳ מן גלותא ברחמי.\n(משיחות ש״פ בשלח תשל״ד, תשכ״ו)",[["72","72","אגה״ק הידועה דהבעש״ט (נדפסה בס׳ בן פורת יוסף בסופו. כתר שם טוב בתחלתו. ועוד)."],["73","73","זח״ג קכד, ב."]]],[1300161188,"<h3>בשלח ג</h3>\nא. דעם ערשטן מאל וואס אין דער תורה ווערן אנגעזאגט די ציוויים און דינים פון שבת¹, איז אין אונזער פרשה בשייכות צום מן². און וויבאלד אז אלע עניני התורה זיינען בתכלית הדיוק, איז מובן, אז דער ענין פון מן און שבת האבן א שייכות (אין תוכן):\nאון ווי דאס איז אויך משמע פון דעם וואס ס׳ווערט געבראכט בשם הרס״ג³, אז בשעת מען געפינט זיך בשבת (אין א ווייטן וועג⁴) און מען ווייס (דארט) ניט וועלכע פרשה מ׳דארף לייענען דעם שבת, זאל מען לייענען פרשת המן.\nנאכמער: טראץ דעם וואס בשבת איז דער מן ניט געקומען, שטייט אבער אין זהר⁵, אז אדרבא די ברכה למעלה אויף ירידת המן אין די ששת ימי השבוע איז געווען בשבת; און ווי עס שטייט אויך אין מכילתא⁶ — „ברכו במן“⁷.\nדארף מען פארשטיין: אין וואס בא־שטייט דער קשר⁷* צווישן מן און שבת⁸? לכאורה: ניט נאר איז ניט ניכר קיין שייכות צווישן זיי, נאר זיי זיינען ענינים וואס זיינען אינגאנצן אנדערש איינער פון צווייטן — די מצות און ענינים פון שבת זיינען פאראן אין אלע זמנים ומקומות, ירידת המן אבער איז געווען נאר אין א זמן מסוים און מקום מוגבל — אין די פערציג יאר און נאר במחנה ישראל במדבר?\nב. לכאורה וואלט מען געקענט זאגן בפשטות, אז די נקודה משותפת פון מן און שבת איז אין דעם, וואס אין ביידע איז ניטא קיין טירחא און עבודה: דער מן איז געווען „לחם מן השמים“, מען האט ניט געדארפט אקערן, זייען וכו׳ אויף צו באקומען אים; און עד״ז איז ביי שבת, אז נוסף אויף דעם איסור צו טאן מלאכה בשבת, איז — „משום עונג שבת“ — א „מצוה שלא להרהר כלל בעסקיו אלא יהא בעיניו כאילו כל מלאכתו עשוי׳“⁹.\nדאס איז אבער לכאורה ניט מספיק, ווייל:",[["1","1","משא״כ הסיפור דשבת — שהוא בפ׳ בראשית."],["2","2","משא״כ לפני זה בהכתוב (טו, כה) „שם שם לו“ — שלא נאמר מפורש בכתוב שבת כ״א במדרז״ל — ראה סנהדרין נו, ב. מכילתא ופרש״י עה״פ. ועוד. וגם בזה להעיר: א) בגמרא שם למדין דשבת במרה נצטוו מהכתוב בואתחנן (ה, יב) „כאשר צוך“ (הובא בפרש״י שם). ב) נתבאר במ״א (לקו״ש חל״א ס״ע 86 ואילך) שע״פ פשש״מ מדייק רש״י (בפרשתנו שם) „פרשיות של תורה (כולל — שבת) שיתעסקו בהם“, ולא קיום מצות אלו. ואכ״מ."],["3","3","ספר העתים הל׳ ברכת ועונג שבת סקפ״ד (בסופו)."],["4","4","כ״פ בספר העתים שם דברי הרס״ג."],["5","5","ח״ב סג, ב. פח, א."],["6","6","יתרו כ, יא."],["7","7","כ״פ בכ״מ בדא״ח (ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450638\" data-slug=\"or-hatorah-hb\" data-id=\"8316450638\">אוה״ת פרשתנו ע׳ תרלח</a>-ט, המשך תער״ב ח״ב ע׳ א׳סא, א׳פו ועוד) שפי׳ המכילתא והמדרש (ב״ר פי״א, ב) ברכו במן הוא שהמשכתו (למעלה) היא בשבת. אף שבב״ר שם מפרש דהברכה היא דבערב שבת ירד שני עומרים (ועד״ז בפרש״י בראשית ב, ג. יתרו שם). ואולי המובא בדא״ח הוא פי׳ המכילתא וב״ר ע״ד הרמז. ואכ״מ. *7) זה שלא ירד בשבת — מובן בפשטות, כי כיון שאסור ללקטו — וכל כיו״ב — ה״ז בדרך ממילא שולל ירידתו."],["8","8","ראה ע״ד החסידות — <a class=\"ft-cite\" href=\"#/read/torah-or/3901370292\" data-slug=\"torah-or\" data-id=\"3901370292\">תו״א פרשתנו סה, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550601\" data-slug=\"torat-chaim\" data-id=\"2300550601\">תו״ח</a> ד״ה ויאמר ה׳ (שב, א ואילך). אוה״ת ד״ה ויאמר משה אכלוהו גו׳ וביאורו (ושם ע׳ תרלט: וזהו שנסמכה פ׳ שבת לפ׳ המן ובב״א נאמרו). המשך תער״ב שם. ובכ״מ. וראה לקו״ש ח״ד ע׳ 1037."],["9","9","שו״ע אדה״ז סש״ו סכ״א. מכילתא יתרו כ, ט (פרש״י שם). טושו״ע שם ס״ח."]]],[1300161189,"א) ביי דעם מן געפינט מען דאך געוויסע טירחות, ווי די גמרא זאגט¹⁰: „צדיקים לחם, בינונים עוגות, רשעים טחנו בריחים או דכו במדוכה“, און אזוי אויך: „צדיקים ירד על פתח בתיהם בינונים יצאו ללקוט רשעים שטו ולקטו“ — ניט ווי דער ענין פון „כל מלאכתו עשוי׳“ ביי שבת, אז א איד דארף אפילו ניט מהרהר זיין אין זיינע עסקים¹¹.\nב) ולאידך גיסא: די שלילת העבודה בשבת נעמט ארום אלע סוגי מלאכה — „כאילו כל מלאכתו עשוי׳“, משא״כ ביי מן איז דאך ענינו נאר שלילת הטירחא בשייכות צו מזון האדם.\nדערפאר איז מסתבר, אז די שייכות צווישן מן און שבת איז אין דעם פרט פון צוגרייטן די עניני מזון ואכילה פון שבת.\nאון ווי דאס איז אויך מובן פון דעם וואס דער חיוב פון ג׳ סעודות פון שבת, און אויך פון לחם משנה, לערנט מען¹² אפ פון די פסוקים¹³ בנוגע צום מן — „ויאמר משה אכלוהו היום כי שבת היום לה׳ היום לא תמצאוהו בשדה“, „לחם משנה“ — ד.ה. אז די עניני אכילה¹⁴ פון שבת לערנט מען ארויס¹⁵ פון מן¹⁶.\nג. אויפן פסוק¹⁷ „הנני ממטיר לכם לחם מן השמים ויצא העם ולקטו דבר יום ביומו למען אנסנו הילך בתורתי אם לא“ זאגט רש״י [אויף „למען אנסנו“]: „אם ישמרו מצות התלויות בו שלא יותירו ממנו ולא יצאו בשבת ללקוט“, אז דער טעם און מכוון אין ירידת המן איז צו אויספרואוון „אם ישמרו מצות התלויות בו“, וואס די מצות זיינען: שלא יותירו ממנו ולא יצאו בשבת ללקוט.\nדארף מען פארשטיין: וואס איז די שייכות צווישן די צוויי מצות (א) „שלא יותירו ממנו (ב) ולא יצאו בשבת ללקוט“, וואס זיי ביידע זיינען דער „למען“, דער טעם פון ירידת המן.\nד. וועט מען דאס פארשטיין בהקדים לבאר דעם חידוש פון מן, וואס איז „לחם מן השמים“, אויף „לחם מן הארץ“:\n„לחם מן הארץ“ איז פארבונדן מיט עבודת האדם: דורך דעם וואס ער גרייט צו א כלי אין דרך הטבע (חרישה, זריעה כו׳), איז דער אויבערשטער משפיע „לחם“ (וואס איז אויך מרמז וכולל — אלע צרכי האדם) דורך דעם כלי און לבוש.\nמשא״כ לחם מן השמים איז ניט תלוי אין א כלי פון דרכי הטבע — ס׳איז אין דעם ניטא קיין עבודת האדם.",[["10","10","יומא עה, א."],["11","11","ואין בשביתת שבת חילוקים דצדיקים, בינונים כו׳. אבל להעיר מירושלמי שבת פט״ו ה״ג: מעשה בחסיד אחד כו׳. ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111088\" data-slug=\"likkutei-sichot\" data-id=\"1300111088\">לקו״ש חי״א ע׳ 80</a> וע׳ 87 ואילך."],["12","12","שבת קיז, ב."],["13","13","טז, כב. כה."],["14","14","ולהעיר מרמ״א או״ח סרמ״ב (ממהרי״ל) יש שכתבו שבקצת מקומות נהגו לאכול כו׳ בליל שבת זכר למן שהי׳ מכוסה למעלה. אלא שבזה מסיים „ולא ראיתי לחוש לזה“. אבל בנוגע לפריסת מפה כו׳ כתב בשו״ע אדה״ז סי׳ רעא סי״ז (מהגמרי״י הל׳ שבת פכ״ט אות ק׳ (בשם סה״ת). טור שם. ט״ז שם סקי״ב (ושם: וכן אנו נוהגין גם במקדש על הפת (על פי טעם זה). ובשו״ע אדה״ז שם הביא רק טעם זה)) „צריך שתהא כו׳ כדי שתהא הפת בין שתי מפות זכר למן שהי׳ עליו טל כו׳“."],["15","15","ובשו״ע אדה״ז ס׳ ער״ד ס״א „ורמז לזה“ (ג׳ סעודות). ובס״ב „וסמך לזה“ (לחם משנה). וידוע השקו״ט בזה. ואכ״מ."],["16","16","אלא שלימוד זה (ג׳ סעודות ולחם משנה) הוא מענין המן בשבת: ויתירה מזו בהנ״ל (שבהערה 14) שבזה עושין זכר בשבת לירידת המן בכלל (בו׳ ימי החול)."],["17","17","טז, ד."]]],[1300161190,"ומובן, אז בהתאם לזה איז אויך די פעולה אויף רגש האדם:\n„לחם מן הארץ“, וואס די ברכת ה׳ איז אנגעטאן אין דער טבע׳דיקער כלי וואס דער מענטש גרייט צו, איז\n— כאטש ער ווייס אז זיין הכנה־ארבעט איז ניט מער ווי א כלי און א „לבוש“ צו דער ברכת ה׳¹⁸; און נאך־מער — אויך דעם „לבוש“ און די „כלי“ אין טבע מאכט ער ניט דערפאר וואס טבע פארנעמט ביי אים אן ארט, נאר בלויז ווייל אזוי איז דער רצון וציווי ה׳¹⁹, אז „וברכך ה״א“ איז דוקא „בכל אשר תעשה“²⁰ (ניט דורך זיין א „יושב ובטל“²¹), פונדעסטוועגן —\nוויבאלד אז לפועל קומט דער „לחם — מן הארץ“, דורך דעם „לבוש“ (ארציות ו)טבע, וואס דער מענטש טוט אויף דורך זיין עבודה און מלאכה — גיט עס א ארט צו מחשיב זיין דעם מענטשנ׳ס „אויפטו“ פאר זיין פרנסה.\nמשא״כ לחם מן השמים, וואו ס׳איז ניט פאראן קיין אריינמישונג פון פעולת האדם²², דערוועקט עס ביי אים די תנועה פון פארלאזן זיך אינגאנצן אויפן אויבערשטן.\nעפ״ז איז מובן, אז דער נסיון „אם ישמרו מצות התלויות בו שלא יותירו ממנו“ איז דער טעם — דער מכוון פון ירידת המן, „לחם מן השמים“: כדי ארויסצובריינגען (און דורך דעם „אויס־פרואוון“) ביי אידן דעם שלימות׳דיקן בטחון אין דעם אויבערשטן, אז זיין גאנצער לחם (און אלע הצטרכיות) קומט בלויז פון דעם אויבערשטן אליין, אן קיין שום „לבוש“ און „פארמיטלונג“ פון מלאכת האדם — טאר ניט זיין קיין ארט אז דער מענטש זאל זיך אליין בא־זארגן מיט לחם אויף מארגן („שלא יותירו ממנו“). און ווי ער זאגט אין תנחומא²³ „דבר יום ביומו, מי שברא יום ברא פרנסתו מכאן הי׳ ר״א המודעי אומר כל מי שיש לו מה יאכל היום ואומר מה אוכל למחר הרי זה מחוסר אמונה“²⁴.\nה. הגם אז לחם מן השמים איז בעיקרו ובכללותו ניט אפהענגיק אין עבודת האדם — וואס דערפאר איז די ירידת המן געווען צוזאמען מיט ירידת הטל²⁵, וואס „טל לא מיעצר“²⁶ (היות ס׳איז ניט תלוי אין עבודת האדם, כידוע²⁷) — געפינט מען אבער, אז אויך דער מן איז געווען פארבונדן מיט טירחת האדם, ווי געזאגט פריער (סעיף",[["18","18","ראה ספר המצות להצ״צ מצות תגלחת מצורע בסופו. קונטרס ומעין מאמר יז, מאמר כה פ״ב. ד״ה וידעת תרנ״ז. ועוד."],["19","19","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181303\" data-slug=\"likkutei-sichot\" data-id=\"1300181303\">לקו״ש חי״ח ע׳ 294</a> ואילך. וש״נ."],["20","20","ראה טו, יח."],["21","21","ספרי עה״פ. וראה לקו״ש שם הערה 19."],["22","22","ויתירה מזו: פעולת האדם אינה פועלת כלום בזה וכמש״נ (פרשתנו טז, יח) „ולא העדיף המרבה והממעיט לא החסיר“."],["23","23","פרשתנו כ. וראה גם יומא עו, א: נמצאו כולן מכוונים את לבם לאביהן שבשמים. וראה זח״ב סב, ב. כלי יקר פרשתנו טז, ד. ועוד. — וראה שו״ע אדה״ז או״ח (מהד״ת) סי״א ס״ט. לקו״ש חכ״י ע׳ 95 ואילך."],["24","24","במכילתא עה״פ מתחיל בדעת ר״י „כדי שילקוט אדם וכו׳“, ו„כדי שלא ילקט אדם מהיום למחר“ הוא דעת ר״א המודעי. אבל ראה פי׳ „זה ינחמנו“ למכילתא דגם לר״י אין ללקוט מיום א׳ לחבירו. וכ״ה לרוב הגירסאות ופירושים בדעת ר״י במכילתא. ראה מכילתא הוצאת הארוויץ־רבין. ועוד."],["25","25","פרשתנו טז, יד. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370292\" data-slug=\"torah-or\" data-id=\"3901370292\">תו״א סה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380770\" data-slug=\"likkutei-torah\" data-id=\"4001380770\">לקו״ת עקב יד, א</a>־ב. ובכ״מ."],["26","26","תענית ג, א."],["27","27","ראה תו״א שם. לקו״ת שם (יד, ב). ובכ״מ. וכידוע החילוק בין טל למטר — בדרושי האזינו בלקו״ת (עג, ב ואילך) נסמן בלקו״ת עקב (שם, א)."]]],[1300161191,"ב); און דאס איז ניט נאר ביי רשעים און בינונים (וואס האבן געדארפט ארויסגיין אין דרויסן קלייבן), נאר אפילו ביי צדיקים, וואס דער מן איז „ירד על פתח בתיהם“, האבן זיי עכ״פ געמוזט האבן די טרחא פון צונויפקלייבן דעם מן פון „פתח בתיהם“.\nנאכמער: דאס גופא, וואס עס זיינען פאראן חילוקים אין דער טירחא צווישן די דריי דרגות פון אידן, איז א באווייז אז די ברכה פון מן איז ניט געווען אינ־גאנצן ניט פארבונדן מיט עבודת האדם המקבל (ניט אזוי ווי „טל“, וואו ס׳איז לחלוטין קיין חילוק ניט צו וועמען ער קומט אן — עס איז ביי אלעמען גלייך), נאר עס ווענדט זיך, אין א געוויסער מאס, אויף ווי פיל דער „מקבל“ האט זיך צוגעגרייט און איז ראוי צו דעם (ביי צדיקים — ווינציקער טירחא, ביי בינונים — מערער, און ביי רשעים — נאך מער).\n[דערמיט איז אויך מובן דער דיוק הלשון אין פסוק „הנני ממטיר לכם לחם מן השמים“ ניט ווי ער זאגט בפרשת המן (אין במדבר²⁷*) בנוגע צו טל „וברדת הטל“ — און לכאורה איז דא גאר א סתירה (בפנימיות הענינים): מטר ווייזט אויף א השפעה מלמעלה וואס קומט דורך עבודה דלמטה (ע״ד ווי מטר כפשוטו, וואס ווערט פון „ואד יעלה מן הארץ“²⁸), היינט ווי אזוי איז מתאים דער לשון „ממטיר“ ביי „לחם מן השמים“, וואס איז ניט תלוי אין דער עבודה פון אתערותא דלתתא?\nנאר די הסברה איז, כנ״ל: הגם אז „לחם מן השמים“ איז בעיקרו א השפעה וואס איז העכער פון עבודת המקבל (ע״ד הטל), קומט עס אבער אראפ למטה אין אן אופן (פון „ממטיר“, מטר) וואס האט (אויך) א געוויסע פארבונדנקייט מיט עבודת המקבל²⁹].\nו. דער ביאור אין דעם: דער ענין פון מן, „לחם מן השמים“, איז געווען א הכנה צו דער כניסה פון אידן אין ארץ ישראל, וואו דארט איז געווען דער סדר פון „לחם מן הארץ“ — ווייל דורכ־דעם וואס מען האט באוויזן אידן בגלוי ווי זייער פרנסה און הצטרכות ווערט זיי געגעבן נאר פון דעם אויבערשטן אליין, האט דאס זיי צוגעגרייט און געגעבן דעם כח, אז אויך קומענדיק „ארץ נושבת“ און אריבערגייענדיק צום סדר פון „לחם מן הארץ“, זאל מען ניט פאר־געסן ח״ו אז „הוא הנותן לך כח לעשות חיל“³⁰.\nנאך מער: דער „לחם מן השמים“ איז ניט בלויז א הכנה און נתינת כח, נאר ער ווערט נמשך און נרגש אויך אין „ארץ נושבת“ — וויבאלד אז אידן זיינען בעצם העכער פון וועלט און טבע, איז דער אמת, אז אפילו ווען זיי „קומען אראפ“ אין וועלט, אין א סדר העבודה פון „ארץ נושבת“ — איז זייער השפעת הפרנסה באמיתית ובפנימיות ניט פאר־בונדן מיט די דרכי הטבע פון „לחם מן הארץ“",[["","","27*) בהעלותך יא, ט. הובא בפרש״י כאן טז, יג."],["28","28","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381020\" data-slug=\"likkutei-torah\" data-id=\"4001381020\">בראשית ב</a>, ו. ולהעיר מפרש״י שם, ה. ראה לקו״ת (האזינו שם, א. עד, ב)."],["29","29","והי׳ צ״ל אכילה כפשוטה (כלחם מן הארץ) וגם (לכמה ראשונים) ברכה לפני׳ המוציא לחם מן השמים או בנוסח אחר (הרמ״ע מפאנו בס׳ מאמר שבתות ה׳ ח״ב בתחלתו שכן יברכו לעת״ל על המן השמור בצנצנת. ובס׳ חסידים (הוצאת מק״נ) סי׳ תתתת״מ על המן היו מברכים הנותן לחם מן השמים. וראה אוה״ח לזח״ב (סב, ב) שהרמ״ק מפרש בזהר שהיו מברכין ברכת המוציא, ולאחריו ברכת המזון). ואכ״מ."],["30","30","עקב ח, יח."]]],[1300161192,"[אפי׳ ניט אין אן אופן וואס טבע בפני עצמו האט קיין באטרעף ניט, עס איז ניט מער ווי א „לבוש“ צו „ברכת ה׳“; און דער לבוש גופא מאכט ער נאר דערפאר וואס אזוי איז דער ציווי ה׳ כנ״ל — אבער דאך איז די השפעה פארבונדן מיט טבע, די ברכת ה׳ קומט אן צום מענטש דורך דער כלי וואס ער האט צוגעגרייט].\nנאר אז אויך דער „לחם“, די פרנסה „מן הארץ“, איז אין אן אופן פון „לחם מן השמים“, וואס איז איבערהויפט ניט געבונדן מיט דרכי הטבע.\nאון דאס איז די אמת׳ע שלימות הבטחון פון א אידן אין אויבערשטן:\nניט נאר אין פאל ווען ער זעט ניט קיין אויסזיכט אין דרכי הטבע³¹ צו בא־קומען פרנסה, ובמילא איז כאילו קיין ברירה ניטא און ער פארלאזט זיך אויפן אויבערשטן אז ער וועט אים באזארגן זיין פרנסה באופן נסי³², ווי ירידת המן אין מדבר —\nנאר אפילו ווען ער מאכט יא א כלי אין טבע (ווייל אזוי האט דער אויבערשטער געהייסן), איז ביי אים אפגעלייגט אז זיין פרנסה איז (בעיקרה) „לחם מן השמים“³³ — ניט געבונדן מיט דרכי הטבע; און אז די הבטחה פון „וברכך ה״א בכל אשר תעשה“ מיינט ניט בלויז אז דאס וואס דער אויבערשטער בענטשט אים איז בערך צו (די מדידות והגבלות פון) דער „כלי“ („תעשה“) וואס ער האט צוגעגרייט (אפילו ווען ס׳איז אין אן אופן פון „וברכך“ — ברכה והצלחה) — נאר ס׳איז באין ערוך³⁴, אזוי, אז די כלי איז ניט תופס מקום³⁵.\nז. און דאס איז די הסברה פארוואס דער מן האט געדארפט זיין פארבונדן מיט (עכ״פ קצת) עבודת וטירחת האדם:\nווען דער „לחם מן השמים“ וואלט אינגאנצן ניט געווען פארבונדן מיט עבודת האדם, וואלט עס ניט געהאט קיין פארבונד און ענלעכקייט מיט „לחם מן הארץ“, ובמילא וואלט געבליבן א מקום לטעות: ביי „לחם מן השמים“ וואס איז אינגאנצן ניט תלוי אין דער הכנה ועבודה מצד דעם מקבל, פאדערט זיך דער פולער בטחון און פארלאזן זיך אויף דעם אויבערשטן; משא״כ „לחם מן הארץ“, וויבאלד אז תורה אליין זאגט³⁶ אז שש שנים תזרע שדך גו׳ — דא איז נויטיג די עבודה פונעם מענטשן, איז דערפון גופא א הוכחה אז צוגרייטן די כלי אין טבע האט א „תפיסת מקום“ אין דער השפעת הפרנסה.",[["31","31","שאז הוא אמיתית ענין הבטחון — ראה בארוכה המשך תער״ב ח״א פרק פב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151299\" data-slug=\"likkutei-sichot\" data-id=\"1300151299\">לקו״ש חי״ג ע׳ 883</a> ובמכתב כ״ק מו״ח אדמו״ר שנעתק בהערה 30 שם. ד״ה ובבואה לפני המלך תרנ״ד (נעתק בלקו״ש חט״ו ע׳ 286 הערה 47)."],["32","32","ראה המשך תער״ב שם: כאשר רואין שההנהגה צ״ל באופן כזה אין זה בכלל אין סומכין על הנס כו׳."],["33","33","וזהו החידוש והעילוי על הבטחון הגמור שיש לו כאשר אין שום מראה מקום גשמי להעזר, שגם כאשר הוא צריך ע״פ תורה לעשות כלי בטבע, מ״מ הבטחון שלו בה׳ הוא אותו הבטחון הגמור בה׳ כמו אם לא הי׳ לו כלי בטבע."],["34","34","ראה דרך חיים בהקדמה (ג, א)."],["35","35","ראה אוה״ת פרשתנו ע׳ תרמד: האמת האמיתי הוא שאין לאדם לדאוג כלל מה יהי׳ למחר ומה יהי׳ פרנסתו .. כדרך זה יום ביומו .. מי שאינו רוצה בזה יוכל להיות שיכין מזונו על כל השנה או על כמה שנים אבל באמת הרצון לזה הוא מפני התרחקותו מה׳ ע״י כמה השתלשלות עד שנמשך ומתלבש בלבוש הטבע .. בלחם מן הארץ .. הרוצה לדבקה בו יתברך יוכל להמשיך בבחינה זו גם כן גילוי יומין עילאין להיות ברוך ה׳ יום יום כו׳. ועיי״ש בארוכה."],["36","36","בהר כה, ג."]]],[1300161193,"און דערפאר איז אויך דער „לחם מן השמים“ געווען אין אן אופן פון „ממטיר“, אז עס זאל זיין דורך טירחה (הנ״ל, עכ״פ) ועבודת האדם — וואס דאס באווייזט, אז אויך דארט וואו עס איז פאראן עבודת האדם, זאל דער־הערט ווערן, אז די השפעה מלמעלה איז (כלל ניט געבונדן מיט דער עבודה פון אדם, נאר ס׳איז) לחם מן השמים³⁷.\nאון דאס איז די נתינת כח אז אויך אריינקומענדיק אין ארץ נושבת, זאל זיך אפלייגן ביי א אידן³⁸, אז אויך דער דארטיקער סדר העבודה, פון „לחם מן הארץ“ איז בפנימיותו — לחם מן השמים³⁹.\nח. דערמיט וועט ווערן פאר־שטאנדיק א דבר פלא וואס מען געפינט ביי ברכת המזון:\nדי ערשטע ברכה, ברכת „הזן“ האט משה רבינו מתקן געווען „בשעה שירד להם המן“; די צווייטע ברכה, ברכת הארץ — „יהושע תיקן להם“, ווען מ׳איז אריין אין ארץ ישראל⁴⁰. ולכאורה שטעלט זיך די שאלה: „ברכת המזון“ איז ענינה וואס א איד דאנקט און לויבט דעם אויבערשטן פאר דעם מזון וואס ער האט אים איצט געגעבן — ווי קומט עס אז ברכת הזן וואס מיר מאכן אויף דעם (וואס איז — לחם מן הארץ) איז דער נוסח וואס משה האט מתקן געווען אויף ירידת המן — „לחם מן השמים“⁴¹.",[["37","37","ולהעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380773\" data-slug=\"likkutei-torah\" data-id=\"4001380773\">לקו״ת עקב יד, ד</a>. ושם: כי עיקר המשכה דברכת הזן ג״כ בשביל ברכת הארץ כו׳ גם בימי משה קודם שנכנסו לארץ הזכירו ברכת הארץ .. אלא שאז היתה כו׳ וגם נכללת תוך ברכת הזן שעל המן. ראה הערה הבאה. ולקמן בפנים ס״ח."],["38","38","וידועים דברי כ״ק אדמו״ר מהר״ש (סה״מ תש״ט ע׳ 21) שפרנסה בזמן הזה (בזמן הגלות) הוא באופן דהשפעת המן, לחם מן השמים. והנה ע״פ המדובר בפנים צ״ל כן בכל הזמנים, אבל הרי בא״י שהיו איש תחת גפנו כו׳ אי״ז ניכר כ״כ, משא״כ בצוק העתים הללו דזמן הגלות, נראה שאין השפעה באה ע״י ולפ״ע מעשי ידיו. וראה דרמ״צ קז, סע״א: בעסקו במו״מ יכוין שמאמין שהשפע ברכת ה׳ היא כשארי הנסים הגלויים כמו שהוריד המן כו׳."],["39","39","עפ״י כהנ״ל יובן הטעם שבפ׳ עקב (ח, ג) אמר משה „ויאכילך את המן גו׳ למען הודיעך כי לא על הלחם לבדו יחי׳ האדם כי על כל מוצא פי ה׳ יחי׳ האדם“ — שלכאורה הוא טעם שונה מהנאמר בפרשתנו „למען אנסנו גו׳, אם ישמרו מצות התלויות בו שלא יותירו ממנו כו׳“. אלא שבפרשתנו הטעם הוא לעצם ירידת המן — שיהי׳ אצל ישראל האמונה והבטחון הגמור בה׳, שרק ממנו בא מזונו כו׳. משא״כ במשנה תורה, בסוף ארבעים שנה לפני כניסתם לא״י אמר להם משה ענינו ופעולתו של המן בשייכות ללחם מן הארץ (סדר העבודה שצ״ל בארץ). ולכן אמר שע״י המן יודעים ש„לא על הלחם לבדו יחי׳ האדם“, שי״ל פירושו שחיות האדם הוא לא רק מחיות האלקי המלובש בהלחם גשמי*, „כי על כל מוצא פי ה׳ יחי׳ האדם“ (מוצא לשון מקור ושורש), היינו שחיותו הוא ממקור פי ה׳ (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380130\" data-slug=\"likkutei-torah\" data-id=\"4001380130\">לקו״ת צו יג, רע״ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380708\" data-slug=\"likkutei-torah\" data-id=\"4001380708\">מסעי צו, א</a>. ועוד) שלמעלה מהתלבשות בלחם גשמי ודרכי הטבע [בלשון החסידות: „יחי׳ האדם“ הוא לא רק מבחי׳ ממכ״ע שמתלבש בהבריאה, שמצד בחי׳ זו יש תפיסת מקום לדרכי הטבע, כ״א מבחי׳ סוכ״ע שלמעלה מהתלבשות, ומצד בחי׳ זו אין תפיסת מקום להנהגת ודרכי הטבע]."],["40","40","ברכות מח, ב. טור או״ח סקפ״ז. שו״ע אדה״ז שם ס״ג."],["41","41","כן הקשה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380771\" data-slug=\"likkutei-torah\" data-id=\"4001380771\">לקו״ת עקב (יד, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380130\" data-slug=\"likkutei-torah\" data-id=\"4001380130\">וראה סדור קו, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380771\" data-slug=\"likkutei-torah\" data-id=\"4001380771\">קט, א</a>), עפמ״ש הרשב״א ברכות (הובא בב״י לטואו״ח שם) „דמטבע הוא שטבע להן כו׳“, עיי״ש. *) דאם הכוונה לשלול שחיות האדם הוא לא מהלחם הגשמי כפשוטו, הרי אין צריך ע״ז הידיעה מהמן, שהרי זה באמונה פשוטה בכ״א מישראל שמציאות כל דבר הוא החיות האלקי שבו (שעהיוה״א בתחילתו). ובפרט שירידת המן הי׳ לאחר שאכלו המצה ביציאתם ממצרים שהיא מיכלא דמהימנותא — שנקבע בהם האמונה באלקות שמחי׳ את הלחם כו׳ (ראה לקו״ת צו יג, ג ואילך. ובכ״מ בדרושי חגה״פ). וראה ל״ת להאריז״ל פ׳ עקב. לקו״ת עקב יד, ב. סידור קז, א ואילך."]]],[1300161194,"נאכמער: די ערשטע ברכה לערנט מען אפ⁴² פון פסוק⁴³ „ואכלת ושבעת וברכת זו ברכת הזן שהיא על אכילה ושביעה“⁴⁴, און די צווייטע ברכה „על הארץ זו ברכת הארץ“⁴⁴; וואס דאס מיינט בפשטות אז די הודאה ביי דער צווייטער ברכה „על הארץ ועל המזון“, איז ניט אויף אכילה ושביעה (ווייל דאס איז דאך שייך צו ברכת הזן: „על אכילה ושביעה“), נאר אויפן ארץ — מיר דאנקען דעם אויבערשטן וואס די ארץ איז אזא וואס איז „מפקא מזון“⁴⁵ [וע״ד ווי ביי דער ברכה שלישית, בונה ירושלים].\nאיז דאך תמוה ביותר: ווי קומט עס, וואס די הודאה אויף (אונזער) „אכילה ושביעה“ ווערט נכלל דוקא אין דער (ערשטער) ברכה, וואס איר יסוד און תוכן איז לחם מן השמים (מן)?\nאבער לויט ווי ס׳האט זיך פריער גערעדט⁴⁶: דער לחם מן הארץ — כולל דאס וואס דער אויבערשטער בענטשט דעם ארץ און עס זאל זיין „ארץ דמפקא מזון“ — איז אין דער אמת׳ן בלויז א לבוש צו דעם שרש ומקור פון זייער מזון (פרנסה), וואס דאס איז „לחם מן השמים“:\nאון וויבאלד אז א איד אנערקענט דעם אמת אז (דער שרש פון) זיין מזון איז ניט אפהענגיק פון זיין הכנה און מלאכה, אפילו ניט פון די לבושי הטבע אלס כלי צו ברכת ה׳ — עס איז דורכאויס לחם מן השמים — איז מובן אז דער נוסח פון ברכת הזן אויף זיין אכילה ושביעה איז דער נוסח פון דער ברכה אויף „לחם מן השמים“, ווארום דאס איז דער אמת׳ער מקור פון זיין אכילה ושביעה; און ערשט דערנאך דאנקט ער דעם אויבערשטן אויף דעם וואס ער „בענטשט“ די כלי און לבוש אין טבע („וברכך ה״א בכל אשר תעשה“) — ברכת הארץ, ארץ דמפקא מזון.\nט. ע״פ כהנ״ל וועט מען אויך פאר־שטיין די שייכות צווישן מן און שבת:\nדי אלע פרטים הנ״ל אין מן: (א) ער איז „לחם מן השמים“ בגילוי — עס ווייזט אפן־קלאר אז מען דארף זיך פאר־לאזן אינגאנצן אויף דעם אויבערשטן, ווייל אלץ ווערט געגעבן פון דעם אויבערשטן אליין; (ב) עס איז אבער פארבונדן אויך מיט טירחת האדם, עבודת המקבל; און (ג) דאס גיט א כח אז אויך אינעם סדר פון לחם מן הארץ (וואו בגילוי איז עס פארבונדן מיט „ארץ“ און „טבע“) זאל מען וויסן אז בשרשו ובפנימיותו איז עס לחם מן השמים —\nזיינען זיי אויך פאראן אינעם תוכן הענין פון שבת:",[["42","42","ברכות שם."],["43","43","עקב ח, יו״ד."],["44","44","כ״ה בשו״ע אדה״ז שם ס״א. והוא כגירסתנו בגמרא שם. מכילתא בא יג, ג. וכן הובא ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370293\" data-slug=\"torah-or\" data-id=\"3901370293\">תו״א פרשתנו סה, ד</a> (ושם: זו ברכת הזן משה תיקן). לקו״ת עקב שם, סע״א. סדור קו, סע״ג. ובכ״מ. אבל בירושלמי ברכות (פ״ז ה״א), תוספתא ברכות (רפ״ו), וכן הביא בתוד״ה עד (שם מו, א. מ„לקמן בפירקין“), רא״ש פ״ז סי״ב (ועוד) „ואכלת ושבעת וברכת זו ברכת הזימון את ה׳ אלקיך זו הזן כו׳“. וראה דק״ס ברכות שם. ואכ״מ."],["45","45","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380771\" data-slug=\"likkutei-torah\" data-id=\"4001380771\">ברכות מט, א</a>. כ״ה פירוש הפשוט שהברכה היא רק על הארץ (דמפקא מזון). וראה ב״ח לטור שם. לבוש או״ח שם ס״א. שו״ע אדה״ז שם. אבל בלקו״ת עקב שם (יד, ב) סידור שם (קט, א) דמזון בברכת הארץ קאי על לחם מן הארץ. ולהעיר מברכ״י או״ח סי׳ רח סק״י שהביא מכפתור ופרח ואגודה דחותם בא״י „על הארץ ועל מזונה“."],["46","46","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380772\" data-slug=\"likkutei-torah\" data-id=\"4001380772\">לקו״ת עקב שם (יד, ג</a> ואילך), סדור שם — בלשון ע״ד החסידות."]]],[1300161195,"(א) וועגן די צרכים פון שבת⁴⁷ זאגן חז״ל⁴⁸ „לוו עלי .. והאמינו בי ואני פורע“, ד.ה. אז אויך ווען מ׳האט ניט, ח״ו, מיט וואס צו קויפן די צרכי השבת, און אפילו ניט קיין אויסזיכטן שפעטער צו פארדינען און באצאלן די הלואה⁴⁹ — דארף מען זיך אינגאנצן פארלאזן אויפן אויבערשטן, „לוו עלי .. ואני פורע“⁵⁰. ווייל די צרכי השבת קומען על דרך „לחם מן השמים“ — בלי עבודת המקבל.\n(ב) לאידך, איז עס דאך בפשטות פארבונדן מיט דער טירחא פון „לוו“: און נאכמער: דער דין איז געזאגט געווארן דווקא ווען ער האט חפצים, וואס דעמאלט „ימשכנם וילוה עליהם“: אויב אבער „אין לו משלו“ איז „לא ילוה ושהקב״ה יפרע“⁵¹, ד.ה. כאטש אז אויך ווען ער האט חפצים צו פאר׳משכון־נען, איז ניט זיין כוונה צו באצאלן דעם חוב מיט׳ן משכון, נאר, ווי דער לשון חז״ל „לוו עלי ואני פורע“⁵² — אז „הקב״ה ימציא לו לפרוע“⁵³ — פונדעסטוועגן, פאדערט זיך פארט א באשטימטע (טירחא און) „כלי“ מצד דעם אדם, ער מוז האבן עכ״פ „חפצים“ וואס „ילוה עליהם“⁵⁴.",[["47","47","להעיר משבת קיז, ב: „לעולם ישכים אדם להוצאת שבת שנאמר (בפרשתנו — במן — טז, ה) והי׳ ביום הששי והכינו כו׳“. וכ״ה בשבלי הלקט הובא בב״י לטאו״ח סי׳ רנ. ובטור ושו״ע אדה״ז (ס״א) „להכין צרכי שבת כו׳“."],["48","48","ביצה טו, סע״ב."],["49","49","ראה לקמן הערה 51, 52."],["50","50","להעיר מסוטה מח, סע״ב: „אלו בנ״א שהן מאמינין בהקב״ה כדתניא ר״א הגדול אומר כל מי שיש לו פת בסלו כו׳“ (כמאמר ר״א הנ״ל (ס״ד) שבתנחומא בנוגע למן), ובפרש״י שם „שמאמינים בהקב״ה לוותר ממונם כו׳ ולהוצאות שבתות כו׳“."],["51","51","שו״ע אדה״ז סי׳ רמב ס״ג (ע״פ תוד״ה לוו (לגירסת המהרש״ל), והגהות אשר״י ביצה שם). אבל בב״ח לטאו״ח שם מפרש הספק דהטור שהוא רק באם אין לו משכון*. אבל מסקנתו (דהטור) דילוה היא לא מצד מאמר הגמרא „לוו עלי ואני פורע“ כ״א מפני ש„צריך אדם לזרז עצמו וכנשר לכבד שבתות ביותר“ [אלא שמסיים: וכיון שכן (דלוו עלי ואני פורע) אל ידאג כי נאמן הוא בעל חובו לפרוע לו חובו]. וראה אות״ת להה״מ קיד, ג: „וז״ש לוו עלי כי זה מדבר בעני בעת שביתו ריקם ואין כל בבית כו׳“ עיי״ש. *) ולהעיר מהגהת הגר״א בתוס׳ (ושו״ע) שם, דגרים בתוס׳ שם: כשאין לו ממי ללוות."],["52","52","וי״ל שמזה מקור לדברי אדה״ז דמ״ש בתוס׳ לוו עלי (והגהות אשר״י) שם „הכא מיירי שיש לו משכונות כדי לפרוע ואין לו מעות“, אין הכוונה בזה שילוה ע״מ לפרוע עם המשכון גופא, כ״א ש„הקב״ה ימציא לו לפרוע“ (והמשכון הוא רק שיוכל „ללות עליהם“) — כי דוקא אז מתאים לומר „והאמינו בי ואני פורע“. (ומש״כ בסוף הסעיף „למשכנם ולפרוע בהם“ הרי כתבו רק בהשלילה „אם אין לו חפצים“, וכוונתו לבאר מטרת המשכון (שפורע בזה באם אין לו במה לשלם). וכדמוכח גם מהמשך לשונו „לא ילוה ושהקב״ה יפרע“. ועצ״ע). וע״פ הנ״ל בפנים ש„לוו עלי ואני פורע“ הוא דוגמת „לחם מן השמים“ מובן שלא איירי (דוקא) כשיש לו עסק ולוה בכוונה שירויח מן העסק (כמ״ש בערה״ש או״ח שם) — כי אז אי״ז הענין ד„האמינו בי ואני פורע“. וראה או״ת שם. ומוכרח הוא גם מהמשך הסוגיא שם: כל מזונותיו של אדם קצובים לו מר״ה חוץ מהוצאת שבתות כו׳ ואם הוסיף מוסיפין לו (כמ״ש אדה״ז שם „כלומר (שזהו פי׳ „לוו עלי“) שאין הוצאת שבת כו׳“ ראה תוד״ה כל שם „נפקי מקראי דלעיל“) ראה פרש״י שם ד״ה חוץ „אותה לא פסקו לו מה ישתכר לו לצרכה ומהיכן תבואהו“ דמשמע דמוסיפין לו גם אם אין לו עסק כו׳."],["53","53","שו״ע אדה״ז שם. ויומתק ע״ד החסידות ע״פ פי׳ אדה״ז שזהו״ע כל מזונותיו של אדם קצובים לו מר״ה כו׳, שהוצאות שבתות בא מבחי׳ אלקות שלמעלה מהתלבשות בהבריאה (שמצד בחי׳ המתלבשת בהבריאה ה„הוצאות קצובים לו“), ולכן בא בדרך מציאה מן השמים, בלי עבודת האדם, דוגמת ענין המן כמשנת״ל בארוכה."],["54","54","ראה ר״ח ביצה שם „אזמין לכם ברכה במעשה ידיכם כדי שתפרעו“. ולכאורה מוכח מדבריו שהמדובר ביש לו עסק (כפי הערוה״ש"]]],[1300161196,"(ג) דער עילוי פון שבת טוט אויף און איז משפיע אין די ששת ימי החול: דורך דעם וואס א איד האט דעם פולן בטחון בה׳, אז „הקב״ה ימציא לו לפרוע“ און ער זעט ווי דער אויבערשטער בענטשט זיין „טירחא“ פון „לוו עלי“ (דורך דער „כלי“ — די „חפצים“) ניט ע״פ דרכי הטבע — איז אויך זיין עסק בששת ימי החול אין אן אופן וואס ער אנערקענט, אז די פרנסה וואס ער באקומט דורך זיין אויסהארעווען א כלי אין טבע, איז עס אין דער אמת׳ן אן ענין פון „אני פורע“ — דער אויבערשטער איז אים ממציא (בדרך מציאה) זיין פרנסה אין אן אופן למעלה מדרך הטבע (מער ניט וואס די ברכה שלמעלה מהטבע איז אנ־געטאן אין א לבוש פון טבע⁵⁵).\nיו״ד. לויט דעם קען מען מסביר זיין דאס וואס עס איז פארשטאנדיק פון זהר⁵⁶ אויפן פסוק „אל יותר ממנו עד בקר“, אז אלע ששת ימי השבוע ווערן געבענטשט מיט מן פון שבת „בגין דלא יהיב ולא יוזיף יומא דא לחברי׳“.\nולכאורה: וואס איז די שייכות צווישן די ביידע ענינים, אז וויבאלד די השפעת המן איז בשבת, דעריבער טאר מען ניט איבערלאזן פון איין טאג אויפן צווייטן⁵⁷?\nוע״פ הנ״ל איז דאס מובן: דאס וואס די ברכה מלמעלה אויף השפעת המן ווערט אויפגעטאן בשבת, איז ווייל ענינו פון מן איז א השפעה פון אויבערשטן וואס איז ניט מלובש אין די כלים ולבושים פון טבע, פונקט ווי דאס איז ענינו פון שבת, כנ״ל בארוכה (ובמילא איז אויך זמנו למעלה כפשוטו אויך בשבת).\nאון דעריבער דארף דאס זיין באופן כזה אויך ווען די השפעת המן קומט אראפ למטה: אין דער השפעה דארף ניט זיין אריינגעמישט די חשבונות פון דעם מענטשן ע״פ טבע, וואס דריקט זיך אויס אין דעם וואס מ׳לאזט איבער פון איין טאג אויפן צווייטן.\nיא. אעפ״כ איז בשבת געווען די ברכה והשפעת המן בלויז למעלה, משא״כ למטה איז לא ירד המן — ווארום דאס וואס מען געפינט ביי מן דעם ענין פון „מטר“ (ניט ווי „טל“), אז עס איז פארבונדן מיטן מקבל (כנ״ל דער חילוק פון צדיקים, בינונים כו׳), איז דאס ווי דער מן איז „יורד“ ממדריגתו און ווערט נשפע למטה; אבער ווי דער ענין פון מן איז „במקומו“ (בבחי׳ שבת) איז ער אינגאנצן העכער פון שייכות מיט וועלכער עס איז פעולה פון מקבל.",[["","","הנ״ל). ועפ״ז יובן המשך הגמרא „ואמר ר׳ יוחנן משום ר״א בר״ש הרוצה שיתקיימו נכסיו כו׳“, שאי״ז רק שמביא אגב גררא עוד מאמר מר״י משום ר״א בר״ש, כ״א המשך בגוף הענין, שגם „לוו עלי“ מדובר בשיש לו נכסים כו׳ עסק. אבל ע״פ הנ״ל בפנים י״ל דגם לדעת אדה״ז „אני פורע“ הוא ע״י „ברכה במעשה ידיכם“ (איזה שיהי׳) אלא שבא לא לפי״ע „המעשה ידיכם“ עד שנראה במוחש ש„ואני פורע“. וגם עפ״ז המשך הגמרא „הרוצה שיתקיימו נכסיו כו׳“ הוא בגוף הענין. אלא שמתחלה מביא הגמרא „הרוצה שיתקיימו נכסיו כו׳“ שעי״ז מובן ש„ואני פורע“ הוא כאשר יש לו חפצים כו׳, ואח״כ „כל מזונותיו של אדם קצובין לו כו׳“, שעי״ז מובן שבאמת „(האמינו בי) ואני פורע“. וראה לשון הטור שהובא בהערה 51. ועי׳ או״ת שם."],["55","55","ראה לעיל הערה 33. וראה אוה״ת שבהערה 35 בביאור מחלוקת שמאי והלל ביצה שם, ושם: לעשות הגילוי ביחו״ת כמו ביחו״ע, וע״פ הנ״ל יומתק ביותר ההמשך בביצה שם דהלל ושמאי ללפנ״ז."],["56","56","הנ״ל הערה 5."],["57","57","ראה גם המשך תער״ב ח״ב ע׳ איפו."]]],[1300161197,"ועד״ז בשבת כפשוטו: דאס וואס מ׳דארף האבן א משכון כדי עס זאל זיין „לוו עלי כו׳ והאמינו בי ואני פורע“ איז דאס פאר שבת (אויף די צרכי השבת), אבער בשבת עצמו דארף זיין „כל מלאכתו עשוי׳“, און אפי׳ „שלא להרהר כלל בעסקיו“.\nאון דעריבער איז דער ענין פון „ולא יצאו בשבת ללקוט“ איינע פון די „מצות התלויות בו“, וועלכע דריקט אויס דעם טעם ותוכן פון ירידת המן — ווארום ביום השבת איז אויך דא למטה מאיר די בחי׳ פון „מן“ ווי דאס איז „במקומו“, און דעריבער דארף זיך אנהערן בא יעדן איינעם אז אין דעם קען ניט זיין קיין שום אריינמישונג פון דעם מענטשן, אפילו ניט א תנועה פון „קבלה“ (ליקוט) ווי בששת ימי החול — „ולא יצאו בשבת ללקוט“.\n(משיחות (ומאמר*) ט״ו בשבט תשל״ז, ש״פ בראשית תשל״ג)",[["","","*) נדפס בשלימותו בסה״מ מלוקט ח״א ע׳ רלה. המו״ל."]]],[1300161198,"<h3>בשלח ד</h3>\nא. ביי עירוב תבשילין איז דער דין<sup data-n=\"1\">1</sup>, אז באלד נאכדעם ווי מ'ענדיקט צו־גרייטן אלע צרכי שבת מעג מען אויפ־עסן דעם עירוב (נאך אינעם טאג פון יו\"ט) — שטייט אבער אין מהרי\"ל<sup data-n=\"2\">2</sup>, אז ער האט איינגעפירט „להניח ככר העירוב (תבשילין) ללחם משנה בליל שבת ובשחריתו ובסעודה שלישית הי' בוצע עליו\". און אזוי ברענגט אויך דער מהרש\"ל<sup data-n=\"3\">3</sup>: „(ומאחר שצ\"ל העירוב קיים אין ראוי לאכלה עד ליל שבת, ומ\"מ) הי' מנהג מהר\"ם להניחה הככר תחת הלחם משנה בליל שבת ולמחרתו ובסעודה ג' הי' בוצע עליו מאחר דאיתעביד בי' מצוה א' ראוי לעשות עליו מצות אחרות\".\nאויך דער אלטער רבי ברענגט אראפ אט דעם מנהג אין שו\"ע<sup data-n=\"4\">4</sup>, וז\"ל: „לכתחילה צריך שיהיו הפת והתבשיל שמורים אצלו עד לאחר שתיקן כל צרכי שבת .. ומ\"מ מצוה מן המובחר להמתין מלאכול הפת של ע\"ת עד א' מג' סעודות השבת כדי לבצוע עליו .. שכל דבר שנעשה בו מצוה אחת ראוי לעשות בו מצוה אחרת ויש נוהגין שלא לבצוע עליו עד סעודה ג' של שבת כדי לעשות בו מצות הרבה שמניחין זה הככר ללחם משנה בסעודה הראשונה ובסעודה שני' של שבת ובסעודה שלישית בוצעין עליו\".\nב. דער מקור פון דער סברא — אז וויבאלד מיט דער זאך איז געטאן געווארן איין מצוה (עירוב תבשילין), איז ראוי צו טאן דערמיט נאך א מצוה (לחם משנה וסעודת שבת) — איז אין גמרא<sup data-n=\"5\">5</sup> ביי עירובי חצירות<sup data-n=\"6\">6</sup>: „רב אמי ורב אסי כי הוה מתרמי להו ריפתא דערובא („שערבו בו אתמול ערובי חצירות\"<sup data-n=\"7\">7</sup>) מברכין עלי' המוציא לחם מן הארץ אמרי הואיל ואתעביד בי' מצוה חדא נעביד בי' מצוה אחריתי\".\nאון אויך ביי עירובי חצרות שטייט אין מהרי\"ל<sup data-n=\"8\">8</sup>: „ובליל שבת ובשחריתו אני מניחו ללחם משנה .. ואמר דגם בליל שבת יכולין לאוכלו .. רק חביב עליו להרבות בו מצוה\", „בסעודה שלישית בשבת .. הי' בוצע על ככר .. אותו שעירב בו עירובי חצרות כו'\"<sup data-n=\"9\">9</sup>: און אזוי ברענגט דער מהרש\"ל<sup data-n=\"10\">10</sup>: „וכן נהגו בעירובי חצרות\" (אז מ'עסט עס ערשט ביי דער סעודה שלישית, נאכדעם ווי מ'לייגט עס צו לחם משנה ביי די צווייי ערשטע סעודות, ווי ביי עירוב תבשילין).\nאבער ביי דעם דין ברענגט אראפ",[["1","1","ביצה יז, ב. רמב\"ם הל' יו\"ט פ\"ו ה\"ה. טושו\"ע אר\"ח סתקכ\"ז סט\"ז. שו\"ע אדה\"ז שם סכ\"ה."],["2","2","הל' עירובי תבשילין בסופן. הובא בבאר היטב סתקכ\"ז סק\"ב."],["3","3","יש\"ש ביצה פ\"ב סו\"ס יח. הובא בב\"ח סתקכ\"ז שם. ט\"ז שם סקי\"ד. מג\"א שם סקט\"ו."],["4","4","דלעיל הערה 1."],["5","5","ברכות לט, סע\"ב. שבת קיז, סע\"ב (בשינוי לשון קצת)."],["6","6","ולפי' א' ברא\"ה ברכות שם — עירובי תחומין. אבל במאירי ברכות ושבת שם מפרשו על עירוב תבשילין (ובברכות שם שולל הפי' דקאי על עירובי תחומין או עירובי חצירות „אא\"כ נפרש בה שהי' בוצע בה למחר\". וראה רא\"ה שם. חי' הר\"ן שבת שם). וכ\"ה באוצר הגאונים שבת שם (מרב יוסף גאון)."],["7","7","פרש\"י ברכות שם."],["8","8","הל' עירובי חצירות."],["9","9","שם הל' שבת."],["10","10","ביצה שם. הובא בב\"ח וט\"ז שם."]]],[1300161199,"דער אלטער רבי<sup data-n=\"11\">11</sup> נאר דעם פסק הלכה (פון רמ\"א<sup data-n=\"12\">12</sup>): „ויש לבצוע עליו בשבת שחרית<sup data-n=\"13\">13</sup> .. דהואיל ונעשית בו מצוה אחת יש לעשות בו ג\"כ מצוה אחרת\" — און ער ברענגט ניט אראפ דעם מנהג הנ\"ל צו בוצע זיין אויפן עירוב ערשט ביי דער סעודה שלישית (כדי „להרבות בו מצוה\").\nדארף מען פארשטיין: וויבאלד אז דער מהרי\"ל און דער מהרש\"ל דער־מאנען דעם מנהג סיי ביי עירוב תבשילין און סיי ביי עירובי חצרות — היינט פארואס ברענגט דער אלטער רבי דעם מנהג נאר ביי עירוב תבשילין<sup data-n=\"14\">14</sup> (ובפרט, אז די סברא „הואיל ואתעביד בי' מצוה חדא נעביד בי' מצוה אחריתי\" האט איר מקור ביי עירובי חצרות<sup data-n=\"15\">15</sup>, כנ\"ל)?\nג. וועט מען דאס פארשטיין נאכדעם ווי מ'וועט באווארענען א שוועריקייט אין דעם עצם מנהג צו בוצע זיין אויפן עירוב (תבשילין) ביי „סעודה ג' של שבת כדי לעשות בו מצות הרבה כו'\":\nאין די ערשטע צוויי סעודות פון שבת איז דאך דא א גרעסערע חשיבות ווי אין דער סעודה שלישית<sup data-n=\"16\">16</sup>: לויט כמה דיעות דארף מען ניט האבן קיין לחם משנה ביי דער סעודה שלישית; נאכ־מער: אנדערע האלטן אז די סעודה שלישית דארף בכלל ניט האבן קיין פת (און ס'איז גענוג א מאכל מחמשת המינים כו'), ביז אז עס זיינען פאראן דיעות אז מ'איז יוצא די סעודה מיט פירות וכו' —\nאיז ניט גלאטיק: פארוואס זאל מען אפלייגן צו „בוצע\" זיין אויפן ככר העירוב ביז דער סעודה שלישית ווען די אכילה (פון פת דוקא) איז ניט אזוי חשוב אדער אינגאנצן רשות — ס'וואלט דאך לכאורה מער מתאים געווען צו „בוצע\" זיין אויפן עירוב בסעודת שחרית, וואס דעמאלט וואלט מען מיטן עירוב געטאן ניט בלויז (צוויי מאל) די מצוה פון לחם משנה, נאר מ'וואלט אויך פארבונדן אכילת העירוב גופא מיט דער מצוה וחיוב פון סעודת שבת (א סעודה וואס מ'איז לכו\"ע מחויב צו עסן פת<sup data-n=\"17\">17</sup>) ?\nמ'קען ניט זאגן, אז דאס איז צוליב דעם וואס דעמאלט טוט מען ביים ככר א דריטע מצוה — ברכת המוציא ביי דער סעודה שלישית — ווארום וויבאלד אז ביי דער סעודה שלישית איז (לכמה דיעות) ניטא דער חיוב פון פת, איז אין דעם בלויז דא ברכת המוציא אלס ברכת הנהנין — איז דאך דאס פאראן אויך ווען מ'איז בוצע ביי דער סעודת שחרית (נוסף אויף דער מצוה פון לחם משנה).",[["11","11","או\"ח סי' שצג ס\"ג."],["12","12","סשצ\"ד ס\"ב. ממנהגים מהר\"א טירנא (הובא בדרכי משה שם). ובמנהגים הנ\"ל לפנינו הובא זה ב„דין עירוב תבשילין\" (ובעירובי חצרות כ' „וישמור העירוב כל השנה\")."],["13","13","בחצע\"ג מוסיף „או בסעודת הלילה אם סועד משחשיכה ודאי\". והוא כמנהג מהר\"ם שהובא בב\"י סשצ\"ד. דרכי משה (ורמ\"א) שם. וכן מפורש בירושלמי עירובין (פ\"ו סה\"ז) „מברך עלוי בלילי שובתא כו'\". וכ\"ה במאירי ואוצה\"ג שבת שם (לעניין עירוב תבשילין — כנ\"ל הערה 6). ובביאור הגר\"א שם ד„במנהגים חששו בערבית שלא יאכל קודם חשיכה\". וראה לקמן הערה 41."],["14","14","ועד\"ז במג\"א (סתקכ\"ז שם) שמביא מיש\"ש המנהג בע\"ת, אבל משמיט הסיום שביש\"ש „וכן נהגו בע\"ח\", ורק מסיים „עסי' שצ\"ד\"."],["15","15","אבל ראה לעיל הערה 6."],["16","16","בהבא לקמן — ראה טושו\"ע או\"ח סו\"ס רצא ונ\"כ שם. שו\"ע אדה\"ז שם ס\"ז."],["17","17","ראה טושו\"ע או\"ח סו\"ס רעד. שו\"ע אדה\"ז שם ס\"ה. פסקי דינים להצ\"צ ח\"ב יט, ג [שנז, ג]. אבל להעיר משו\"ע אדה\"ז או\"ח סקפ\"ח ס\"י בהגה\"ה."]]],[1300161200,"ד. דער ביאור אין דעם:\nאין גמרא<sup data-n=\"18\">18</sup> ווערן געבראכט צוויי טעמים<sup data-n=\"19\">19</sup> אויף דער תקנה פון עירוב תבשילין: (א) רבא זאגט „כדי שיברור מנה יפה לשבת ומנה יפה ליו\"ט\", ופרש\"י: „מתוך שמערב זוכר את השבת ואינה מכלה את הכל ליו\"ט וכו'\" — וואס לפי זה איז די תקנה פון עירוב תבשילין „כדי להרבות בכבוד שבת\"<sup data-n=\"20\">20</sup>. (ב) „רב אשי אמר כדי שיאמרו אין אופין מיו\"ט לשבת ק\"ו מיו\"ט לחול\" — און לויט אים איז דער טעם „כדי להרבות בכבוד יו\"ט\"<sup data-n=\"20\">20</sup>.\nפון די נפק\"מ להלכה צווישן די צוויי טעמים זאגט דער ראש<sup data-n=\"21\">21</sup>: לויטן טעם פון רבא „כדי שיברור מנה יפה לשבת\" מוז מען מאכן דעם עירוב דוקא ערב יו\"ט, אינעם טאג ווען ער גרייט די מאכלים לכבוד יו\"ט און דער עירוב וועט אים דערמאנען אין די צרכי שבת (ווייל אויב מ'וועט עס מאכן אין א פריערדיקן טאג, וועט עס אים ניט גענוג העלפן צו געדענקן זיינע צרכי שבת אינעם טאג פון ערב יו\"ט<sup data-n=\"22\">22</sup>); משא\"כ לויטן טעם פון רב אשי „כדי שיאמרו אין אופין מיו\"ט לחול\" איז גענוג בלויז דאס וואס דער עירוב איז „קיים\" ערב יו\"ט, אבער עשיית העירוב קען זיין אויך פאר ערב יו\"ט.\nדער אלטער רבי ברענגט אראפ ביידע טעמים אין שו\"ע<sup data-n=\"23\">23</sup> (נאר אין א פארקערטן סדר<sup data-n=\"24\">24</sup> — „א' כדי להרבות בכבוד יו\"ט כו' הב' כדי להרבות בכבוד שבת כו'\"), מיט דער אויבנדערמאנטער נפק\"מ צווישן זיי להלכה, און פירט אויס: „לענין מעשה אין לערב לכתחלה אלא בעי\"ט ממש לי\"ט זה בלבד כמו שנתבאר לפי טעם הב' אבל בדיעבד שכבר עירב ימים רבים קודם יו\"ט ובעיו\"ט ממש שכח כו' ולא עירב מותר לסמוך על עירובו כו'\" — ד.ה. אז לכתחילה דארף מען זיך נוהג זיין צו באווארענען (אויך) דעם טעם „כדי שיברור מנה יפה לשבת כו'\"<sup data-n=\"25\">25</sup>.\nה. דער חילוק צווישן די צוויי טעמים איז ניט נאר צי די תקנה איז צוליב יו\"ט אדער צוליב שבת, נאר נאכ־מער — אין תוכן התקנה:\nלויטן טעם פון רב אשי, איז דער תוכן התקנה שלילה — און אין צוויי פרטים: (א) צו באווארענען אן ענין (איסור) שלילי — מ'זאל ניט נכשל ווערן אינעם איסור פון בישול ביו\"ט לצורך חול: און דערפאר (ב) קומט די תקנה צו (שולל זיין, צו) אסר\"ן דעם בישול מיו\"ט לשבת „אא\"כ התחיל לבשל תבשיל אחד מעי\"ט\"<sup data-n=\"26\">26</sup>;\nמשא\"כ לויטן טעם פון רבא, איז תוכן התקנה חיוב — און אין די ביידע פרטים הנ\"ל: (א) דורך דער תקנה ווערט באווארנט אז די הכנה צו שבת זאל זיין כדבעי (מען זאל בורר זיין „מנה יפה לשבת\"); ובמילא (ב) אז דער עיקר",[["18","18","ביצה רפ\"ב (טו, ב)."],["19","19","מסגנון לשון אדה\"ז (סתקכ\"ז ס\"ב) „ומפני ב' דברים תיקנו חכמים דבר זה כו'\" משמע לכאורה, שאי\"ז פלוגתא כ\"א ב' טעמים. וראה פנ\"י וצל\"ח ביצה שם."],["20","20","ל' אדה\"ז שם. וראה רש\"י ביצה שם ד\"ה רב אשי."],["21","21","ביצה שם."],["22","22","וראה הגמ\"יי הל' יו\"ט פ\"ו סק\"ב. ב\"י סתקכ\"ז ד\"ה ומ\"ש ויכול להניח."],["23","23","שם."],["24","24","ראה לקמן סי\"א הביאור (עפ\"י פנימיות הענינים)."],["25","25","כבשו\"ע סתקכ\"ז סי\"ד. ובמג\"א סוסק\"ג."],["26","26","ל' אדה\"ז שם."]]],[1300161201,"התקנה איז דאס אוועקלייגן דעם עירוב וואס דערמאנט דעם חיוב צו מכין זיין די צרכי שבת (און אדרבה: דער איסור פון בישול מיו\"ט לשבת סיידן מ'מאכט פריער דעם עירוב, איז נאר צו פאר־שטארקן די תקנה פון הכנה לשבת כדבעי<sup data-n=\"27\">27</sup>).\nו. עפ\"ז וועט זיין פארשטאנדיק נאך אן ענין: די גמרא ברענגט צוויי אסמכתות פון פסוק אויפן דין פון עירוב תבשילין: (א) „אמר שמואל דאמר קרא<sup data-n=\"28\">28</sup> זכור את יום השבת לקדשו זכרהו מאחר שבא להשכיחו\". (ב) „ותנא מייתי לה מהכא את אשר תאפו אפו ואת אשר תבשלו בשלו (וואס שטייט בפרשתנו<sup data-n=\"29\">29</sup>) מכאן אר\"א אין אופין אלא על האפוי וכו' מכאן סמכו חכמים לעירובי תבשילין מן התורה\".\nאויף „זכרהו מאחר שבא להשכיחו\" איז רש\"י מפרש: „כשבא יו\"ט בערב שבת קרוב שבת להשתכח מחמת יו\"ט שמרבה בסעודת היום ואינו מניח לשבת כדי כבודו והזהירך הכתוב לזכרו וכשמערב ערובי תבשילין נמצא שזוכרו וכו'\" — וואס פון פירוש רש\"י איז מובן, אז די אסמכתא פון פסוק „זכור את יום השבת לקדשו\" — „זכרהו מאחר שבא להשכיחו\" — איז (נאר) לויטן טעם פון רבא<sup data-n=\"30\">30</sup>.\nולכאורה איז ניט מובן: די גמרא ברענגט ביידע טעמים (פון רבא און רב אשי) בהמשך צו דער אסמכתא פון פסוק „זכור את יום השבת לקדשו\" (און די צווייטע אסמכתא ברענגט די גמרא ערשט נאכן אראפברענגען ביידע טעמים, פון רבא און רב אשי) — היינט פארוואס נעמט אן רש\"י אז די אסמכתא פון פסוק „זכור את יום השבת לקדשו\" איז לויטן טעם פון רבא<sup data-n=\"31\">31</sup> ?\nועפ\"י הנ\"ל איז מובן: דער לימוד פון דער צווייטער אסמכתא דריקט אויס די תקנה אין אן אופן שלילי — „אין אופין אלא על האפוי כו'\": מ'האט גע'אסרט דעם בישול יו\"ט סיידן עס איז דא „האפוי\" „בחמישי בשבת\"<sup data-n=\"32\">32</sup>: משא\"כ דער לימוד פון פסוק „זכור את יום השבת לקדשו\" דריקט עס אויס אין אן אופן חיובי — עס מוז זיין דער „זכרהו\".\nאון דריבער נעמט אן רש\"י אז די אסמכתא פון „זכור את יום השבת לקדשו\" איז לויטן טעם פון רבא אז די תקנה פון עירוב תבשילין איז אן ענין חיובי — „כדי שיברור מנה יפה לשבת כו'\".\nז. עפ\"י הנ\"ל — אז לויט רבא איז די תקנה פון עירוב תבשילין אן ענין חיובי פון „זכרהו מאחר שבא להשכיחו\" — קען מען זאגן, אז עס האט אן ארט (לויט",[["27","27","וראה ביצה שם: „אלא לרבא .. אפי' ביו\"ט נמי .. גזירה שמא יפשע\"."],["28","28","יתרו כ, ח."],["29","29","טז, כג."],["30","30","כמ\"ש בשיטת ריב\"ב לרי\"ף שם. מהרש\"א ומהר\"ם שי\"ף שם. אבל בחי' המאירי מפרש הסוגיא כפרש\"י („כך נראה פי' סוגיא זו מתוך פי' רש\"י\") וכותב בפירוש (ועד\"ז בבית הבחירה) „והני אמוראי כולהו מיהא ס\"ל דעירובי תבשילין אסמכתא דילי' מזכור וכו'\" (וראה הערה הבאה). — אבל גם לפירושו, מזה שרש\"י (ועד\"ז במאירי) מפרש על „זכרהו וכו'\" — „קרוב שבת להשתכח מחמת יו\"ט שמרבה בסעודת היום ואינו מניח לשבת כדי כבודו כו'\", מובן, שפירושו הפשוט בהאסמכתא הוא כטעמו דרבא."],["31","31","וראה ר\"ן דמפרשו אליבא דר\"א („זכרהו מיו\"ט שבא לאסור עליך שלא תבשל לו וכו'\"). וברי\"ף ורא\"ש מביא רק האסמכתא ד„זכור וכו'\" ומ\"מ מביא ב' הטעמים דרבא ור\"א. וראה מאירי שבהערה הקודמת. ובצל\"ח שם: „דרבא מפרש כפרש\"י ור\"א מפרש כפירוש הר\"ן וכו'\"."],["32","32","ל' רש\"י שם ד\"ה אלא על האפוי."]]],[1300161202,"דעם טעם) צו האלטן גאנץ דעם עירוב תבשילין אויך אינעם טאג פון שבת גופא:\nווארום הגם אז ווען מ'ענדיקט צו־גרייטן אלע צרכי שבת איז מען שוין באווארנט פונעם חשש פון „קרוב שבת להשתכח .. ואינו מניח לשבת כדי כבודו\" „ואינו מכלה את הכל ליו\"ט כו'\" (און מהאי טעמא מעג מען שוין דאן עסן דעם עירוב<sup data-n=\"33\">33</sup>), פונדעסטוועגן, ווייבאלד דער עירוב באווארנט דעם (ענין חיובי) „זכרהו\", איז מסתבר אז דער זכרון מצד העירוב זאל דויערן אויך אין שבת גופא — ווי דער פשטות המכוון פון „זכור את יום השבת לקדשו\", אז מ'דארף געדענקן שבת אינעם טאג פון שבת גופא<sup data-n=\"34\">34</sup>.\nבסגנון אחר: ווייבאלד דאס איז א שבת „שבא להשכיחו\", איז דער „זכור את יום השבת לקדשו\" פון דעם שבת מיט א תוספת הדגשה (אז דאס זאל אויך זיין — דורכן עירוב תבשילין — בשבת).\nוי\"ל אז דאס איז דער טעם וואס שטייט אין מהרי\"ל (ביי עירוב תבשילין) „וטוב להותיר מי\"ט לשבת\" (צו האלטן דעם עירוב „לשבת\") — וואס פון סתימת לשונו איז משמע אז דאס איז ניט (נאר) מצד דעם טעם פון „הואיל ואתעביד בי' מצוה חדא כו'\"<sup data-n=\"35\">35</sup>; און נאך מער איז עס מובן ממש\"כ במנהגים (פון מהר\"א טירנא<sup data-n=\"36\">36</sup>) „וישמור העירוב עד שיכנס השבת\" — ווייל לויט טעמו של רבא איז דאס האלטן דעם עירוב אויף\nשבת א הוספה אין דעם „זכרהו\" פון עירוב תבשילין<sup data-n=\"37\">37</sup>.\nח. דערמיט איז אויך פארשטאנדיק דער דיוק הלשון פון אלטן רבי\"ן אין שו\"ע:\nביי עירובי חצרות שרייבט ער: „העירוב אצ\"ל קיים אלא ביה\"ש וכו' ויש לבצוע עליו בשבת שחרית .. דהואיל ונעשית בו מצוה אחת יש לעשות בו ג\"כ מצוה אחרת\" — וואס פון דעם המשך הלשון איז מובן, אז דער הידור פון „לבצוע עליו בשבת שחרית\" האט ניט קיין שייכות צום ענין וגדר פון עירובי חצרות, נאר ס'איז א זייטיקער ענין אין דער זאך, וואס מ'האט דערמיט געטאן א מצוה („הואיל ונעשית בו מצוה כו'\").\nמשא\"כ דא ביי עירוב תבשילין איז ער מדייק: „לכתחלה צריך שיהיו הפת והתבשיל שמורים אצלו עד לאחר שתיקן כל צרכי שבת שאז רשאי לאכלם מעיקר הדין ומ\"מ מצוה מן המובחר להמתין מלאכול הפת של ע\"ת עד אחד מג' סעודות השבת כדי לבצוע עליו .. שכל דבר שנעשה בו מצוה אחת ראוי לעשות בו מצוה אחרת כו'\" — וואס פון דעם דיוק וקישור הלשון איז מובן, אז די הנהגה פון „להמתין מלאכול הפת עד א' מג' סעודות השבת כו'\" איז (ניט נאר א זייטיקער ענין, כנ\"ל, נאר אויך) א „מובחר\" אין דער „מצוה\", אין דעם ענין פון עירוב תבשילין.\nועפ\"י הנ\"ל איז עס מובן, ווייל דורכדעם וואס מ'נוצט דעם עירוב בפועל פאר צרכי וסעודת שבת איז מען מקיים דעם „זכרהו\" אין אופן פון „מצוה מן",[["33","33","נסמן בתחילת השיחה."],["34","34","ולהעיר מפרש\"י ביצה שם ד\"ה מ\"ט: וכי אתא קרא לקדוש היום כו'."],["35","35","כי רק אח\"כ ממשיך „ורשאי לאכול העירוב בליל שבת לבצוע כו' אך הנהיג מהרי\"ל כו'\", עיי\"ש."],["36","36","„דין עירוב תבשילין\"."],["37","37","וראה לשון אדה\"ז בסידורו (סדר עירוב תבשילין): יקח בעיו\"ט הפת משבח כו'."]]],[1300161203,"המובחר\": און דערפאר זאגט דער אלטער רבי „ומ\"מ מצוה מן המובחר להמתין כו'\", ווייל ער פסק'נט דאך אז לכתחילה דארף מען זיך נוהג זיין (אויך) ווי דער צווייטער טעם („להרבות בכבוד שבת\"<sup data-n=\"38\">38</sup>, כנ\"ל ס\"ד.\nט. לפי ביאור הנ\"ל וועט אויך זיין פארשטאנדיק פארוואס דער אלטער רבי ברענגט די הנהגה פון „בוצע\" זיין אויפן עירוב ביי דער סעודה שלישית נאר ביי עירוב תבשילין און ניט ביי עירובי חצרות:\nווי ס'איז מוסבר לעיל, אז לויט דעם טעם אז עירוב תבשילין איז „כדי להרבות בכבוד שבת\", איז אויך דאס נוצן דעם עירוב לצרכי שבת אן ענין פון „זכרהו\" — קומט אויס, אז וואס מער און לענגער מ'נוצט דעם עירוב ביי די סעודות שבת (ביי די ערשטע צוויי — ללחם משנה, און ביי דער דריטער — „לבצוע עליו\"), איז אלץ מער הדגשה ויתרון אין דעם „זכרהו\": יעדער מאל וואס מ'עסט די מאכלי שבת וואס מ'האט צוגעגרייט יו\"ט (דורכן עירוב), איז מען מוסיף אין דעם „זכרהו\" דורך משתף זיין צו דער סעודה דעם עירוב תבשילין.\nאין אנדערע ווערטער: ווען מ'האלט דעם עירוב ביי יעדער סעודה, אויך ביי דער לעצטער סעודה — דער סעודה שלישית, פארבינדט מען דעם „זכרהו\" פון דעם עירוב תבשילין מיט „כל צרכי שבת\" ביז די סאמע לעצטע צרכים, אויך מיט דער לעצטער סעודה.\nבמה דברים אמורים — ביי עירוב תבשילין, וואס מצד דעם עצם גדר פון („זכרהו\" ביי) עירוב תבשילין איז דא א סברא צו האלטן דעם עירוב ביז דער סעודה שלישית<sup data-n=\"39\">39</sup>:\nמשא\"כ ביי עירובי חצרות וואו ס'איז ניטא אט דער טעם וגדר — איז (לדעת אדמו\"ר הזקן<sup data-n=\"40\">40</sup>) ניטא קיין סברא צו לאזן דעם עירוב אויף סעודה שלישית, ווייל אדרבה, ס'איז בעסער „לבצוע עליו בשבת שחרית\" ווען מ'האט דערביי דעם קיום מצות אכילת סעודת שבת — א סעודה וואס מוז האבן פת לכו\"ע, כנ\"ל ס\"ג<sup data-n=\"41\">41</sup>.",[["38","38","אלא שמ\"מ, גם לטעמו דרבא אי\"ז חיוב כיון שגם אם לא יאכלוהו בשבת אין מקום להחשש ד„להשכיחו\", כנ\"ל בפנים."],["39","39","אלא מכיון שסברא זו לא נזכרה בגמ' וראשונים כו' לא כתב אדה\"ז בפירוש כ\"א טעם המפורש „לעשות בו מצות הרבה כו'\" — ע\"ד משנ\"ת בלקו\"ש ח\"ד (ע' 1126 ואילך) שכנראה אדה\"ז בשו\"ע שלו — ע\"ד הרמב\"ם בספרו — אינו מביא דינים מחודשים כו' — רק רמזה בסגנון לשונו, שאכילת (והשתמשות) העירוב בסעודת שבת היא גם גדר בע\"ת גופא (כנ\"ל ס\"ח)."],["40","40","וי\"ל שטעם המהרי\"ל הוא (לא מפני שפליג על סברא זו — ראה לעיל בפנים ס\"ז בדברי המהרי\"ל — כ\"א) מפני שס\"ל שברכת המוציא נוספת דסעודה שלישית (עם אכילת פת אז) מכריעה המעלה דאכילת פת דסעודת שבת (דלא כנ\"ל ס\"ג), כיון שגם לדעת אלו שאין חיוב פת בסעודה שלישית, באם אכיל אז פת — מצוה קעביד. ועד\"ז כשנוסף על ג' התפלות מתפלל כל היום (ברכות כא, א), נתינת צדקה לאחרי שכבר נתן חומש, ועוד כיו\"ב. באופן אחר: שני ענינים בזה: ענין וחיוב סעודות שבת (ב, ג, או ד (שבת קיז, סע\"ב)), ענין וחיוב עונג שבת (בדברים ו)במאכלים שהם חשובים עונג ואין בזה שיעור דאפילו „דבר מועט ולכבוד שבת עשאו\", ולאידך גיסא „יש להרבות כו' כפי יכולתם והשגת ידם. וכל המרבה כו' ובתיקון מאכלים רבים וטובים ה\"ז משובח\" (שבת קיח, ב. רמב\"ם הל' שבת פ\"ל ה\"ז. שו\"ע אדה\"ז ר\"ס רמב)."],["41","41","אלא שצ\"ע למה מוסיף אדה\"ז בחצע\"ג (ראה לעיל הערה 13) „או בסעודת הלילה אם סועד משחשכה ודאי\" — דלכאורה טוב יותר להמתין עד סעודת שחרית דאז עושים בו „מצות הרבה\" (ב\"פ"]]],[1300161204,"יו\"ד. די הוראה פון דעם ענין הנ\"ל אין עבודת ה':\nדער חילוק צווישן שבת און יו\"ט איז מבואר אין זוהר<sup data-n=\"42\">42</sup>, אז שבת ווערט אנגע־רופן „קדש\"<sup data-n=\"43\">43</sup> און יו\"ט „מקראי קדש\"<sup data-n=\"44\">44</sup>, ווייל יו\"ט איז מען בלויז „קורא\", „מזמין\"<sup data-n=\"45\">45</sup> די בחי' פון „קודש\" (ד.ה. מען איז מזמין דעם „קודש\" אין אן „ארט\" (זמן) פון חול), משא\"כ שבת איז די בחי' פון קדש אליין<sup data-n=\"46\">46</sup>.\nד.ה.47: זמן היו\"ט מצ\"ע — איז שייך עניני חול — און די עבודה פון (מועדי ה' אשר תקראו אותם, אתם<sup data-n=\"48\">48</sup> — אידן דוקא) באשטייט אין „מזמין\" זיין אין דעם די בחי' פון קדש, אז די אכילה וכו' זאל זיין אין אן אופן פון „קדש\" — „צדיק אוכל לשובע נפשו\"<sup data-n=\"49\">49</sup>; ולכן שבת\nוואס איז מיקדשא וקיימא<sup data-n=\"50\">50</sup> מצ\"ע איז כולו קדש, „אין בו פסולת כלל\"<sup data-n=\"51\">51</sup>. משא\"כ יו\"ט — איז אויב עס פעלט בעבודתו פון דעם אידן (אפילו באם יחיד, אע\"פ וואס דער „תקראו אתם\" (פון בי\"ד) איז געווען בשלמות) איז דא „פרש חגיכם\" („פרש חגיכם קאמר ולא פרש שבתכם\"<sup data-n=\"52\">52</sup> — די עבודה איז אין א טאג וואס מצ\"ע איז ניטא קיין „פרש\" ובמילא נאר „צדיק אוכל לשובע נפשו\").\nוע\"ד דער חילוק צווישן דעם אופן פון מתקן זיין דעם רע, ע\"ד מעדנים „מדברים חריפים או חמוצים רק שהם מתובלים ומתוקנים כו'\"<sup data-n=\"53\">53</sup>, און דעם אופן — אז ס'איז איבערהויפט ניטא קיין רע, ע\"ד מעדנים „ממאכלים ערבים ומתוקים\"<sup data-n=\"53\">53</sup>.\nאון דאס איז דער חילוק (בפנימיות הענינים) צווישן די צוויי טעמים אויף עירוב תבשילין: לויטן טעם אז עס איז „כדי להרבות בכבוד יו\"ט\" איז תוכן התקנה שלילה, און לויטן טעם „להרבות בכבוד שבת\" — חיוב (כנ\"ל ס\"ה בארוכה):\nוויבאלד אז אין דער עבודה פון יו\"ט דארף מען מברר און מתקן זיין עניני (וזמן) חול, איז אויך די תקנה „להרבות",[["","","לחם משנה וסעודת שחרית•). ואולי טעם המנהג „לאכול העירוב משחשיכה מיד\" (מנהג מהר\"ם — נסמן בהערה הנ\"ל) הוא לאשמעינן ד„בבין השמשות סגי\" (ראה ב\"י שבהערה הנ\"ל), ע\"ד מאמר ר' זירא ברכות לח, סע\"א ואילך. ולהעיר ממ\"ש המהרי\"ל (אחי אדה\"ז) בשארית יהודה (חאר\"ח סי' ר. נעתק בהוספות לשו\"ע אדה\"ז או\"ח ח\"א ע' 52 [356]): שמעתי מפי קדשו [רבינו הזקן] פעמים רבות דכל ספק [שבשו\"ע] העמיד בתוך חצע\"ג ודעתו היתה לחזור ולשנות פרק זה לראות אם צדקו דבריו. וראה קונטרס השלחן (להרראי\"ח נאה) מבוא ס\"ח. ואכ\"מ."],["42","42","ח\"ג צד, א."],["43","43","תשא לא, יד."],["44","44","אמור כג, ב, ד."],["45","45","ראה גם זהר שם צג, ב: זמינין דקדש."],["46","46","וראה זהר שם צה, א."],["47","47","בהבא לקמן — ראה תו\"א ר\"פ חיי שרה. סידור ר, ג־ד. רג, ג ואילך. ועוד."],["48","48","ר\"ה כד, א."],["49","49","משלי יג, כה. — בתו\"א וסידור (רג, א ואילך) מבואר ד„צדיק אוכל כו'\" הו\"ע אכילת שבת. אבל בסידור (ר, ג) מובא כתוב זה לענין אכילת יו\"ט, עיי\"ש. וכן משמע גם מזה שיו\"ט נק' „מקראי קדש\". ועייג\"כ אוה\"ת בא ע' שט."],["50","50","ביצה יז, א."],["51","51","ל' ה<a class=\"ft-cite\" href=\"#/read/torah-or/3901370291\" data-slug=\"torah-or\" data-id=\"3901370291\">תו\"א</a> שם. וראה (נוסף על הנסמן בהערה 47): תו\"א בשלח ד\"ה ויאמר משה (סה, סע\"ב ואילך). ד\"ה הנ\"ל סה\"מ הנחות הר\"פ (ע' עד ואילך). סה\"מ תקס\"ח (ע' לב). סהמ\"צ להצ\"צ מצות לא תבערו אש (צ, א ואילך). מצות אכילת ק\"ק (צב, סע\"א ואילך). ד\"ה והוא עומד תרס\"ג. לקוטי לוי\"צ לזח\"ג ע' רג."],["52","52","מלאכי ב, ג. זח\"ב פח, ב."],["53","53","<a class=\"ft-cite\" href=\"#/read/tanya/3401310032\" data-slug=\"tanya\" data-id=\"3401310032\">תניא פכ\"ז</a>. •) ולהעיר ג\"כ דכבוד יום קודם לכבוד לילה — שו\"ע אדה\"ז סרע\"א סוס\"ח. רסרפ\"ט."]]],[1300161205,"בכבוד יו\"ט\" בדוגמא לזה — צו באווא־רענען אן ענין פון (חול —) שלילה; משא\"כ לויטן טעם „להרבות בכבוד שבת\" — וואס שבת איז מצ\"ע מיקדשא וקיימא, העכער פון עניני חול, מצ\"ע איז ניטא וואס צו שולל זיין (סיידן ער בריינגט עס אריין, ר\"ל, ע\"י מעשה שלו — דחילול (גם מל' חול<sup data-n=\"54\">54</sup>) שבת) — איז די זאך פון דער תקנה: להוסיף אור, אויפטאן אן ענין חיובי.\nיא. עפ\"ז קען מען אויך מבאר זיין (עפ\"י פנימיות הענינים), פארוואס דער אלטער רבי ברענגט די צוויי טעמים אין א פארקערטן סדר ווי זיי ווערן געברענגט אין גמרא — פריער דעם טעם „להרבות בכבוד יו\"ט\", און דערנאך — „להרבות בכבוד שבת\":\nהתחלת העבודה (טעם הא') איז די עבודה פון סור מרע (כולל — בזמן דיו\"ט — מחול), „להרבות בכבוד יו\"ט\", און ערשט דערנאך קען מען צוקומען צו דעם העכערן אופן העבודה (טעם הב') „להרבות בכבוד שבת\" — ועשה טוב, כנ\"ל.\nאון דאס איז אויך די הסברה פאר־וואס לכתחילה דארף מען זיך נוהג זיין „לפי טעם הב'\", אבער עס איז ניט לעיכובא, ווי דאס איז לפי טעם הא' (כנ\"ל ס\"ד):\nדאס וואס עס מאנט זיך פון יעדערן ולעיכובא בכל מקום ובכל זמן ובכל ענין איז סור מרע — די עבודה מוז זיין ביי יעדער איינעם; משא\"כ די עבודה פון שלילת מציאות הרע (ניט נאר בנוגע זיין מחדו\"מ בפועל), איז ניט יעדער קען עס אויספירן, און דעריבער איז אין איר\nניטא דער ענין פון לעיכובא. וע\"ד החילוק בין צדיק ובינוני (שכל אדם יכול להיות בינוני<sup data-n=\"55\">55</sup> וע\"ד החילוק דאתכפיא ואתהפכא.\nפונדעסטוועגן דארף מען „לכתחלה\" זיך נוהג זיין „לפי טעם הב'\" — וע\"ד המבואר בכ\"מ אז כדי די עבודה פון אתכפיא זאל זיין כדבעי ובאמיתית, מוז מען האבן אויך די עבודה פון אתהפכא<sup data-n=\"56\">56</sup> (עכ\"פ מזמן לזמן):\nוע\"ד המבואר אין קונטרס עה\"ח<sup data-n=\"57\">57</sup> לגבי דעם ענין יחו\"ע און יחו\"ת [וואס די עבודה שמצד יחו\"ע איז אתהפכא<sup data-n=\"58\">58</sup>, און מצד יחו\"ת — אתכפיא], אז כדי די עבודה פון יחו\"ת זאל זיין כדבעי ובאמיתית, מוז מען האבן דער־צו די עבודה פון יחו\"ע — אפילו די ביי וועלכע די עבודה פון יחו\"ע קען ניט זיין באמיתית אין אן אופן תמידי.\nיב. דערצו איז מען מוסיף נאך אן ענין, אז ניט נאר דארף מען זיך נוהג זיין לכתחילה „לפי טעם הב'\", נאר מ'דארף (עכ\"פ אלס „ויש נוהגין\", וואס ווערט אבער געבראכט אין שו\"ע) נוצן דעם עירוב תבשילין ביי דער סעודה שלישית — וואס אין דעם זיינען דא צוויי קצוות:\nדער עירוב גרייט מען צו ערב יו\"ט, גאר אין תחילת העבודה ווען מ'האלט נאך אפילו פאר דער עבודה פון יו\"ט;",[["54","54","ראב\"ע קדושים יט, ח."],["55","55","ד„מדת הבינוני היא מדת כל אדם ואחרי' כל אדם ימשוך וכו'\" (<a class=\"ft-cite\" href=\"#/read/tanya/3401310019\" data-slug=\"tanya\" data-id=\"3401310019\">תניא רפי\"ד</a>), ועבודת הבינוני היא רק באתכפיא (<a class=\"ft-cite\" href=\"#/read/tanya/3401310032\" data-slug=\"tanya\" data-id=\"3401310032\">תניא פכ\"ז</a>. פי\"ג. ועוד)."],["56","56","נוסף על המבואר ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310019\" data-slug=\"tanya\" data-id=\"3401310019\">תניא פי\"ד</a>: אך אעפ\"כ וכו'."],["57","57","פ\"ז ואילך."],["58","58","וראה קונטרס עה\"ח פ\"ח (ס\"ע 33), דהעבודה דיחו\"ע היא ע\"ד הענין ד„שבת מצוה לענגו באכו\"ש .. וזהו\"ע צדיק אוכל לשובע נפשו\", עיי\"ש."]]],[1300161206,"אבער לאידך, האט יעדער איד דעם כח, שוין בתחילת (וההכשר ל)העבודה, צו גרייטן זיך (ניט נאר צו דרגת שבת בכלל, נאר) אפילו צו דער סעודה שלישית, וואס איז, כידוע<sup data-n=\"59\">59</sup>, די דרגא הכי עליונה אין שבת —\nווארום הגם אז ער האלט נאך גאר בתחילת העבודה, איז אבער דורך דעם וואס ער טראכט און טוט א מעשה וואס איז פארבונדן מיט שבת, ביז — דער\nסעודה שלישית, וועט דאס ביי אים פועל'ן אז די עבודה, בא וועלכע ער האלט, זאל געטאן ווערן כדבעי ובאמיתית, און דערנאך בריינגען צו א נאך העכערע עבודה.\n(משיחת שבת בראשית (התוועדות ב' — המשך לשמח\"ת•) תשח\"י)",[["59","59","ראה סידור סדר סעודת שבת בתחילתו. המשך תרס\"ו בסופו (ע' תקמד ואילך). ובכ\"מ. •) שחל אז ביום ו' עש\"ק. וראה לעיל בפנים השייכות דעירוב תבשילין לסעודה שלישית דוקא. ונת' בארוכה בהתוועדות, שזהו טעם בפשטות להתוועדות בתור המשך לשמח\"ת — בזמן דסעודה שלישית דשבת בראשית הסמוך לשמח\"ת (שחל ביום ועש\"ק)."]]],[1300161207,"<h3>יתרו</h3>\nא. אויפן פסוק „וישמע יתרו כהן מדין גו'\" פרעגן חז\"ל¹: „מה שמועה שמע ובא\", און אין דעם ענטפער אויף דער שאלה זיינען פאראן עטליכע דיעות: איין דיעה זאגט „מלחמת עמלק שמע ובא\", א צווייטע דיעה „מ\"ת שמע ובא\", און די דריטע דיעה „קרי\"ס שמע ובא\".\nאיז ידוע² די קושיא וואס מ'פרעגט אויף דעם: וואס פרעגן חז\"ל „מה שמועה שמע\" און זוכן אן ענטפער אויף דעם, בשעת דער פסוק אליין איז ממשיך (אז געהערט האט ער) „את כל אשר עשה³ אלקים למשה ולישראל עמו כי הוציא ה' את ישראל ממצרים\"⁴?\nנאכמער: דאס וואס חז\"ל זאגן, אז יתרו האט געהערט וועגן „מלחמת עמלק\" אדער וועגן „מ\"ת\" וכו', איז, לכאורה, קשה פון דעם וואס עס שטייט אין פסוק אז געהערט האט ער „את כל אשר עשה גו' כי הוציא גו'\".\nנאך שווערער איז צו פארשטיין, וואס אויך רש\"י — וואס איז לכל לראש מפרש לפי פשוטו של מקרא — א) פרעגט דא, אין זיין פירוש אויפן פסוק, די זעלבע שאלה און ב) אין זיין ענטפער איז ער מחבר צווי (פון די דריי) דיעות: „קרי\"ס ומלחמת עמלק\".\nמוז מען זאגן, אז חז\"ל און רש\"י, מיט זייער שאלה און ענטפערס, זיינען אויסן צו באווארענען אן ענין אין תוכן הכתוב; וואס פאדערט הסברה און וואס איז ניט מוסבר דורך המשך הכתוב „את כל אשר עשה וגו'\". דארף מען פארשטיין: וואס איז דא ניט פארשטאנדיק אין פשט הכתובים⁵?\nנאך דארף מען פארשטיין: דער נאמען יתרו (איינער פון די זיבן נעמען⁶) איז צוגעקומען אין דער צייט ווען ער האט זיך מגייר געווען — „כשנתגייר וקיים המצוות הוסיפו לו אות אחת על שמו\"⁷ — היינט ווי אזוי רופט אים דא דער פסוק מיט אט דעם נאמען („וישמע יתרו\"), ווייבאלד דא רעדט זיך וועגן דעם זמן ווען ער איז נאך געווען „כהן מדין\" — נאך איידער ער האט זיך מגייר געווען⁸?\nב. בכדי דאס אלץ צו פארשטיין דארף מען פריער מבאר זיין א פירוש",[["1","1","מכילתא כאן. זבחים קטז, א. ירושלמי מגילה פ\"א הי\"א. וראה לקמן הערה 75 השינוי' בלשונם."],["2","2","ראה מפרשי רש\"י ריש פרשתנו. חדא\"ג מהרש\"א זבחים שם. כלי יקר כאן. ועוד."],["3","3","ובפרש\"י: בירידת המן ובבאר ובעמלק."],["4","4","ובפרש\"י: זו גדולה על כולם."],["5","5","הכרחו של רש\"י — ע\"ד הפשט — לפרש שדוקא ב' ענינים אלה „שמע ובא\" — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111085\" data-slug=\"likkutei-sichot\" data-id=\"1300111085\">לקו\"ש חי\"א ע' 77</a> הערה 32. וראה לקמן בפנים ס\"ב ובהערה 75."],["6","6","מכילתא ופרש\"י כאן. ופרש\"י שמות ד, יח. שמו\"ר פכ\"ז, ח. תנחומא כאן ד."],["7","7","פרש\"י כאן. עד\"ז בשמו\"ר שם (לפי' הא'). ובמכילתא כאן: שייתר במע\"ט."],["8","8","ודוחק לומר, כמו שכ' אחדים מהמפרשים (ראה רע\"ב, וט\"ז כאן — לענין שם יתר) שהתורה קראו ע\"ש העתיד וכמו בשם הנהר השלישי גו' קדמת אשור (בראשית ב, יד ובפרש\"י), כי (ע\"ד הפשט עכ\"פ) זהו שייך לומר כשאין שם אחר, אבל יתרו הרי הי' לו ז' שמות כו'. ועד\"ז צ\"ל בהכ' שמות ג, א. ד, יח. וראה מפרשי רש\"י כאן. ואכ\"מ."]]],[1300161208,"המשניות פון רמב\"ם, וואס איז זייער תמוה בהשקפה ראשונה.\nדער רמב\"ם⁹ בריינגט דעם מאמר חז\"ל¹⁰ „מיום שחרב ביהמ\"ק אין (לו) להקב\"ה בעולמו אלא ארבע אמות של הלכה בלבד\", און זאגט אז לערנענדיק דעם מאמר רז\"ל כפשוטו קען עס אויסקוקן צו זיין רחוק מאד מן האמת: ווייל צי איז דען „ד' אמות של הלכה\" דער אויסשליסליכער תכלית און אלעס איבעריקע „פארוואָרפן\" („מושלכת אחר גויו\")?\nאון איז מבאר באריכות, אז דער תכלית פון כל עניני העולם איז דער מענטש, און דער תכלית פון א מענטש איז ער זאל צוקומען צו ווערן א איש השלם, און זיין שלימות באשטייט אין „החכמה¹¹ והמעשה\". ד. ה. אז ער זאל שטייגן אין חכמה און השגה ביז צום תכלית: „החכמה אלקית\" — „לצייר לנפשו אחדות הקב\"ה¹²\", און אלע איבעריקע חכמות זיינען נאר א צוגרייטונג בכדי מ'זאל שפעטער צוקומען צו ידיעה אלקית; און „המעשה\" — ניט זיין שטוף בתענוגים — סור מרע, און מתקן זיין די מדות וכו' זיי זאלן זיין ווי עס דארף צו זיין — ועשה טוב.\nאון נאך דעם אריכות הביאור אין דערויף, פירט אויס דער רמב\"ם, אז בשעת מ'וועט זיך מתבונן זיין און לערנען פון דברי חז\"ל די צווי אויבנדערמאנטע ענינים „חכמה ומעשה\", דעמאלט וועט מען וויסן די ריכטיקייט פון מרז\"ל „אין לו להקב\"ה בעולמו אלא ארבע אמות של הלכה\"¹³.\nדארף מען פארשטיין:\nא) ווי אזוי ווערט אויפגעקלערט די מעלה מיוחדת פון „ד' אמות של הלכה\" דורך די צווי ענינים פון „חכמה ומעשה\"? דער קישור פון „הלכה\" מיט „מעשה\" איז מובן ווייל דער תוכן פון הלכה איז בכדי לידע „את המעשה אשר יעשון\" ואלה „אשר לא תיעשנה\", און „תלמוד גדול שהתלמוד מביא לידי מעשה\"¹⁴; אבער וואס פאר א שייכות האט דער ענין פון חכמה — ביז צו לידע „אחדות הקב\"ה\" — צום ענין פון הלכה¹⁵?",[["9","9","בהקדמתו לפיהמ\"ש ד\"ה אחר כן. ולהעיר שהנדפס בש\"ס שלנו שזוהי הקדמה „מסדר זרעים\" — צ\"ע שה\"ז הקדמת כללות פיהמ\"ש. ואם מפני שסמכו לו — ה\"ז סמוך למס' ברכות. וראה תרגומו של קאפאח."],["10","10","ברכות ח, א."],["11","11","כמה פעמים לפני זה מובא הל' „דעת\" (ולא „חכמה\") — וצ\"ע אם דייק המתרגם בזה."],["12","12","גם מרמב\"ם זה מובן גודל הכרח לימוד פנימיות התורה שהיא חכמה האלקית, שע\"י דוקא אפשר „לצייר לנפשו אחדות הקב\"ה\" (נוסף על המפורש בספר היד החזקה (הל' יסוה\"ת פ\"ב ה\"ב): והאיך היא הדרך לאהבתו ויראתו בשעה שיתבוננו וכו')."],["13","13","בתרגומו של קאפאח: „וכיון שמדבריהם ע\"ה אנו לומדים שני הדברים הללו כלומר החכמה והמעשה ממה שביארו וממה שרמזו בצדק אמרו אין לו להקב\"ה בעולמו כו'\". ולפי פשוטו הכוונה שמלימוד תושבע\"פ מגיעים לב' ענינים אלו. אבל עדיין חסר ביאור איך מגיעים ואיפה נרמז תכלית החכמה ידיעת אלקות ואחדות הבורא וכו', וכדלקמן בפנים."],["14","14","קדושין מ, ב. ב\"ק יז, א."],["15","15","גם צלה\"ב מה שמקשה בהתחלת דבריו „ובזמן שם ועבר ואחריו שלא היתה שם הלכה הנוכל לומר שאין להקב\"ה חלק בעולם כלל\" — והרי בזמן שם ועבר הי' „בימד\"ר של שם ובימד\"ר של עבר\" וכמדרז\"ל עה\"פ (תולדות כה, כז) „יושב אהלים\". ובע\"ז (לו, ב): בב\"ד של שם גזרו כו'. — ולהעיר מרמב\"ם הל' ע\"ז פ\"א ה\"ב. מו\"נ ח\"ב פל\"ט. וארז\"ל (יומא כח, ב) מימיהן של אבותינו לא פרשה ישיבה כו' אברהם אבינו זקן ויושב בישיבה כו' יצחק אבינו זקן כו'."]]]]});
